export const CARETARO_BASENAMES = {"M00":"바보","M01":"마법사","M02":"고위여사제","M03":"여황제","M04":"황제","M05":"교황","M06":"연인","M07":"전차","M08":"힘","M09":"은둔자","M10":"운명의수레바퀴","M11":"정의","M12":"매달린남자","M13":"죽음","M14":"절제","M15":"악마","M16":"탑","M17":"별","M18":"달","M19":"태양","M20":"심판","M21":"세계","W01":"완드에이스","W02":"완드2","W03":"완드3","W04":"완드4","W05":"완드5","W06":"완드6","W07":"완드7","W08":"완드8","W09":"완드9","W10":"완드10","W11":"완드페이지","W12":"완드기사","W13":"완드퀸","W14":"완드킹","C01":"컵에이스","C02":"컵2","C03":"컵3","C04":"컵4","C05":"컵5","C06":"컵6","C07":"컵7","C08":"컵8","C09":"컵9","C10":"컵10","C11":"컵페이지","C12":"컵기사","C13":"컵여왕","C14":"컵킹","S01":"소드에이스","S02":"소드2","S03":"소드3","S04":"소드4","S05":"소드5","S06":"소드6","S07":"소드7","S08":"소드8","S09":"소드9","S10":"소드10","S11":"소드페이지","S12":"소드기사","S13":"소드퀸","S14":"소드킹","P01":"펜타클에이스","P02":"펜타클2","P03":"펜타클3","P04":"펜타클4","P05":"펜타클5","P06":"펜타클6","P07":"펜타클7","P08":"펜타클8","P09":"펜타클9","P10":"펜타클10","P11":"펜타클페이지","P12":"펜타클기사","P13":"펜타클퀸","P14":"펜타클킹"};
export const MASTER_READING_CARDS = {"M00":{"name":"바보","number":0,"arcana":"major","suit":"major","element":"spirit","u":{"line":"절벽 끝에서 가벼운 발걸음으로 새 길을 향해 나서는 순간이에요.","core":"계산보다 마음이 먼저 움직이는, 순수한 시작의 카드예요. 결과를 다 알지 못해도 첫발을 내딛는 용기가 지금의 힘이에요.","mind":"지금 당신의 마음은 기대와 설렘으로 가볍지만, 근거보다 감정이 앞서 있어 방향이 흔들릴 수 있어요.","daily":"오늘은 익숙한 틀에서 한 걸음 벗어나 보세요. 작은 새로움이 뜻밖의 활력을 줘요.","love":"관계에서 아무런 조건 없이 마음이 열리는 시기예요.","people":"격식보다 진심이 통하는 관계예요. 서로에게 아직 규칙이 없어 자유롭지만, 그래서 방향을 함께 정하는 대화가 필요해요.","reunion":"계산보다 마음이 먼저 움직이는, 순수한 시작의 카드예요. 결과를 다 알지 못해도 첫발을 내딛는 용기가 지금의 힘이에요.","career":"새로운 분야나 도전에 뛰어들기 좋은 때예요. 경험 부족을 두려워하기보다 배우려는 자세가 길을 열어요.","money":"새로운 수입원이나 시도가 열리지만, 아직 검증되지 않았으니 큰 자금을 한 번에 걸지는 마세요.","advice":"완벽한 준비를 기다리기보다, 지금 할 수 있는 첫걸음을 가볍게 내딛으세요. 방향은 걸으며 다듬으면 돼요.","caution":"설렘에 취해 현실 조건을 아예 무시하면, 도약이 무모한 추락으로 바뀔 수 있어요.","words":["새로운 시작","순수한 도약","가능성"]},"r":{"line":"발밑을 살피지 않아 헛디딜 뻔한, 준비 없는 출발의 순간이에요.","core":"시작하고 싶은 마음은 크지만 준비와 현실 감각이 따라오지 못한 상태예요. 무모함과 회피 사이에서 방향을 잃기 쉬워요.","mind":"지금 마음은 들뜸과 불안이 뒤섞여, 시작하고 싶으면서도 발을 못 떼는 상태예요.","daily":"오늘은 즉흥적인 결정을 잠시 미루고, 기본을 점검하는 편이 안전해요.","love":"설렘만 좇다 상대의 진심이나 현실 조건을 놓치기 쉬운 시기예요. 즉흥적인 결정이 관계를 흔들 수 있어요.","people":"책임을 지지 않으려는 마음이 관계를 가볍게 만들 수 있어요. 자유와 무책임을 혼동하지 않는 것이 중요해요.","reunion":"다시 시작하고 싶은 충동은 있지만 같은 실수를 반복할 위험이 커요. 감정만으로 움직이기 전에 무엇이 정말 달라졌는지 확인하세요.","career":"충분히 검토하지 않은 도전은 위험해요. 열정만큼 계획과 안전장치를 갖추세요.","money":"충동적인 지출이나 검증 안 된 투자에 주의하세요. 지금은 벌이기보다 지키는 관리가 우선이에요.","advice":"떠나기 전에 최소한의 준비물부터 챙기세요. 용기와 무모함을 가르는 것은 딱 한 번의 현실 점검이에요.","caution":"'어떻게든 되겠지'라는 낙관이 반복되면, 같은 자리에서 넘어지는 일이 되풀이돼요.","words":["무모함","준비 부족","회피"]}},"M01":{"name":"마법사","number":1,"arcana":"major","suit":"major","element":"spirit","u":{"line":"필요한 도구를 모두 손에 쥐고, 뜻을 현실로 옮기는 마법사의 자리예요.","core":"원하는 것을 실제로 만들어낼 힘과 자원이 지금 당신에게 모두 갖춰져 있어요. 남은 것은 집중과 실행뿐이에요.","mind":"지금 당신은 목표가 뚜렷하고 자신감이 살아 있어, 마음먹은 대로 밀고 나가려는 상태예요.","daily":"오늘은 미뤄둔 일 하나를 실제로 착수하기 좋은 날이에요. 시작하는 순간 흐름이 열려요.","love":"먼저 다가가 관계의 흐름을 주도할 수 있는 시기예요. 마음을 명확한 말과 행동으로 표현할 때 상대의 반응이 살아나요.","people":"관계를 원하는 방향으로 이끌 주도권이 당신에게 있어요. 진심을 구체적인 행동으로 보여줄 때 신뢰가 쌓여요.","reunion":"재회를 스스로 만들어갈 수 있는 흐름이에요. 다만 진심 어린 접근인지, 상대를 움직이려는 기술인지 스스로 구분해야 해요.","career":"실력을 발휘해 성과를 낼 최적의 시기예요. 아이디어를 실행으로 옮기면 인정과 기회가 따라와요.","money":"실행이 곧 결과가 되는 흐름이에요.","advice":"필요한 것은 이미 다 갖춰져 있어요. 망설이지 말고 지금 가진 것으로 첫 행동을 만드세요.","caution":"능력을 남을 조종하거나 겉을 꾸미는 데 쓰면, 힘은 오래가지 못하고 신뢰를 잃어요.","words":["의지","실행력","집중"]},"r":{"line":"도구는 많지만 정작 하나도 제대로 쓰지 못하고 흩어지는 자리예요.","core":"능력과 의욕은 있으나 집중이 흩어져 실행으로 이어지지 못하는 상태예요. 말과 행동이 어긋나기 쉬워요.","mind":"지금 마음은 하고 싶은 것은 많지만 무엇부터 손대야 할지 몰라 산만한 상태예요.","daily":"오늘은 여러 일을 동시에 벌이기보다, 딱 하나를 골라 끝내는 데 집중하세요.","love":"마음은 있는데 표현이 겉돌거나, 진심 없이 기술만 앞세워 관계가 공허해질 수 있어요.","people":"약속과 행동이 일치하지 않아 신뢰가 흔들려요. 말보다 실제로 지키는 것에 무게를 두세요.","reunion":"다시 다가가려는 시도가 진심보다 조급함에서 나오면 역효과예요. 상대를 설득하려 들기보다 스스로 달라진 모습을 먼저 보이세요.","career":"역량을 제대로 못 쓰거나 방향을 잘못 잡아 노력이 성과로 이어지지 않을 수 있어요. 우선순위부터 다시 세우세요.","money":"계획 없이 벌이기만 하면 자원이 새어나가요. 벌이기 전에 흐름을 정리하는 것이 먼저예요.","advice":"능력이 없는 게 아니라 흩어져 있을 뿐이에요.","caution":"자신을 실제보다 크게 포장하거나 남을 속이려는 유혹에 흔들리지 마세요. 결국 자기 발목을 잡아요.","words":["산만함","미실행","자기기만"]}},"M02":{"name":"여사제","number":2,"arcana":"major","suit":"major","element":"spirit","u":{"line":"말없이 앉아 겉으로 드러나지 않은 진실을 꿰뚫어 보는 여사제의 자리예요.","core":"겉으로 드러난 것 너머, 아직 말해지지 않은 진실을 감지하는 카드예요. 머리로 따지기보다 내면의 직관을 신뢰할 때예요.","mind":"지금 당신의 마음은 겉으로 표현하지 않은 감정과 예감으로 가득 차 있어요. 그 직관이 꽤 정확해요.","daily":"오늘은 결정을 서두르지 말고, 조용히 자기 내면의 소리에 귀 기울여 보세요.","love":"말로 다 표현되지 않은 감정이 흐르는 시기예요. 서두르지 말고 상대의 침묵과 분위기 속 진심을 읽어보세요.","people":"겉으로 조용해도 그 아래 깊은 감정이 오가고 있어요. 답을 재촉하기보다 흐름을 지켜보는 지혜가 필요해요.","reunion":"아직 드러나지 않은 감정의 여지가 남아 있어요. 성급히 확인하려 하기보다 상대가 스스로 마음을 열 때까지 기다리는 편이 좋아요.","career":"표면의 정보만으로 판단하지 마세요. 아직 공개되지 않은 흐름을 감지하는 직관이 중요한 시기예요.","money":"겉으로 드러난 조건 이면을 살펴야 해요. 왠지 꺼려지는 느낌이 든다면 그 직관을 무시하지 마세요.","advice":"답은 이미 당신 안에 있어요. 남의 말이나 겉모습에 흔들리지 말고 조용히 내면의 신호를 신뢰하세요.","caution":"느낌으로 알면서도 애써 외면하면, 나중에 '알고 있었는데'라는 후회가 남아요.","words":["직관","내면의 목소리","숨은 진실"]},"r":{"line":"내면의 목소리를 스스로 막아버려, 진실이 흐려지는 자리예요.","core":"분명히 감지되는 직관을 애써 무시하거나, 감춰진 진실이 관계를 흐리게 하는 상태예요. 내면과 겉이 단절되어 있어요.","mind":"지금 마음은 자기 감정을 스스로도 잘 모르는 혼란 상태예요. 느낌을 억누르다 보니 판단이 흐려졌어요.","daily":"오늘은 억눌러온 감정을 조용히 들여다보는 시간이 필요해요. 외면할수록 마음이 무거워져요.","love":"속마음을 감추거나 상대의 신호를 오해하면서 감정이 엉켜요. 느낌을 억누르기보다 솔직하게 마주할 때예요.","people":"숨기는 것이 많아 서로의 진심이 닿지 않아요. 비밀이나 오해가 관계를 무겁게 만들고 있어요.","reunion":"직관은 '아직 아니다' 혹은 '더 봐야 한다'고 말하는데, 조급함이 그 신호를 덮고 있을 수 있어요.","career":"겉으로 드러난 정보만 믿었다가 숨은 변수에 부딪힐 수 있어요. 꺼림칙한 신호를 무시하지 마세요.","money":"설명되지 않는 불안이 든다면 그것이 신호예요. 확인되지 않은 정보에 휩쓸리지 마세요.","advice":"느낌을 무시하지 마세요. 조용히 내면의 목소리를 다시 듣고, 진실을 회피하는 대신 마주하세요.","caution":"직감을 계속 억누르면 판단이 흐려지고, 뒤늦게 후회할 선택을 하기 쉬워요.","words":["직관 무시","숨겨진 비밀","혼란"]}},"M03":{"name":"여황제","number":3,"arcana":"major","suit":"major","element":"spirit","u":{"line":"풍요로운 들판에서 넉넉한 마음으로 만물을 품는 여황제의 자리예요.","core":"마음도 현실도 넉넉하게 채워지는, 풍요와 돌봄의 카드예요. 무리하지 않아도 자연스럽게 자라나는 흐름 속에 있어요.","mind":"지금 당신의 마음은 여유롭고 넉넉해, 상대와 상황을 있는 그대로 품을 수 있는 상태예요.","daily":"오늘은 자신을 넉넉히 돌보고, 주변에도 따뜻함을 나눠보세요. 편안함이 곧 힘이 돼요.","love":"따뜻한 애정이 오가며 관계가 깊고 안정적으로 자라는 시기예요. 주는 사랑과 받는 사랑이 조화로워요.","people":"서로를 편안하게 품어주는 성숙한 관계예요. 있는 그대로를 받아들일 때 정서적 풍요가 커져요.","reunion":"감정의 문이 따뜻하게 열려 있어요. 다그치지 않고 넉넉한 마음으로 다가가면 다시 이어질 여지가 있어요.","career":"무리하지 않고 꾸준히 키워온 것이 성과가 돼요.","money":"안정적으로 재물이 늘어나는 흐름이에요. 여유가 생겼다면 나누고 재투자하는 것도 좋아요.","advice":"억지로 밀어붙이기보다, 자연스럽게 자라도록 넉넉히 품어주세요. 풍요는 조급함이 아니라 여유에서 와요.","caution":"지나친 돌봄이 상대를 숨 막히게 하거나, 남을 챙기다 정작 자신을 소홀히 할 수 있어요.","words":["풍요","돌봄","감정적 성장"]},"r":{"line":"품는 힘이 과하거나 메말라, 흐름이 막힌 자리예요.","core":"돌봄이 과잉이 되어 상대를 옭아매거나, 반대로 자신을 돌보지 못해 정서가 메마른 상태예요. 성장의 흐름이 정체되어 있어요.","mind":"지금 마음은 남을 챙기느라 지쳐 있거나, 채워지지 않는 허전함으로 예민해진 상태예요.","daily":"오늘은 남보다 자신을 먼저 돌보세요. 스스로를 채워야 남에게도 나눌 힘이 생겨요.","love":"사랑이 집착이나 지나친 헌신으로 변질될 수 있어요. 주는 만큼 자신도 채워야 관계가 건강해져요.","people":"한쪽의 과한 희생이나 의존이 균형을 무너뜨려요. 돌봄과 통제의 경계를 다시 세우세요.","reunion":"감정에만 매달리면 오히려 부담이 돼요. 그리움을 앞세우기보다 서로에게 여백을 주는 편이 나아요.","career":"아이디어가 막히거나 성과가 정체될 수 있어요. 무리하게 짜내기보다 재충전이 먼저예요.","money":"과소비나 남을 위한 과한 지출로 재정이 새어나갈 수 있어요. 자신의 곳간부터 챙기세요.","advice":"다 품으려 하지 마세요. 자신을 먼저 채우는 것이 이기심이 아니라, 오래 돌보기 위한 지혜예요.","caution":"헌신이 지나치면 상대는 부담을, 당신은 소진을 얻어요. 사랑과 통제를 혼동하지 마세요.","words":["과잉 돌봄","정체","의존"]}},"M04":{"name":"황제","number":4,"arcana":"major","suit":"major","element":"spirit","u":{"line":"단단한 옥좌에 앉아 질서와 기준으로 세상을 지탱하는 황제의 자리예요.","core":"명확한 기준과 책임감으로 현실의 토대를 세우는 카드예요. 감정보다 구조와 원칙이 흐름을 안정시켜요.","mind":"지금 당신은 상황을 통제하고 질서를 잡으려는 의지가 강해요. 책임감이 큰 만큼 어깨도 무거워요.","daily":"오늘은 미뤄둔 일을 체계적으로 정리하기 좋아요. 틀을 잡으면 마음도 안정돼요.","love":"관계에 안정과 신뢰의 틀이 잡히는 시기예요. 든든하게 지켜주는 사람, 혹은 진지하게 관계를 책임지려는 태도가 핵심이에요.","people":"약속과 규칙이 분명할 때 관계가 단단해져요. 감정에만 기대지 말고 현실적인 합의를 세우세요.","reunion":"재회하려면 감정 호소보다 '달라진 태도와 책임'을 보여주는 것이 효과적이에요.","career":"체계와 리더십을 발휘해 성과를 다질 시기예요. 규칙을 세우고 책임을 지는 태도가 인정받아요.","money":"계획적이고 보수적인 관리가 재정을 안정시켜요. 즉흥적 지출보다 원칙 있는 운용이 유리해요.","advice":"감정에 휘둘리지 말고, 지킬 원칙과 기준부터 분명히 세우세요. 안정은 즉흥이 아니라 구조에서 와요.","caution":"질서가 지나치면 경직과 통제가 돼요. 원칙을 고집으로 밀어붙이면 관계가 딱딱해져요.","words":["질서","안정","책임"]},"r":{"line":"기준이 무너졌거나, 반대로 지나치게 굳어 숨 막히는 자리예요.","core":"통제욕이 과해져 고집과 억압으로 흐르거나, 반대로 중심이 무너져 불안정해진 상태예요. 유연함과 원칙의 균형이 깨져 있어요.","mind":"지금 마음은 모든 걸 통제하려다 오히려 불안하고 경직된 상태예요. 뜻대로 안 될 때 조급함이 커요.","daily":"오늘은 '내 방식이 옳다'는 고집을 잠시 내려놓아 보세요. 유연함이 문제를 풀어요.","love":"한쪽이 관계를 지나치게 통제하려 하거나, 책임을 회피해 신뢰가 흔들려요. 규칙과 자유의 균형이 필요해요.","people":"고집이나 권위적 태도가 갈등을 키워요. 상대를 통제하려는 마음을 내려놓아야 관계가 풀려요.","reunion":"억지로 상황을 통제하려 들수록 상대는 멀어져요. 힘으로 붙잡기보다 여유를 보여주는 편이 나아요.","career":"권위나 규칙을 둘러싼 갈등이 생길 수 있어요. 힘으로 누르기보다 조율하는 리더십이 필요해요.","money":"지나친 인색함이나 반대로 통제 없는 지출로 균형이 깨질 수 있어요. 기준을 현실에 맞게 조정하세요.","advice":"통제하려 할수록 어긋나요. 지킬 것과 놓아줄 것을 구분하고, 힘 대신 신뢰로 이끄세요.","caution":"원칙이 고집이 되고 리더십이 강압이 되는 순간, 사람들은 곁을 떠나기 시작해요.","words":["경직","통제욕","고집"]}},"M05":{"name":"교황","number":5,"arcana":"major","suit":"major","element":"spirit","u":{"line":"오랜 전통과 가르침으로 사람들을 이어주는 교황의 자리예요.","core":"신뢰와 약속, 검증된 방식이 힘을 발휘하는 카드예요. 혼자 튀기보다 함께 지켜온 가치와 질서 안에서 안정을 찾아요.","mind":"지금 당신은 안정과 신뢰를 중시하며, 검증된 길을 따르고 싶어 하는 상태예요.","daily":"오늘은 조언을 구하거나 배움의 자리에 서기 좋아요. 경험 있는 사람의 지혜가 길을 밝혀요.","love":"진지하고 안정적인 관계로 나아가는 시기예요. 공식적인 약속이나 서로의 가치관이 통하는지가 중요해져요.","people":"신뢰의 틀과 공유된 가치가 관계를 지탱해요. 즉흥적 끌림보다 오래 함께할 수 있는 기반을 확인하세요.","reunion":"진지한 태도와 신뢰 회복이 재회의 열쇠예요.","career":"조직의 규범이나 멘토의 도움이 힘이 되는 시기예요. 검증된 방식과 협력이 성과를 안정시켜요.","money":"안정적이고 정통적인 방법이 유리해요. 검증되지 않은 편법보다 신뢰할 수 있는 경로를 택하세요.","advice":"혼자 판단하기보다 신뢰할 수 있는 조언과 검증된 방식을 따르세요. 약속을 지키는 태도가 신뢰를 만들어요.","caution":"형식과 체면에만 매이면 진심이 가려져요. 규범이 목적을 앞서지 않도록 하세요.","words":["신뢰","전통","약속"]},"r":{"line":"겉의 형식만 남고 진심은 빠져나간, 혹은 낡은 틀에 반발하는 자리예요.","core":"형식과 위선이 진심을 가리거나, 기존 방식에 반발해 자기만의 길을 찾으려는 상태예요. 신뢰의 틀이 흔들리고 있어요.","mind":"지금 마음은 기존의 규칙이나 남들의 기대에 답답함을 느끼며, 자기만의 방식을 찾고 싶어 해요.","daily":"오늘은 '원래 그런 것'이라는 틀을 의심해 보세요. 자기 신념에 맞는 선택이 더 편해요.","love":"겉으로만 관계를 유지하거나, 진심 없는 약속이 신뢰를 갉아먹을 수 있어요. 형식보다 진짜 마음을 확인하세요.","people":"가치관 차이나 약속 위반으로 신뢰에 금이 가요. 남들의 기준이 아니라 두 사람의 진심이 기준이 되어야 해요.","reunion":"낡은 방식 그대로 다가가면 통하지 않아요. 형식적인 화해보다 진심 어린 변화가 필요해요.","career":"낡은 규범이 발목을 잡거나 위선적인 관계에 실망할 수 있어요. 형식보다 본질에 집중하세요.","money":"겉만 그럴듯한 제안이나 신뢰가 의심스러운 거래를 조심하세요. 검증이 부족한 약속을 경계해야 해요.","advice":"형식에 얽매이지 말고 본질을 보세요. 남의 기준이 아닌 자기 가치에 맞는 길을 택하되, 신뢰만은 지키세요.","caution":"진심 없는 약속이나 위선적인 태도는 결국 신뢰를 무너뜨려요.","words":["형식주의","관습 거부","위선"]}},"M06":{"name":"연인","number":6,"arcana":"major","suit":"major","element":"spirit","u":{"line":"서로를 향해 마음을 여는 두 사람, 진실된 결합과 선택의 자리예요.","core":"마음이 깊이 통하고 가치가 맞아 하나로 이어지는 카드예요. 동시에 무엇을 진심으로 원하는지 선택해야 하는 순간이기도 해요.","mind":"지금 당신의 마음은 상대에게 진심으로 향해 있지만, 동시에 어떤 선택을 할지 고민하는 상태예요.","daily":"오늘은 마음이 진짜 원하는 것을 따라 선택해 보세요. 진심에서 나온 결정이 후회를 줄여요.","love":"서로에게 진심으로 끌리며 관계가 깊어지는 시기예요. 표면적 매력을 넘어 가치관이 통하는 결합이에요.","people":"진심이 통하는 조화로운 관계예요. 다만 관계의 방향에 대한 중요한 선택이 필요할 수 있어요.","reunion":"감정의 끌림이 여전히 살아 있어요. 다만 '왜 다시 만나려는지' 마음의 진짜 이유를 분명히 하는 것이 먼저예요.","career":"함께할 파트너나 방향을 선택하는 시기예요. 조건보다 가치가 맞는 쪽을 택할 때 오래가요.","money":"중요한 재정적 선택 앞에 섰어요. 눈앞의 이익보다 자신의 가치와 맞는 결정을 하세요.","advice":"머리로 재기보다 무엇을 진심으로 원하는지 물으세요. 가치가 맞는 선택이 오래가는 결합을 만들어요.","caution":"선택을 미루거나 조건만 따지면, 정작 마음이 원하는 것을 놓칠 수 있어요.","words":["선택","결합","가치 일치"]},"r":{"line":"서로 다른 곳을 바라보며 어긋나는, 선택을 회피하는 자리예요.","core":"가치관이 어긋나거나 선택을 미루면서 관계가 삐걱대는 상태예요. 진심과 조건 사이에서 갈등이 커요.","mind":"지금 마음은 선택 앞에서 갈팡질팡하며, 어느 쪽도 확신하지 못하는 상태예요.","daily":"오늘은 미뤄둔 선택 하나를 마주해 보세요. 결정하지 않는 것도 결국 하나의 선택이에요.","love":"마음은 있지만 가치관 차이나 우유부단함으로 관계가 흔들려요. 진짜 원하는 것을 회피하고 있을 수 있어요.","people":"서로 다른 방향을 보며 갈등이 쌓여요. 무엇이 어긋났는지 솔직히 마주해야 해요.","reunion":"다시 만나도 같은 가치 차이가 반복될 수 있어요. 감정만으로 결정하기 전에 근본 문제를 직시하세요.","career":"잘못된 선택이나 가치가 안 맞는 협업으로 갈등이 생길 수 있어요. 무엇을 우선할지 다시 정하세요.","money":"유혹적인 제안이나 성급한 결정에 흔들리기 쉬워요. 진짜 필요한 것과 욕심을 구분하세요.","advice":"회피는 답이 아니에요. 무엇이 어긋났는지 솔직히 보고, 진심과 가치에 맞는 선택을 내리세요.","caution":"선택을 미룰수록 갈등은 커지고, 눈앞의 유혹에 흔들리면 정작 중요한 것을 잃어요.","words":["가치 불일치","갈등","우유부단"]}},"M07":{"name":"전차","number":7,"arcana":"major","suit":"major","element":"spirit","u":{"line":"고삐를 굳게 쥐고 상반된 힘을 하나로 몰아 전진하는 전차의 자리예요.","core":"강한 의지로 방향을 정하고 밀고 나가 승리하는 카드예요. 상반된 힘을 스스로 통제하며 목표를 향해 나아가요.","mind":"지금 당신은 목표가 뚜렷하고 의지가 강해, 밀어붙여서라도 원하는 걸 이루려는 상태예요.","daily":"오늘은 목표 하나에 집중해 강하게 밀어붙이기 좋은 날이에요. 결단이 흐름을 만들어요.","love":"적극적으로 관계를 이끌어 원하는 방향으로 나아가는 시기예요. 망설임 대신 분명한 의지가 상대의 마음을 움직여요.","people":"목표를 향해 함께 나아가는 추진력 있는 관계예요. 다만 속도를 상대와 맞추는 조율이 필요해요.","reunion":"의지를 갖고 다가가면 흐름을 만들 수 있어요. 단, 밀어붙이는 힘과 상대의 속도 사이 균형이 중요해요.","career":"의지와 집중으로 성과를 쟁취할 시기예요.","money":"적극적인 실행이 결과를 만들어요. 목표를 정하고 자원을 집중하면 재물의 흐름이 열려요.","advice":"방향을 분명히 정하고, 상반된 마음을 하나로 모아 밀고 나가세요. 승리는 흔들리지 않는 의지에서 와요.","caution":"속도에만 취해 주변을 무시하면, 통제를 잃고 방향까지 잃을 수 있어요.","words":["의지","추진력","통제"]},"r":{"line":"고삐가 풀려 서로 다른 말이 제멋대로 달리는, 통제를 잃은 자리예요.","core":"의지는 있지만 방향을 잃었거나, 상반된 마음이 부딪혀 앞으로 나아가지 못하는 상태예요. 조급함이 통제력을 흔들어요.","mind":"지금 마음은 여러 방향으로 끌려다니며, 무엇을 향해 가야 할지 통제력을 잃은 상태예요.","daily":"오늘은 여러 일에 힘을 분산하기보다, 잠시 멈춰 방향부터 정리하세요.","love":"관계를 밀어붙이려다 오히려 어긋나거나, 방향을 못 정해 제자리걸음이에요. 힘보다 조율이 필요해요.","people":"서로 다른 방향으로 힘을 쓰다 갈등이 커져요. 속도와 목표를 다시 맞춰야 해요.","reunion":"조급하게 밀어붙이면 역효과예요. 통제하려 들기보다 흐름에 여유를 두세요.","career":"의욕은 앞서지만 방향이 흐트러져 성과가 나지 않을 수 있어요. 속도보다 방향 점검이 먼저예요.","money":"조급한 결정이나 무리한 추진이 손실을 부를 수 있어요. 속도를 늦추고 흐름을 정비하세요.","advice":"밀어붙이기 전에 방향부터 점검하세요. 상반된 마음을 정리하지 않으면 힘만 낭비돼요.","caution":"통제를 잃은 추진력은 사고로 이어져요. 조급함이 클수록 한 박자 멈추세요.","words":["통제 상실","방향 상실","조급함"]}},"M08":{"name":"힘","number":8,"arcana":"major","suit":"major","element":"spirit","u":{"line":"사나운 사자를 힘이 아닌 부드러운 손길로 다스리는 힘의 자리예요.","core":"강압이 아닌 인내와 부드러움으로 어려움을 다스리는 카드예요. 진짜 힘은 감정을 억누르지 않고 품어내는 데서 나와요.","mind":"지금 당신은 흔들려도 무너지지 않는 내면의 힘으로, 감정을 다스리며 상황을 품고 있어요.","daily":"오늘은 화가 나는 순간에도 한 박자 참아보세요. 부드러운 대응이 상황을 부드럽게 만들어요.","love":"조급함 없이 따뜻한 인내로 관계를 이끄는 시기예요. 강요하지 않는 부드러움이 상대의 마음을 열어요.","people":"감정의 파도를 서로 품어주며 신뢰가 깊어지는 관계예요. 부드러움 속의 단단함이 관계를 지켜요.","reunion":"조급함을 내려놓고 따뜻하게 다가갈 때 마음의 문이 열려요. 힘이 아니라 인내가 열쇠예요.","career":"압박 속에서도 침착함을 유지하며 신뢰를 얻는 시기예요. 강하게 밀기보다 꾸준히 버티는 힘이 통해요.","money":"조급한 결정 대신 인내심 있는 관리가 유리해요. 흔들려도 원칙을 지키면 회복돼요.","advice":"힘으로 누르지 말고 인내로 품으세요. 감정을 다스리는 부드러운 용기가 진짜 강함이에요.","caution":"참는 것과 억누르는 것은 달라요.","words":["내면의 힘","인내","부드러운 용기"]},"r":{"line":"사자에게 휘둘려 힘을 잃은, 혹은 억눌린 감정이 터지기 직전의 자리예요.","core":"자신감이 무너졌거나 감정을 다스리지 못해 휘둘리는 상태예요. 억눌러온 것이 폭발하거나 무력감에 빠지기 쉬워요.","mind":"지금 마음은 자신감이 떨어지고 감정 조절이 어려워, 작은 일에도 크게 흔들리는 상태예요.","daily":"오늘은 감정이 격해지면 잠시 멈추고 심호흡하세요. 자기 자신에게 조금 더 관대해질 필요가 있어요.","love":"감정 기복이 커져 관계가 흔들리거나, 자신감을 잃어 위축될 수 있어요. 마음을 다잡는 시간이 필요해요.","people":"감정을 억누르다 폭발하거나, 자기 의심이 관계를 흔들어요. 감정을 솔직하게 다루는 연습이 필요해요.","reunion":"조급함이나 불안이 앞서 감정을 그르칠 수 있어요. 마음을 먼저 다스린 뒤에 다가가세요.","career":"압박을 견디지 못해 실수하거나 자신감을 잃을 수 있어요. 무리하지 말고 페이스를 회복하세요.","money":"불안이나 조급함에 휘둘린 결정을 조심하세요. 감정이 아닌 사실로 판단해야 해요.","advice":"억누르지 말고 감정을 인정하되, 그것에 휘둘리지는 마세요. 자기 자신을 다독이는 것이 회복의 시작이에요.","caution":"참기만 하다 터뜨리거나, 자기 의심에 빠져 스스로를 갉아먹지 않도록 하세요.","words":["자신감 상실","감정 폭발","무력감"]}},"M09":{"name":"은둔자","number":9,"arcana":"major","suit":"major","element":"spirit","u":{"line":"홀로 등불을 들고 내면의 길을 비추며 걷는 은둔자의 자리예요.","core":"밖의 소음에서 물러나 홀로 답을 찾는 성찰의 카드예요. 조급히 움직이기보다 고요히 자신을 들여다볼 때예요.","mind":"지금 당신은 밖보다 안을 향해 있으며, 조용히 자신의 진짜 마음을 찾고 싶어 해요.","daily":"오늘은 혼자만의 조용한 시간을 가져보세요. 고요함 속에서 답이 떠올라요.","love":"관계에서 한 걸음 물러나 자신의 마음을 정리하는 시기예요. 혼자만의 시간이 관계를 더 명료하게 만들어요.","people":"잠시 거리를 두고 서로를 돌아볼 필요가 있는 관계예요. 침묵이 냉담이 아니라 성찰일 수 있어요.","reunion":"지금은 다가가기보다 각자 정리하는 시간이 필요해요. 조급히 연락하기보다 스스로의 마음을 먼저 아세요.","career":"혼자 깊이 파고들거나 방향을 재점검하기 좋은 시기예요. 남과 비교하지 말고 자기 속도로 나아가세요.","money":"성급한 결정보다 신중한 검토가 유리해요. 조용히 계획을 다듬을 때예요.","advice":"답을 밖에서 찾지 마세요. 잠시 물러나 홀로 자신을 들여다볼 때 진짜 방향이 보여요.","caution":"거리 두기가 길어지면 자기 이해가 아니라 자기 의심으로 변질될 수 있어요.","words":["내면 탐색","거리 두기","자기 성찰"]},"r":{"line":"등불이 꺼진 채 홀로 남겨진, 고립되고 길을 잃은 자리예요.","core":"성찰이 지나쳐 고립되거나, 반대로 자신을 마주하기 싫어 회피하는 상태예요. 외로움과 단절이 깊어지고 있어요.","mind":"고립이 안전감이 아니라 자기비난 통로가 되는 시기에는 외부 검증이 필요해요.","daily":"오늘은 혼자 웅크리기보다, 믿을 수 있는 사람에게 마음을 열어보세요.","love":"지나친 거리 두기나 단절이 관계를 멀어지게 해요. 혼자 있는 것과 외면하는 것은 달라요.","people":"소통이 끊겨 서로 고립되어 있어요. 성찰을 핑계로 회피하고 있는 건 아닌지 돌아보세요.","reunion":"계속 물러나 있기만 하면 관계는 자연히 멀어져요. 필요하다면 먼저 손 내밀 용기가 필요해요.","career":"혼자 끌어안다 지치거나 방향을 잃을 수 있어요. 필요하면 조언과 협력을 구하세요.","money":"지나친 신중함이 기회를 놓치게 할 수 있어요. 고민만 하지 말고 조언을 구해 결정하세요.","advice":"정답을 찾으려 하지 말고 도움 요청 문장을 먼저 실행하세요.","caution":"혼자 만든 결론으로 상대 반응을 단정하면 불안 루프가 심해져요.","words":["고립","자기 의심","내면 길 잃음"]}},"M10":{"name":"운명의 수레바퀴","number":10,"arcana":"major","suit":"major","element":"spirit","u":{"line":"쉼 없이 도는 운명의 수레바퀴, 국면이 크게 전환되는 자리예요.","core":"예상치 못한 변화와 전환이 찾아오는 카드예요. 흐름이 바뀌는 지금, 붙잡기보다 변화의 리듬에 올라타는 것이 지혜예요.","mind":"지금 당신은 변화의 한가운데 있어, 흐름이 어디로 향할지 기대 반 불안 반인 상태예요.","daily":"오늘은 뜻밖의 변화나 기회가 찾아올 수 있어요. 열린 마음으로 흐름을 받아들이세요.","love":"관계에 새로운 국면이 열리는 시기예요. 뜻밖의 계기로 흐름이 좋은 쪽으로 바뀔 수 있어요.","people":"관계의 흐름이 자연스럽게 전환되는 때예요. 변화를 두려워하지 말고 흐름에 몸을 맡겨보세요.","reunion":"타이밍이 무르익고 있어요. 억지로 만들기보다 흐름이 다시 이어지는 순간을 알아채는 것이 중요해요.","career":"흐름을 읽고 올라타면 큰 도약이 가능해요.","money":"재정 흐름이 좋은 쪽으로 바뀔 수 있어요. 다만 운에만 기대지 말고 타이밍을 활용하세요.","advice":"변화를 통제하려 하지 말고 흐름에 올라타세요. 좋은 타이밍을 알아채고 움직이는 것이 관건이에요.","caution":"운이 좋을 때 자만하면 다음 순환에서 크게 흔들려요.","words":["전환","순환","타이밍"]},"r":{"line":"수레바퀴가 나쁜 쪽으로 굴러, 같은 자리를 맴도는 악순환의 자리예요.","core":"흐름이 불리하게 돌거나, 같은 문제가 반복되는 악순환에 갇힌 상태예요. 변화에 저항할수록 더 지쳐요.","mind":"지금 마음은 아무리 애써도 제자리인 것 같은 답답함과 무력감에 눌려 있어요.","daily":"오늘은 뜻대로 안 되는 일이 있어도 조급해하지 마세요. 흐름이 바뀔 때까지 버티는 것도 지혜예요.","love":"관계가 나쁜 패턴을 반복하거나 흐름이 정체돼요. 같은 실수를 되풀이하고 있진 않은지 돌아보세요.","people":"반복되는 갈등의 고리를 끊지 못하고 있어요. 흐름을 바꾸려면 익숙한 패턴부터 깨야 해요.","reunion":"타이밍이 아직 맞지 않거나, 같은 결말로 돌아갈 위험이 있어요. 흐름이 바뀔 때까지 기다리는 편이 나아요.","career":"일이 지연되거나 반복되는 문제로 정체될 수 있어요. 안 풀리는 방식을 고집하지 말고 접근을 바꾸세요.","money":"예상 밖의 지출이나 불운한 흐름이 있을 수 있어요. 무리한 시도보다 안정적 관리가 우선이에요.","advice":"안 되는 것을 억지로 밀지 마세요. 반복되는 패턴을 끊고, 통제할 수 없는 것은 흐름에 맡기세요.","caution":"같은 방식을 고집하면 같은 결과가 반복돼요. 무력감에 갇히지 말고 작게라도 다르게 시도하세요.","words":["악순환","불운의 흐름","통제 불가"]}},"M11":{"name":"정의","number":11,"arcana":"major","suit":"major","element":"spirit","u":{"line":"저울과 칼을 들고 흐트러짐 없이 진실을 가늠하는 정의의 자리예요.","core":"원인과 결과가 정직하게 맞아떨어지는 균형의 카드예요. 감정보다 공정한 판단과 책임이 흐름을 바로잡아요.","mind":"관계에서 감정적 압박을 줄이기 위해 객관적 기준을 세우려는 심리가 작동해요.","daily":"오늘은 미뤄둔 책임이나 결정을 공정하게 처리하기 좋아요. 정직함이 마음을 가볍게 해요.","love":"관계에서 주고받음의 균형이 맞춰지는 시기예요. 서로에게 공정하고 정직할 때 신뢰가 단단해져요.","people":"책임과 진실이 관계의 기준이 돼요. 감정에 치우치지 않고 서로를 공평하게 대할 때 안정돼요.","reunion":"관계를 정직하게 되돌아볼 때예요. 잘잘못을 공정하게 인정하는 태도가 재회의 실마리가 돼요.","career":"공정한 평가와 정당한 결과가 따르는 시기예요. 계약이나 판단에서 정직함이 유리하게 작용해요.","money":"재정의 균형을 맞추고 정산할 때예요. 정직하고 투명한 처리가 신뢰와 이익을 가져와요.","advice":"상대를 설득하기 전에 내 기준 1가지를 문장으로 정리하세요. 기준이 분명하면 과잉 사과를 줄일 수 있어요.","caution":"자기 입장만 옳다고 여기면 균형이 깨져요. 상대의 몫도 공정하게 인정하세요.","words":["공정","기준","균형"]},"r":{"line":"저울이 한쪽으로 기울어, 진실이 왜곡되고 책임이 회피되는 자리예요.","core":"관계에서 공정성보다 분위기 유지가 앞서며, 스스로를 과하게 재판하는 흐름이 강해져요.","mind":"누군가 실망하는 기색이 보이면 사실을 확인하기 전에 '내가 잘못한 것 같다'는 생각이 먼저 올라올 수 있어요.","daily":"오늘은 회피해온 책임 하나를 마주해 보세요. 미룰수록 무게만 커져요.","love":"주고받음의 균형이 무너지거나, 한쪽이 책임을 회피해 관계가 불공정해져요. 정직함을 회복해야 해요.","people":"오해나 편향된 판단이 갈등을 키워요. 자기 입장만 고집하지 말고 공정하게 돌아보세요.","reunion":"잘못을 인정하지 않으면 관계는 회복되기 어려워요. 책임 회피를 멈추는 것이 먼저예요.","career":"불공정한 평가나 계약 문제에 주의하세요. 세부 조건을 꼼꼼히 확인하고 정직하게 처리해야 해요.","money":"재정 불균형이나 정산 문제가 생길 수 있어요. 대충 넘기지 말고 정확히 따져야 해요.","advice":"오늘은 사과 문장을 줄이고 사실 문장을 늘리세요. '내가 잘못했어' 대신 '나는 이렇게 이해했어'라고 말해 보세요.","caution":"나를 지키기 위한 경계 대신, 관계의 평온을 지키려는 자기희생이 반복될 수 있어요.","words":["불공정","자기판단","왜곡된 기준"]}},"M12":{"name":"매달린 사람","number":12,"arcana":"major","suit":"major","element":"spirit","u":{"line":"거꾸로 매달린 채 세상을 뒤집어 바라보는 매달린 사람의 자리예요.","core":"잠시 멈추고 관점을 바꿀 때 답이 보이는 카드예요. 억지로 밀어붙이는 대신 내려놓음으로써 새로운 시각을 얻어요.","mind":"지금 당신의 마음은 결정을 미룬 채, 상황을 다른 각도에서 이해하려 애쓰고 있어요.","daily":"오늘은 무언가를 억지로 진행하기보다, 잠시 멈춰 다른 시각으로 바라보세요.","love":"관계에서 잠시 멈추고 상대의 입장에서 바라보는 시기예요. 조급함을 내려놓을 때 마음이 보여요.","people":"지금은 행동보다 기다림과 이해가 필요한 때예요. 다른 각도에서 보면 갈등의 실마리가 풀려요.","reunion":"지금은 밀어붙일 때가 아니라 기다리며 관점을 바꿀 때예요. 내려놓을수록 오히려 답이 선명해져요.","career":"지금은 밀어붙이기보다 관망하며 새로운 접근을 찾을 때예요. 잠깐의 정지가 더 나은 방향을 줘요.","money":"지금은 큰 결정을 미루고 기다리는 편이 나아요. 상황을 다른 각도에서 검토할 시간이 필요해요.","advice":"억지로 밀지 마세요. 잠시 멈추고 관점을 바꾸면, 매달려 있던 문제가 다르게 보여요.","caution":"기다림이 목적을 잃으면 그저 정체가 돼요. 무엇을 위한 멈춤인지 잊지 마세요.","words":["멈춤","관점 전환","내려놓음"]},"r":{"line":"내려놓지 못한 채 매달려만 있는, 헛된 희생과 정체의 자리예요.","core":"내려놓아야 할 것을 붙들고 헛되이 희생하거나, 필요한 변화에 저항하는 상태예요. 멈춤이 정체로 굳어지고 있어요.","mind":"지금 마음은 놓지도 나아가지도 못한 채, 무의미한 기다림 속에서 지쳐 있어요.","daily":"오늘은 붙들고 있던 것 하나를 내려놓아 보세요. 놓는 순간 흐름이 다시 움직여요.","love":"일방적인 희생이나 미련이 관계를 지치게 해요. 매달리는 것과 사랑하는 것은 달라요.","people":"변화를 거부하고 과거에 머물러 갈등이 반복돼요. 놓아야 할 것을 놓을 용기가 필요해요.","reunion":"미련만으로 붙잡으면 소모적일 뿐이에요. 관점을 바꾸지 못하면 같은 자리를 맴돌게 돼요.","career":"쓸모없는 것을 붙들다 시간과 에너지를 낭비할 수 있어요. 놓을 것을 정리해야 나아갈 수 있어요.","money":"손실을 못 놓고 붙들다 더 큰 손해를 볼 수 있어요. 미련을 끊는 결단이 필요해요.","advice":"헛된 희생을 멈추세요. 관점을 바꾸지 못하고 붙들기만 하면, 멈춤은 그저 정체가 돼요.","caution":"'조금만 더'가 반복되면 기회도 마음도 소진돼요. 놓을 때를 아는 것이 지혜예요.","words":["헛된 희생","정체","저항"]}},"M13":{"name":"죽음","number":13,"arcana":"major","suit":"major","element":"spirit","u":{"line":"낡은 것이 저물고 새로운 것이 태어나는, 거대한 전환의 자리예요.","core":"한 챕터가 끝나고 새로운 시작이 열리는 카드예요. 두렵지만 이 종결은 파괴가 아니라 재탄생을 위한 문이에요.","mind":"지금 당신은 무언가를 끝내야 함을 알고 있으며, 변화 앞에서 두려움과 해방감을 동시에 느끼고 있어요.","daily":"오늘은 끝내야 할 것을 매듭짓기 좋은 날이에요. 정리가 곧 새 출발의 준비예요.","love":"관계의 한 단계가 마무리되고 새로운 국면이 열리는 시기예요. 끝은 곧 다른 시작의 신호예요.","people":"낡은 방식이나 관계의 형태가 변화해요. 붙들기보다 자연스러운 전환을 받아들일 때예요.","reunion":"예전 그대로의 관계로는 돌아갈 수 없어요. 과거를 완전히 정리해야 새로운 형태로 다시 시작할 수 있어요.","career":"한 단계를 정리하고 새 국면으로 넘어가는 시기예요. 낡은 방식을 버릴 때 도약이 가능해요.","money":"재정 구조를 근본적으로 정리·전환할 때예요. 안 맞는 것을 정리하면 새 흐름이 생겨요.","advice":"끝을 두려워하지 마세요. 낡은 것을 놓아야 새것이 들어와요. 이 변화는 재탄생을 위한 것이에요.","caution":"끝을 억지로 거부하면 변화가 더 고통스러워져요. 놓아줄 것은 놓아주세요.","words":["종결","변화","전환"]},"r":{"line":"저물어야 할 것을 붙들어, 변화가 고통스럽게 지연되는 자리예요.","core":"필요한 끝을 받아들이지 못해 변화가 막힌 상태예요. 두려움과 미련이 전환을 지연시켜 더 힘들어져요.","mind":"지금 마음은 변화가 필요함을 알면서도 두려움 때문에 붙들고 있는 상태예요.","daily":"오늘은 끝내지 못한 것 하나를 마주해 보세요. 미룰수록 마음만 무거워져요.","love":"끝난 관계나 낡은 패턴을 놓지 못해 괴로운 상태예요. 붙들수록 마무리가 길고 아파져요.","people":"변화를 거부하고 옛 방식을 고집해 관계가 정체돼요. 놓아야 할 것을 직시해야 해요.","reunion":"과거를 정리하지 않은 채 다시 시작하려 하면 같은 문제가 반복돼요. 완전한 마무리가 먼저예요.","career":"낡은 방식을 놓지 못해 정체될 수 있어요. 변화를 받아들여야 다음 단계로 갈 수 있어요.","money":"손실이나 낡은 구조를 정리하지 못해 부담이 이어져요. 결단이 지연될수록 손해가 커요.","advice":"붙들지 마세요. 두려움 때문에 미룬 마무리가 고통을 길게 만들어요. 놓아주는 것이 시작이에요.","caution":"붙들지 마세요. 두려움 때문에 미룬 마무리가 고통을 길게 만들어요. 놓아주는 것이 시작이에요.","words":["변화 저항","정체","미련"]}},"M14":{"name":"절제","number":14,"arcana":"major","suit":"major","element":"spirit","u":{"line":"두 잔 사이로 물을 부드럽게 흘려보내며 완벽한 균형을 맞추는 절제의 자리예요.","core":"서로 다른 것을 조화롭게 섞어 균형을 이루는 카드예요. 극단으로 치닫지 않고 적절한 중용을 지킬 때 흐름이 안정돼요.","mind":"감정 반응과 관계 유지 사이의 간격을 조절할 수 있을 때 갈등이 누적되지 않아요.","daily":"오늘은 무리하지 말고 페이스를 조절하세요. 균형 잡힌 하루가 흐름을 부드럽게 해요.","love":"서로의 차이를 부드럽게 조율하며 관계가 안정되는 시기예요. 인내심 있는 조화가 사랑을 성숙하게 해요.","people":"서로 다른 성향을 맞춰가며 균형을 이루는 관계예요. 극단적인 감정보다 온화한 조율이 통해요.","reunion":"감정과 현실을 잘 섞어 서서히 다가갈 때예요. 조급함 없이 균형을 맞추면 자연스럽게 이어져요.","career":"서로 다른 요소를 잘 조합해 성과를 내는 시기예요. 균형 잡힌 협업과 페이스 조절이 유리해요.","money":"재정의 균형을 맞추고 절제하는 것이 유리해요. 과하지도 부족하지도 않은 관리가 안정을 줘요.","advice":"상대의 요청에 즉답하지 말고 '확인 후 답할게요'를 먼저 말해 감정 온도를 조절하세요.","caution":"균형을 핑계로 결단을 미루면, 조율이 아니라 회피가 돼요.","words":["조율","안정","회복"]},"r":{"line":"물이 넘치거나 모자라, 균형이 무너지고 조화가 깨진 자리예요.","core":"내 감정을 늦게 알아차리거나 참아버려 경계선이 흐려지는 흐름이에요.","mind":"거절을 관계 파괴로 해석하는 순간, 갈등 회피가 과도해지고 자기표현이 위축될 수 있어요.","daily":"오늘은 무리하거나 극단으로 가지 않도록 페이스를 조절하세요.","love":"감정의 균형이 무너져 지나치거나 부족한 방향으로 흘러요. 서로의 페이스를 다시 맞춰야 해요.","people":"한쪽의 과함이나 조급함이 조화를 깨요. 극단을 줄이고 중용을 회복하세요.","reunion":"조급하게 밀어붙이거나 감정만 앞서면 어긋나요. 균형을 되찾은 뒤에 다가가는 편이 나아요.","career":"과욕이나 조급함이 성과를 그르칠 수 있어요. 무리하지 말고 흐름을 조율하세요.","money":"과소비나 극단적인 결정이 균형을 무너뜨려요. 절제와 조율이 필요해요.","advice":"오늘 한 번은 '지금은 어렵다'를 짧게 말해 보세요. 설명을 길게 붙이지 않아도 관계는 유지될 수 있어요.","caution":"극단을 반복하면 몸도 관계도 지쳐요. 무엇이 균형을 깨뜨렸는지 돌아보세요.","words":["감정 조절 어려움","균형 붕괴","경계선 약화"]}},"M15":{"name":"악마","number":15,"arcana":"major","suit":"major","element":"spirit","u":{"line":"느슨한 사슬에 스스로 묶인 채, 벗어날 수 있는데도 욕망의 고리에서 나오지 못하는 자리예요.","core":"강한 끌림과 욕망 뒤에 빠져나오기 어려운 조건이 붙는 카드예요. 매력에 취하기 전에, 무엇이 나를 묶고 있는지 차갑게 확인할 때예요.","mind":"지금 마음은 벗어나야 함을 알면서도 욕망이나 두려움에 묶여 선택권을 놓치고 있는 상태예요.","daily":"오늘은 끊고 싶은 습관이나 집착 하나를 자각해 보세요. 인식이 경계 회복의 시작이에요.","love":"강한 끌림 속에 집착이나 의존이 섞인 관계예요. 열정이 속박으로 변하지 않는지, 사랑인지 익숙함인지 냉정하게 구분하세요.","people":"서로에게 얽매여 벗어나기 어려운 관계예요. 감정의 크기보다 경계선과 의존 구조를 먼저 점검해야 해요.","reunion":"그리움이 아니라 집착이나 익숙함에 매달리는 건 아닌지 돌아보세요. 헤어나지 못하는 이유가 사랑인지 두려움인지 확인이 먼저예요.","career":"안정이라는 이름의 굴레나 달콤한 제안에 묶일 수 있어요. 수익보다 해지 조건과 책임 범위를 먼저 확인하세요.","money":"과소비, 도박성 유혹, 물질 집착을 조심하세요. 위약금·중독성 패턴을 가볍게 넘기면 선택권이 줄어들어요.","advice":"무엇에 묶여 있는지 직시하세요. 끌림보다 해지 조건과 경계선을 먼저 확인하고, 반복되는 집착 하나를 중단 목록에 적으세요.","caution":"욕망과 집착을 방치하면, 스스로 만든 굴레가 점점 더 단단해지고 선택권이 사라져요.","words":["집착","유혹","의존"]},"r":{"line":"묶여 있던 사슬을 스스로 풀어내려 하지만, 아직 불안정한 해방의 자리예요.","core":"악마 역행은 얽매인 것을 자각하고 벗어나려는 상태예요. 다만 회복이 아직 불안정해, 방심하면 익숙한 굴레로 되돌아가기 쉬워요.","mind":"지금 마음은 굴레를 자각하고 벗어나고 싶어 하지만, 아직 완전히 끊어내지 못한 불안정한 상태예요.","daily":"오늘은 끊어내고 싶던 것에서 한 걸음 벗어나 보세요. 다만 다시 익숙한 굴레로 돌아가지 않도록 마음을 다잡으세요.","love":"집착이나 의존에서 벗어나려는 시기예요. 굴레를 끊는 용기가 필요하되, 미련이 다시 발목을 잡지 않도록 경계하세요.","people":"속박에서 벗어나 관계를 재정립하려는 흐름이에요. 놓아야 할 것을 놓되, 같은 패턴으로 돌아가지 않도록 경계선을 지키세요.","reunion":"집착을 내려놓으면 마음이 편해져요. 매달리던 것에서 벗어나는 것이 회복이지만, 익숙함에 이끌려 되돌아가지 않도록 조심하세요.","career":"속박이나 나쁜 조건에서 벗어날 기회예요. 익숙한 굴레를 끊되, 성급함이 또 다른 덫이 되지 않게 확인하세요.","money":"과소비나 나쁜 재정 습관을 끊어낼 때예요. 욕망의 굴레에서 벗어나되, 방심하면 다시 새어나갈 수 있으니 경계하세요.","advice":"묶였던 것을 놓아주세요. 자각하고 끊어내는 지금이 자유를 되찾는 순간이지만, 재발하지 않도록 경계선을 분명히 하세요.","caution":"벗어나는 과정이 아직 불안정하니, 다시 익숙한 굴레로 돌아가지 않도록 방심을 경계하세요.","words":["속박 자각","끊어내기","경계 회복"]}},"M16":{"name":"탑","number":16,"arcana":"major","suit":"major","element":"spirit","u":{"line":"번개에 무너지는 탑처럼, 약한 기반이 한순간에 흔들려 감춰둔 문제가 표면으로 드러나는 자리예요.","core":"안정돼 보이던 토대가 갑자기 흔들리는 카드예요. 충격은 아프지만, 무너지는 것은 애초에 부실했던 구조이니 이참에 균열을 직시하세요.","mind":"지금 마음은 예상치 못한 충격 속에서 혼란스럽지만, 동시에 덮어둔 문제를 직시하기 시작한 상태예요.","daily":"오늘은 예상 밖의 일이 생길 수 있어요. 흔들려도 급히 키우지 말고 숨은 비용과 균열부터 확인하세요.","love":"겉으로 괜찮아 보여도 감춰진 균열이 드러날 수 있는 시기예요. 감정의 크기로 덮기보다 관계의 토대부터 차분히 점검하세요.","people":"쌓아온 것이 흔들리는 충격이 올 수 있어요. 급히 봉합하기보다 무엇이 부실했는지 먼저 확인해야 같은 붕괴를 막아요.","reunion":"예전 관계의 틀은 이미 흔들렸어요. 그리움으로 원래대로 복원하려 하기보다, 무너진 지점을 직시하고 새로 세울지 판단하세요.","career":"예상 밖의 변화나 구조 문제가 드러날 수 있어요. 밀어붙이기 전에 계약·비용·책임 소재의 균열부터 확인하세요.","money":"갑작스러운 지출이나 재정 충격에 대비하세요. 불안정한 구조는 덮지 말고 이참에 손실선을 정리하는 편이 나아요.","advice":"무너지는 것을 억지로 붙들지 마세요. 확장보다 구조 점검을 먼저 두고, 계약·비용·관계의 균열을 확인해 손실을 줄이세요.","caution":"충격을 부정하고 낡은 구조를 고집하면, 균열이 덮인 채 더 크게 무너져요.","words":["급변","붕괴","구조 점검"]},"r":{"line":"무너질 것을 간신히 붙들고 있는, 지연되고 억눌린 붕괴의 자리예요.","core":"탑 역행은 경고가 사라진 것이 아니라 지연되거나 안쪽으로 숨어 있는 상태예요. 터질 것을 억누를수록 내부 균열이 깊어져요.","mind":"지금 마음은 다가올 변화를 두려워하며, 터질 것 같은 긴장을 억누르고 있는 상태예요.","daily":"오늘은 미뤄둔 문제를 조금씩이라도 확인하세요. 억누르기만 하면 긴장과 균열이 쌓여요.","love":"문제를 알면서도 덮어두어 관계가 위태롭게 유지돼요. 곪은 것을 급히 키우지도, 계속 미루지도 말고 서서히 균열을 확인하세요.","people":"터질 갈등을 억누르며 간신히 버티는 상태예요. 진실을 확인하는 것이 오히려 관계를 지켜요.","reunion":"무너진 것을 억지로 복원하려 하면 더 크게 흔들려요. 근본 균열을 외면한 재회는 같은 붕괴로 이어져요.","career":"곪은 문제를 덮어두면 나중에 더 크게 터져요. 흔들리기 전에 계약·비용의 위험 조건을 미리 점검하세요.","money":"잠재된 재정 위험을 외면하지 마세요. 미리 손실선을 정리하지 않으면 갑작스러운 충격이 와요.","advice":"터질 것을 억누르지 마세요. 급히 키우지도 말고, 숨은 비용과 균열을 하나씩 확인해 충격을 미리 낮추세요.","caution":"변화를 계속 회피하면, 통제할 수 있었던 균열이 통제 불가능한 사태가 돼요.","words":["지연된 충격","억눌린 균열","변화 회피"]}},"M17":{"name":"별","number":17,"arcana":"major","suit":"major","element":"spirit","u":{"line":"밤하늘의 별빛 아래 맑은 물을 길으며 마음을 치유하는 별의 자리예요.","core":"폭풍이 지나간 뒤 찾아오는 희망과 치유의 카드예요. 조급하지 않아도 서서히 회복되며 가능성이 다시 열려요.","mind":"지금 당신의 마음은 힘든 시기를 지나 희망을 되찾으며, 차분하게 회복되고 있어요.","daily":"오늘은 지친 마음을 돌보고 희망을 회복하기 좋은 날이에요. 작은 긍정이 큰 힘이 돼요.","love":"상처가 아물고 관계에 희망이 다시 피어나는 시기예요. 진솔한 마음이 서로를 치유해요.","people":"서로에게 안식과 희망이 되어주는 관계예요. 꾸밈없는 진심이 신뢰를 회복시켜요.","reunion":"서서히 회복되는 희망의 카드예요.","career":"꾸준함이 희망을 현실로 만들어요.","money":"재정이 서서히 회복되는 흐름이에요. 조급하지 않게 계획을 이어가면 안정을 되찾아요.","advice":"조급해하지 마세요. 진심과 희망을 잃지 않는 것이 열쇠예요.","caution":"희망만 품고 현실의 노력을 놓으면, 별빛은 그저 바라만 보는 것이 돼요.","words":["희망","회복","신뢰 재건"]},"r":{"line":"별빛이 흐려져 희망이 잘 보이지 않는, 지치고 실망한 자리예요.","core":"희망을 잃거나 자신감이 흔들리는 상태예요. 실망과 피로가 겹쳐 앞날이 잘 보이지 않아요.","mind":"지금 마음은 자신감이 떨어지고 희망이 흐려져, 무기력함에 눌려 있는 상태예요.","daily":"오늘은 지친 마음을 먼저 돌보세요. 자신에게 조금 더 너그러워질 필요가 있어요.","love":"실망이나 불신으로 마음이 위축된 시기예요. 다시 믿음을 회복하는 데 시간이 필요해요.","people":"신뢰가 흔들리고 희망이 옅어져 관계가 지쳐 있어요. 서로를 다시 믿는 노력이 필요해요.","reunion":"희망을 놓지 못하지만 현실 행동이 부족한 상태예요. 마음은 남아도 실질적 접점이 없으면 가능성은 빠르게 약해져요.","career":"성과가 더디거나 확신이 흔들려 지칠 수 있어요. 조급함을 내려놓고 페이스를 회복하세요.","money":"재정 불안이나 실망이 있을 수 있어요. 무리하지 말고 회복의 시간을 두세요.","advice":"희망을 완전히 놓지는 마세요. 지금은 흐려 보여도, 스스로를 돌보며 기다리면 별빛은 다시 밝아져요.","caution":"실망에 갇혀 자신을 탓하기만 하면, 회복할 수 있는 힘마저 잃게 돼요.","words":["희망 지연","현실 행동 부족","관망"]}},"M18":{"name":"달","number":18,"arcana":"major","suit":"major","element":"spirit","u":{"line":"달빛 아래 실체가 흐릿해, 무엇이 진짜인지 분간하기 어려운 안갯속 자리예요.","core":"불안과 착각, 숨은 감정이 섞여 판단이 흐려지는 카드예요. 겉으로 보이는 것이 전부가 아니며, 상상이 사실을 앞지르지 않도록 확인이 먼저예요.","mind":"지금 마음은 불안과 의심으로 흔들리며, 무엇이 진짜인지 확신하지 못하는 상태예요.","daily":"오늘은 불안한 생각이 커질 수 있어요. 상상과 사실을 구분하고, 확인된 것만 붙드세요.","love":"감정이 모호하고 불안이 커지는 시기예요. 확실하지 않은 것을 지레짐작하기보다, 확인된 행동과 머릿속 가정을 분리해 보세요.","people":"오해나 불확실함이 관계를 흐리게 해요. 상상으로 결론 내리지 말고, 사실과 추측을 나눠 진실을 확인해야 해요.","reunion":"지금은 모든 것이 불분명한 안갯속이에요. 불안에 휩쓸려 단정하지 말고, 흐름이 선명해질 때까지 감정 결론을 보류하세요.","career":"정보가 불충분하거나 상황이 불투명한 시기예요. 확실하지 않은 것에 큰 결정을 걸지 말고 근거를 확인하세요.","money":"불확실한 정보나 감춰진 위험에 주의하세요. 왠지 불안하다면 그 직감을 무시하지 말고 사실부터 확인하세요.","advice":"불안이 만든 상상에 휘둘리지 마세요. 사실과 추측을 두 칸으로 나눠 적고, 확인되지 않은 감정 결론은 하루 보류하세요.","caution":"두려움이 만든 상상을 사실로 착각하면, 있지도 않은 문제로 스스로를 괴롭히게 돼요.","words":["불안","모호함","숨은 감정"]},"r":{"line":"안개가 걷히며 흐릿하던 것들이 서서히 제 모습을 드러내는 자리예요.","core":"달 역행은 혼란과 불안이 걷히고 진실이 드러나기 시작하는 상태예요. 다만 아직 정리되는 과정이니, 다 안다고 단정하기엔 일러요.","mind":"지금 마음은 불안이 가라앉으며 점차 명료해지고, 진짜 감정을 마주하기 시작했어요.","daily":"오늘은 안개가 걷히듯 혼란이 정리돼요. 불안했던 문제의 실체가 보이기 시작해요.","love":"오해가 풀리고 감정이 선명해지는 시기예요. 불안이 가라앉되, 확인되지 않은 부분은 여전히 사실로 검증하세요.","people":"감춰졌던 진실이 드러나거나 오해가 정리돼요. 불확실함이 걷히며 방향이 보이기 시작해요.","reunion":"흐릿했던 상황이 정리되고 마음이 분명해져요. 불안을 넘어서면 진짜 답이 보이지만, 성급한 확신은 아직 일러요.","career":"불투명했던 상황이 정리되고 방향이 잡히는 시기예요. 감춰진 정보가 드러나 판단이 쉬워져요.","money":"불확실했던 재정 상황이 명확해져요. 감춰진 위험이 드러나 대비할 수 있게 돼요.","advice":"불안이 걷히고 있어요. 이제 상상이 아니라 드러난 사실을 근거로 차분히 판단하되, 아직 확인 안 된 부분은 보류하세요.","caution":"진실이 드러나는 과정이 아직 진행 중이니, 성급히 다 안다고 단정하지는 마세요.","words":["혼란 정리","진실 노출","불안 완화"]}},"M19":{"name":"태양","number":19,"arcana":"major","suit":"major","element":"spirit","u":{"line":"밝은 햇살 아래 모든 것이 선명하게 빛나는, 기쁨과 성공의 자리예요.","core":"환하게 빛나는 성공과 기쁨의 카드예요. 모든 것이 명료해지고, 숨김없이 드러나는 긍정의 에너지가 흘러요.","mind":"지금 당신의 마음은 밝고 자신감이 넘쳐, 모든 것을 긍정적으로 바라보는 상태예요.","daily":"오늘은 밝고 활기찬 하루가 될 수 있어요. 긍정적인 마음이 좋은 흐름을 불러요.","love":"관계가 밝고 따뜻하게 빛나는 시기예요. 진심이 숨김없이 통하며 함께하는 기쁨이 커져요.","people":"서로에게 활력과 기쁨을 주는 건강한 관계예요. 솔직하고 밝은 마음이 관계를 빛내요.","reunion":"긍정적인 흐름이 강해 재회의 가능성이 밝아요. 밝고 진솔하게 다가가면 마음이 통해요.","career":"성과가 분명히 드러나고 인정받는 시기예요. 자신감을 갖고 나아가면 성공이 따라요.","money":"재물의 흐름이 밝고 풍요로운 시기예요. 긍정적인 에너지가 좋은 결과로 이어져요.","advice":"숨기지 말고 밝게 드러내세요. 진심 어린 긍정과 자신감이 지금의 성공을 완성해요.","caution":"지나친 낙관으로 방심하면, 밝은 흐름 속에서도 놓치는 것이 생겨요.","words":["기쁨","활력","성공"]},"r":{"line":"구름이 잠시 해를 가린, 빛이 흐려지고 활력이 떨어진 자리예요.","core":"성공과 기쁨이 잠시 흐려지거나 지연되는 상태예요. 과신이나 겉치레가 진짜 빛을 가릴 수 있어요.","mind":"지금 마음은 자신감이 잠시 흐려지고 활력이 떨어져, 긍정을 애써 붙들고 있는 상태예요.","daily":"오늘은 활력이 떨어질 수 있어요. 무리하지 말고 자신을 재충전하세요.","love":"관계의 밝음이 잠시 흐려지거나 활력이 떨어진 시기예요. 진심을 회복하면 다시 빛나요.","people":"겉으로는 괜찮아 보여도 속의 온기가 식어 있을 수 있어요. 진짜 감정을 회복하는 노력이 필요해요.","reunion":"긍정적 흐름이 잠시 주춤하지만 가능성은 남아 있어요. 조급함보다 진심을 다시 보이세요.","career":"성과가 늦어지거나 겉만 화려하고 속은 부실할 수 있어요. 본질에 집중하세요.","money":"재정 흐름이 잠시 주춤하거나 과신으로 인한 손실을 조심하세요. 현실적으로 점검할 때예요.","advice":"겉치레보다 진짜 알맹이를 챙기세요. 잠시 흐려진 빛은, 진심을 회복하면 다시 밝아져요.","caution":"과신하거나 겉만 꾸미면, 진짜 성공은 계속 미뤄져요.","words":["일시적 흐림","과신","지연된 성공"]}},"M20":{"name":"심판","number":20,"arcana":"major","suit":"major","element":"spirit","u":{"line":"나팔 소리에 깨어나 지난날을 딛고 다시 일어서는 심판의 자리예요.","core":"지난 일을 되돌아보고 새롭게 거듭나는 카드예요. 과거를 정리하고 용서할 때, 한 단계 높은 국면으로 부름받아요.","mind":"지금 당신은 과거를 돌아보며 스스로를 재평가하고, 새로운 결단을 준비하는 상태예요.","daily":"오늘은 지난 일을 정리하고 새 마음을 먹기 좋은 날이에요. 매듭이 새 출발을 만들어요.","love":"관계를 되돌아보고 새로운 단계로 나아가는 시기예요. 과거를 용서하고 정리할 때 진짜 답이 나와요.","people":"그동안의 관계를 재평가하고 다시 시작하는 때예요. 지난 일을 매듭지어야 앞으로 나아갈 수 있어요.","reunion":"과거를 정직하게 되돌아보고 용서할 준비가 되었다면, 다시 시작할 부름이 올 수 있어요.","career":"그동안의 성과를 평가받고 새 기회로 부름받는 시기예요. 과거의 경험이 도약의 발판이 돼요.","money":"재정을 총정리하고 새롭게 계획할 때예요. 지난 결정을 되짚어 교훈으로 삼으세요.","advice":"과거를 정직하게 돌아보고 용서하세요. 지난 것을 매듭지을 때, 한 단계 높은 부름에 응할 수 있어요.","caution":"지난 일을 자책으로만 되새기면, 각성이 아니라 후회에 갇히게 돼요.","words":["재평가","각성","부름"]},"r":{"line":"나팔 소리를 외면한 채 지난날에 붙들려 일어서지 못하는 자리예요.","core":"과거에 집착하거나 자기비판에 빠져 앞으로 나아가지 못하는 상태예요. 새로운 부름을 외면하고 있어요.","mind":"지금 마음은 지난 일에 대한 후회와 자책으로, 앞으로 나아가지 못하고 머물러 있어요.","daily":"오늘은 자기 비판을 멈추고 스스로를 용서해 보세요. 과거는 이미 지났어요.","love":"지난 일을 놓지 못하거나 자책에 갇혀 관계가 정체돼요. 과거를 용서해야 앞으로 갈 수 있어요.","people":"옛 상처나 후회에 매여 관계가 나아가지 못해요. 매듭짓지 못한 감정을 정리해야 해요.","reunion":"과거에 대한 미련이나 자책이 발목을 잡아요. 지난 것을 정리하지 않으면 새로 시작하기 어려워요.","career":"지난 실패나 후회에 매여 결단을 미룰 수 있어요. 과거를 교훈 삼아 앞으로 나아가세요.","money":"지난 결정을 후회만 하면 다음 기회를 놓쳐요. 정리하고 새 계획을 세울 때예요.","advice":"자책과 미련을 내려놓으세요. 과거를 용서해야 새로운 부름에 응할 힘이 생겨요.","caution":"지난 일에 계속 매여 있으면, 눈앞의 새 기회조차 보이지 않게 돼요.","words":["자기비판","미련","결정 지연"]}},"M21":{"name":"세계","number":21,"arcana":"major","suit":"major","element":"spirit","u":{"line":"모든 것이 하나로 어우러져 완결되는, 성취와 통합의 자리예요.","core":"노력해온 것이 통합되어 충만한 성취로 마무리돼요.","mind":"지금 당신은 하나의 목표를 이룬 충만함 속에서, 다음 단계를 준비하는 상태예요.","daily":"오늘은 무언가를 마무리하고 성취감을 느끼기 좋은 날이에요. 완결이 새 시작을 준비시켜요.","love":"관계가 성숙하고 완성된 형태로 무르익는 시기예요.","people":"서로를 온전히 이해하며 조화롭게 완성된 관계예요. 함께 이룬 것이 충만함을 줘요.","reunion":"한 챕터가 완성되며 새로운 형태로 관계가 정리돼요. 과거를 온전히 통합할 때 답이 분명해져요.","career":"프로젝트나 목표가 성공적으로 완성되는 시기예요.","money":"재정 목표를 달성하고 안정을 이루는 시기예요.","advice":"여기까지 온 것을 충분히 인정하고 완성하세요. 하나의 마무리가 다음 여정의 든든한 토대가 돼요.","caution":"완성에 안주해 다음을 준비하지 않으면, 충만함이 정체로 바뀔 수 있어요.","words":["완성","통합","성취"]},"r":{"line":"거의 다 왔지만 마지막 조각이 채워지지 않은, 미완성의 자리예요.","core":"완성을 눈앞에 두고 마무리가 지연되는 상태예요. 마지막 한 걸음이 남았거나, 아쉬움이 마무리를 막고 있어요.","mind":"지금 마음은 목표에 거의 도달했지만 채워지지 않은 아쉬움으로 미묘하게 흔들려요.","daily":"오늘은 마무리하지 못한 일 하나를 끝까지 챙겨보세요. 마지막 한 걸음이 관건이에요.","love":"관계가 완성에 이르지 못하고 아쉬움이 남는 시기예요. 마지막 매듭을 위한 노력이 필요해요.","people":"거의 안정되었지만 채워지지 않은 부분이 남아 있어요. 마지막 조율이 완성을 만들어요.","reunion":"정리되지 않은 감정이 남아 마무리가 지연돼요. 미완의 부분을 매듭지어야 답이 나와요.","career":"프로젝트가 마무리 단계에서 지연되거나 미흡할 수 있어요. 끝까지 마저 챙겨야 완성돼요.","money":"재정 목표가 거의 달성되었지만 마무리가 남았어요.","advice":"거의 다 왔어요. 아쉬움에 멈추지 말고, 남은 마지막 한 걸음을 마저 완성하세요.","caution":"마지막을 미루면, 다 이룬 것도 미완으로 남아요.","words":["미완성","마무리 지연","아쉬움"]}},"W01":{"name":"완드 에이스","number":1,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"손에 쥔 완드에서 새싹이 돋는, 열정과 영감이 막 타오르는 자리예요.","core":"가슴에 새로운 불꽃이 붙는 카드예요. 하고 싶은 것이 분명해지고, 그 에너지를 지금 행동으로 옮기면 강하게 뻗어나가요.","mind":"지금 당신은 하고 싶은 것이 분명하고 의욕이 넘쳐, 곧바로 움직이고 싶은 상태예요.","daily":"오늘은 하고 싶던 일에 첫 불씨를 붙여보세요. 시작하는 순간 에너지가 솟아요.","love":"새로운 끌림이나 설렘이 타오르는 시기예요. 망설이지 말고 먼저 다가가면 관계에 불이 붙어요.","people":"관계에 활기와 열정이 살아나요. 솔직한 표현과 능동적인 태도가 서로의 마음에 불을 지펴요.","reunion":"다시 시작하고 싶은 열정이 살아 있어요. 그 불꽃이 진짜 마음인지 확인하고 용기 있게 다가가 보세요.","career":"새 프로젝트나 아이디어에 불이 붙는 시기예요. 영감을 실행으로 옮기면 강한 추진력이 생겨요.","money":"새로운 수입원이나 도전의 기회가 열려요. 열정을 살려 시작하면 흐름이 생겨요.","advice":"떠오른 열정을 미루지 마세요. 지금의 불꽃을 곧바로 작은 행동으로 옮기면 강하게 타올라요.","caution":"불꽃은 방향이 없으면 금세 사그라들어요. 열정을 어디에 쓸지 정하세요.","words":["새로운 열정","영감","시작의 불꽃"]},"r":{"line":"붙으려던 불씨가 바람에 흔들려 좀처럼 타오르지 못하는 자리예요.","core":"열정은 있는데 방향이나 계기가 없어 좀처럼 불붙지 못하는 상태예요. 의욕이 헛돌거나 시작이 자꾸 미뤄져요.","mind":"지금 마음은 하고 싶은 건 있는데 어디서부터 시작할지 몰라 답답한 상태예요.","daily":"오늘은 무리하게 벌이기보다, 하고 싶은 일의 방향부터 정리해 보세요.","love":"설렘은 있지만 진전이 없거나, 타이밍이 어긋나 마음이 헛돌아요. 조급함보다 진짜 동기를 확인하세요.","people":"활기가 떨어지거나 열정이 식어 관계가 정체돼요. 무엇이 불씨를 꺼뜨렸는지 돌아보세요.","reunion":"다시 시작하려는 의욕이 있지만 계기가 부족해요. 조급하게 불을 붙이려 하면 더 어긋나요.","career":"의욕이 앞서지만 준비나 방향이 부족해 헛돌 수 있어요. 계획을 먼저 다지세요.","money":"검증 없이 벌인 일은 흐지부지되기 쉬워요. 시작 전에 현실성을 점검하세요.","advice":"불이 안 붙는다고 조급해하지 마세요. 열정을 쏟을 방향을 먼저 정하면 불씨가 살아나요.","caution":"동기 없이 벌인 일은 금세 식어요. 왜 하려는지부터 분명히 하세요.","words":["열정 지연","동기 부족","헛된 시작"]}},"W02":{"name":"완드 2","number":2,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"세계 지도를 손에 들고 다음 여정을 가늠하는, 방향을 정하는 자리예요.","core":"손에 쥔 가능성을 어디로 펼칠지 구상하는 카드예요. 이미 힘은 있으니, 이제 방향을 정하고 첫걸음을 내딛을 때예요.","mind":"지금 당신은 앞날을 구상하며, 어느 방향으로 나아갈지 결정하려는 상태예요.","daily":"오늘은 앞으로의 계획을 세우기 좋은 날이에요. 방향을 정하면 마음이 든든해져요.","love":"관계를 어떻게 끌어갈지 방향을 정하는 시기예요. 마음의 계획을 세우고 능동적으로 움직이면 흐름이 잡혀요.","people":"관계의 미래를 함께 그려보는 때예요. 주도적으로 방향을 제안할 때 관계가 진전돼요.","reunion":"다시 이어갈지 방향을 정해야 할 시점이에요. 감정만이 아니라 어떻게 달라질지 구체적으로 그려보세요.","career":"장기 계획과 방향을 세우기 좋은 시기예요. 큰 그림을 그리고 첫 실행에 나서세요.","money":"재정 계획과 방향을 세울 때예요. 구상만 하지 말고 첫 실행으로 옮기세요.","advice":"이미 가능성은 손에 있어요. 방향을 정하고, 구상을 첫걸음으로 옮기세요.","caution":"계획만 세우고 발을 떼지 않으면, 가능성은 지도 위에만 남아요.","words":["계획","방향 결정","첫걸음"]},"r":{"line":"지도를 든 채 어느 길로 갈지 정하지 못해 멈춰 선 자리예요.","core":"방향을 정하지 못하고 망설이는 상태예요. 두려움이나 우유부단함이 첫걸음을 막고 있어요.","mind":"지금 마음은 어느 방향으로 가야 할지 몰라 갈팡질팡하는 상태예요.","daily":"오늘은 미뤄둔 결정 하나를 마주해 보세요. 방향을 정하면 답답함이 풀려요.","love":"관계의 방향을 못 정해 진전이 없어요. 확신이 없어 결정을 미루고 있을 수 있어요.","people":"미래에 대한 계획이 어긋나거나 결정을 미뤄 관계가 정체돼요. 솔직한 대화가 필요해요.","reunion":"다시 시작할지 결정을 못 내리고 있어요. 두려움 때문에 미루면 흐름을 놓쳐요.","career":"계획이 지연되거나 방향을 못 잡아 제자리걸음일 수 있어요. 우선순위부터 정하세요.","money":"재정 결정을 미루다 기회를 놓칠 수 있어요. 신중하되 결단이 필요해요.","advice":"완벽한 확신을 기다리지 마세요. 방향을 정하고 작게라도 첫걸음을 내딛으세요.","caution":"두려움에 결정을 미룰수록, 선택지는 오히려 줄어들어요.","words":["우유부단","계획 지연","두려움"]}},"W03":{"name":"완드 3","number":3,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"언덕 위에서 떠나보낸 배가 돌아오길 내다보는, 전망과 확장의 자리예요.","core":"뿌려둔 것이 자라기 시작해 넓은 시야로 미래를 내다보는 카드예요. 첫 결실이 오는 중이니 조금 더 멀리 보며 기다릴 때예요.","mind":"지금 당신은 넓은 시야로 앞날을 내다보며, 결실을 기다리는 상태예요.","daily":"오늘은 눈앞보다 조금 더 멀리 내다보세요. 넓은 시야가 여유를 줘요.","love":"관계가 넓어지고 발전할 가능성이 보이는 시기예요. 조급해하지 말고 상대를 넓은 마음으로 기다려 주세요.","people":"함께 미래를 내다보며 관계가 확장되는 때예요. 서로의 성장을 기다려 주는 여유가 필요해요.","reunion":"뿌려둔 진심이 돌아올 여지가 있어요. 조급하게 재촉하기보다 멀리 보며 기다리는 편이 나아요.","career":"노력이 넓게 뻗어나가고 기회가 확장되는 시기예요. 멀리 내다보며 준비하세요.","money":"투자나 노력의 결실이 돌아오기 시작해요. 조급하지 않게 흐름을 지켜보세요.","advice":"뿌려둔 것은 자라고 있어요. 조급해하지 말고 넓은 시야로 결실을 기다리세요.","caution":"기다림이 방심이 되면 안 돼요. 돌아올 결실을 맞을 준비는 해두세요.","words":["확장","전망","기다림"]},"r":{"line":"돌아올 배를 기다리다 지쳐 시야가 좁아진 자리예요.","core":"기대한 결실이 늦어지거나 시야가 좁아진 상태예요. 조급함이 넓게 보는 눈을 가리고 있어요.","mind":"지금 마음은 기다림에 지쳐 시야가 좁아지고 조급해진 상태예요.","daily":"오늘은 결과를 재촉하기보다, 시야를 넓혀 여유를 되찾아 보세요.","love":"관계의 진전이 기대만큼 안 되거나 좁은 시야로 답답해져요. 조급함을 내려놓으세요.","people":"함께 그린 미래가 지연되어 실망이 쌓여요. 넓은 시야를 회복해야 해요.","reunion":"기다림이 길어져 지치거나 기대가 어긋날 수 있어요. 성급하게 재촉하지 마세요.","career":"확장이 지연되거나 기대가 어긋날 수 있어요. 눈앞에만 매이지 말고 멀리 보세요.","money":"기대한 수익이 늦어질 수 있어요. 조급한 결정보다 흐름을 넓게 보세요.","advice":"결실이 늦다고 조급해하지 마세요. 좁아진 시야를 넓히면 흐름이 다시 보여요.","caution":"눈앞의 지연에만 매이면, 정작 다가오는 기회를 놓쳐요.","words":["지연","좁은 시야","성급함"]}},"W04":{"name":"완드 4","number":4,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"꽃으로 장식된 문 아래 사람들이 모여 기쁨을 나누는, 축하와 안정의 자리예요.","core":"한 단계를 이뤄 함께 기뻐하는 안정의 카드예요.","mind":"지금 당신은 이룬 것에 대한 만족과 안정감 속에서 편안한 상태예요.","daily":"오늘은 이룬 것을 자축하고 편안하게 쉬어가기 좋은 날이에요.","love":"관계가 안정되고 함께하는 기쁨이 커지는 시기예요. 서로에 대한 신뢰가 든든한 토대가 돼요.","people":"조화롭고 편안한 관계가 무르익어요. 함께 이룬 것을 축하하며 안정을 다질 때예요.","reunion":"따뜻한 화합의 기운이 있어요. 편안하고 안정적인 태도로 다가가면 다시 이어질 여지가 커요.","career":"한 단계를 성취하고 안정되는 시기예요. 이정표를 자축하고 다음을 준비하세요.","money":"재정이 안정되고 결실을 거두는 흐름이에요. 이룬 것을 든든한 기반으로 삼으세요.","advice":"여기까지 온 것을 충분히 기뻐하세요. 안정된 토대 위에서 다음 걸음을 준비하면 돼요.","caution":"안정에 안주해 다음을 준비하지 않으면, 이정표가 종착점이 돼요.","words":["안정","축하","결실"]},"r":{"line":"축제 준비가 어수선하거나 기쁨이 온전치 못한 자리예요.","core":"안정과 기쁨이 온전치 못하거나 지연되는 상태예요. 겉으로는 괜찮아도 속에 긴장이나 미완이 남아 있어요.","mind":"지금 마음은 안정을 원하면서도 채워지지 않은 불안이 남아 있는 상태예요.","daily":"오늘은 겉의 안정보다 속의 긴장을 살펴보세요. 진짜 편안함이 필요해요.","love":"관계의 안정이 흔들리거나 함께하는 기쁨이 옅어져요. 화합을 회복하는 노력이 필요해요.","people":"겉으로는 조화로워 보여도 속에 긴장이 있어요. 진짜 화합을 위한 소통이 필요해요.","reunion":"화합의 기운이 있지만 아직 온전치 않아요. 조급하게 안정을 기대하기보다 차근히 다가가세요.","career":"성취가 미완이거나 축하가 이른 시기일 수 있어요. 마무리를 마저 챙기세요.","money":"재정 안정이 아직 불완전해요. 방심하지 말고 기반을 더 다지세요.","advice":"겉의 기쁨에 머물지 말고, 속에 남은 긴장이나 미완을 챙겨 진짜 안정을 만드세요.","caution":"불완전한 안정을 다 됐다고 여기면, 뒤늦게 균열이 드러나요.","words":["불안정","미완의 기쁨","긴장"]}},"W05":{"name":"완드 5","number":5,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"여럿이 완드를 부딪치며 서로 다른 방향으로 힘을 겨루는, 경쟁과 마찰의 자리예요.","core":"서로 다른 힘과 의견이 부딪치는 카드예요. 소모적으로 보여도, 이 마찰은 각자의 입장을 분명히 하는 성장의 과정이기도 해요.","mind":"지금 당신은 여러 힘이 부딪히는 혼란 속에서, 자기 입장을 지키려 애쓰고 있어요.","daily":"오늘은 마찰이 있을 수 있어요. 이기려 들기보다 입장을 정리하는 데 집중하세요.","love":"의견 충돌이나 신경전이 있는 시기예요. 경쟁이나 오해로 부딪히더라도 대화로 조율하면 관계가 단단해져요.","people":"잦은 마찰이나 다툼이 생겨요. 이기려 들기보다 서로의 입장을 정리하는 것이 먼저예요.","reunion":"감정적 다툼이나 경쟁 심리가 남아 있을 수 있어요. 승부를 겨루기보다 진짜 원하는 것을 확인하세요.","career":"경쟁이나 의견 대립이 있는 시기예요. 부딪힘을 성장의 계기로 삼되 감정 소모는 줄이세요.","money":"이해관계 충돌이나 경쟁이 있을 수 있어요. 감정보다 실리로 조율하세요.","advice":"부딪힘을 피하지 말되, 이기는 데 매달리지 마세요. 각자의 입장을 정리하면 소모전이 성장이 돼요.","caution":"감정적으로 이기려 들면, 얻는 것보다 잃는 것이 많아져요.","words":["경쟁","갈등","의견 충돌"]},"r":{"line":"부딪히던 완드가 잦아들거나, 겉으론 조용해도 속에 다툼이 남은 자리예요.","core":"겉의 갈등이 잦아들거나, 반대로 드러내지 못한 마찰이 속에서 곪는 상태예요. 회피와 해소의 갈림길이에요.","mind":"지금 마음은 다툼에 지쳐 회피하고 싶으면서도, 속으로는 불편함이 남은 상태예요.","daily":"오늘은 덮어둔 불편함을 조금씩 풀어보세요. 회피만으론 해소되지 않아요.","love":"갈등을 피하며 넘어가지만 근본 문제는 남아 있어요. 덮어두기보다 솔직히 풀어야 해요.","people":"표면의 다툼은 줄었어도 속에 긴장이 남아요. 회피가 아니라 진짜 화해가 필요해요.","reunion":"갈등이 가라앉는 듯 보여도 근본 문제가 남아 있어요. 회피하면 같은 다툼이 반복돼요.","career":"경쟁이 일단락되거나, 드러나지 않은 갈등이 남을 수 있어요. 회피보다 정리가 우선이에요.","money":"이해 다툼이 봉합되는 듯 보여도 불씨가 남을 수 있어요. 조건을 명확히 하세요.","advice":"갈등을 덮기만 하지 마세요. 근본 문제를 솔직히 마주해야 진짜로 잦아들어요.","caution":"회피한 갈등은 사라지지 않고, 속에서 더 크게 곪아요.","words":["갈등 회피","긴장 해소","내적 다툼"]}},"W06":{"name":"완드 6","number":6,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"월계관을 쓰고 사람들의 환호 속에 당당히 나아가는, 승리와 인정의 자리예요.","core":"노력이 인정받고 승리를 거두는 카드예요.","mind":"성취 경험이 자기효능감을 끌어올리지만, 외부 반응 중심으로 고정되면 변동성이 커질 수 있어요.","daily":"오늘은 인정받거나 좋은 소식이 있을 수 있어요. 자신감을 갖고 나아가세요.","love":"관계에서 인정받고 좋은 결실을 얻는 시기예요. 자신감 있게 다가가면 마음이 통해요.","people":"서로를 자랑스러워하며 관계가 빛나는 때예요. 당당한 태도가 관계에 활력을 줘요.","reunion":"긍정적 흐름이 강해 좋은 결과를 기대할 수 있어요. 자신감 있게 다가가면 마음이 열려요.","career":"성과가 인정받고 좋은 평가를 얻는 시기예요. 자신감 있게 성취를 드러내세요.","money":"노력의 결실이 재물로 돌아오는 흐름이에요.","advice":"칭찬을 받으면 바로 다음 목표로 넘어가기보다, 내가 잘한 선택을 구체적으로 기록해 두세요.","caution":"승리에 취해 자만하면, 다음 도전에서 발을 헛디딜 수 있어요.","words":["자신감","인정","성과"]},"r":{"line":"환호가 잦아들거나, 기대한 인정이 오지 않아 머쓱해진 자리예요.","core":"외부 반응이 약할 때 내 선택 전체를 의심하기 쉬운 상태가 드러나요.","mind":"칬잘한이 없을 때 내 가치 전체가 흔들린다고 느끼다면, 그게 자존감을 가장 약하게 만드는 습관이에요.","daily":"오늘은 인정에 연연하기보다, 자기 페이스를 지키는 편이 나아요.","love":"기대한 인정이나 진전이 늦어져 실망할 수 있어요. 조급함보다 진심을 다지세요.","people":"인정받지 못한다는 서운함이 쌓여요. 서로의 노력을 알아주는 태도가 필요해요.","reunion":"긍정적 흐름이 주춤하지만 가능성은 남아 있어요. 자만하지 말고 진심을 보이세요.","career":"성과가 제대로 평가받지 못하거나 늦어질 수 있어요. 조급해하지 말고 실력으로 증명하세요.","money":"기대한 보상이 늦어질 수 있어요. 성급한 기대보다 꾸준함이 유리해요.","advice":"오늘은 남이 몰라도 되는 작은 선택 하나를 완수한 뒤, 스스로에게 '잘했다'를 소리 내어 말해 보세요.","caution":"남의 인정에만 매달리면, 자기 중심이 흔들려요.","words":["외부 인정 의존","자신감 흔들림","비교"]}},"W07":{"name":"완드 7","number":7,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"높은 곳에서 여러 도전에 맞서 홀로 자기 자리를 지켜내는 자리예요.","core":"밀려오는 도전에 맞서 소신을 지키는 카드예요. 쉽지 않지만, 물러서지 않고 버텨낼 때 자기 자리를 지킬 수 있어요.","mind":"지금 당신은 도전에 맞서 자기 자리를 지키려 애쓰며, 물러서지 않으려 하고 있어요.","daily":"오늘은 소신을 지켜야 할 일이 있을 수 있어요. 흔들리지 말고 버텨보세요.","love":"관계를 지키기 위해 소신을 지켜야 하는 시기예요. 외부의 압력에도 마음을 굳게 지키면 흔들리지 않아요.","people":"지켜야 할 것을 위해 버텨내는 때예요. 물러서지 않는 태도가 관계를 지켜요.","reunion":"쉽지 않은 상황이지만 소신을 지키면 흐름을 만들 수 있어요. 흔들리지 말고 진심을 지키세요.","career":"경쟁이나 도전에 맞서 자기 위치를 지키는 시기예요. 물러서지 않는 끈기가 통해요.","money":"지켜야 할 것을 방어하는 시기예요. 무리한 확장보다 지금 것을 지키는 데 집중하세요.","advice":"밀려와도 물러서지 마세요. 자기 소신을 굳게 지키면, 도전을 이겨낼 수 있어요.","caution":"지키는 것도 좋지만, 무엇을 위해 버티는지 잊으면 소모전이 돼요.","words":["방어","소신","도전 대응"]},"r":{"line":"밀려오는 도전에 지쳐 버티던 자리를 내주려는 자리예요.","core":"계속된 방어에 지쳐 소진되거나, 압도되어 포기하고 싶어지는 상태예요. 버티는 힘이 바닥나고 있어요.","mind":"지금 마음은 계속 버티느라 지쳐, 다 내려놓고 싶은 상태예요.","daily":"오늘은 무리하게 버티기보다, 지친 마음을 먼저 돌보세요.","love":"지켜내려 애쓰다 지쳐 자신감을 잃을 수 있어요. 무리한 방어보다 힘을 회복하세요.","people":"계속 버티다 소진되어 물러서고 싶어져요. 혼자 다 지키려 하지 말고 도움을 구하세요.","reunion":"지치고 자신감이 떨어져 포기하고 싶어질 수 있어요. 무리하지 말고 마음을 먼저 회복하세요.","career":"압박에 지쳐 자신감을 잃을 수 있어요. 무리한 방어보다 페이스를 회복하세요.","money":"지키려 애쓰다 오히려 소모될 수 있어요. 무리한 방어를 재점검하세요.","advice":"다 지키려 애쓰다 소진하지 마세요. 정말 지킬 것만 남기고, 나머지는 힘을 아끼세요.","caution":"지친 채로 계속 버티면, 지켜낸 것마저 무너질 수 있어요.","words":["소진","압도됨","포기 유혹"]}},"W08":{"name":"완드 8","number":8,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"여덟 개의 완드가 하늘을 가르며 빠르게 날아가는, 신속한 전개의 자리예요.","core":"일이 빠르게 전개되는 카드예요. 기다리던 소식이 오거나 흐름에 속도가 붙어, 지금 움직이면 흐름을 탈 수 있어요.","mind":"지금 당신은 빠르게 진행되는 흐름 속에서, 곧바로 움직이고 싶은 상태예요.","daily":"오늘은 일이 빠르게 진행될 수 있어요. 흐름을 타고 신속하게 움직이세요.","love":"관계가 빠르게 진전되는 시기예요. 기다리던 연락이나 만남이 성사되니 흐름을 놓치지 마세요.","people":"빠른 소통과 전개로 관계에 속도가 붙어요. 타이밍을 살려 적극적으로 움직이세요.","reunion":"기다리던 소식이나 연락이 올 수 있는 시기예요. 흐름이 빠르니 타이밍을 놓치지 마세요.","career":"일이 신속하게 진행되고 좋은 소식이 오는 시기예요. 타이밍을 살려 실행하세요.","money":"재정 흐름이 빠르게 움직여요. 좋은 기회의 타이밍을 놓치지 마세요.","advice":"흐름에 속도가 붙었어요. 기다리던 순간이 왔으니 타이밍을 놓치지 말고 움직이세요.","caution":"속도에 휩쓸려 방향을 놓치면, 빠른 만큼 크게 엇나가요.","words":["빠른 전개","속도","소식"]},"r":{"line":"날아가던 완드가 방향을 잃거나 땅에 떨어져 흐름이 막힌 자리예요.","core":"빠르게 가던 흐름이 지연되거나 엇갈리는 상태예요. 성급함이 오히려 일을 꼬이게 해요.","mind":"지금 마음은 빨리 진행하고 싶은데 흐름이 막혀 답답한 상태예요.","daily":"오늘은 서두르면 오히려 꼬예요. 흐름이 풀릴 때까지 잠시 기다리세요.","love":"진전이 늦어지거나 연락이 엇갈려요. 조급하게 밀어붙이면 타이밍이 더 어긋나요.","people":"소통이 지연되거나 오해로 흐름이 막혀요. 서두르지 말고 타이밍을 다시 맞추세요.","reunion":"타이밍이 어긋나거나 연락이 지연될 수 있어요. 조급하게 재촉하지 마세요.","career":"진행이 지체되거나 소식이 늦어질 수 있어요. 성급함보다 흐름을 정비하세요.","money":"재정 흐름이 지연될 수 있어요. 조급한 결정을 삼가세요.","advice":"조급하게 밀어붙이지 마세요. 엇갈린 타이밍은 서두를수록 더 어긋나요.","caution":"지연을 못 견뎌 무리하면, 흐름이 더 크게 막혀요.","words":["지연","성급함","흐름 정체"]}},"W09":{"name":"완드 9","number":9,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"상처 입은 몸으로도 완드에 기대 마지막 경계를 늦추지 않는 자리예요.","core":"많이 버텨온 힘은 분명하지만, 긴장 상태가 일상화되어 회복이 늦어질 수 있어요.","mind":"다시 상처받지 않기 위해 늘 대비하는 패턴이 안전감을 주는 동시에 관계 피로를 키울 수 있어요.","daily":"오늘은 지쳐도 한 고비만 더 버텨보세요. 끝이 가까이 있어요.","love":"여러 어려움을 겪었어도 관계를 지켜내려는 끈기가 있는 시기예요. 마지막 고비를 넘기면 안정이 와요.","people":"지쳤어도 포기하지 않는 힘이 관계를 지켜요. 다만 과한 경계로 마음을 닫진 마세요.","reunion":"상처가 남아 조심스럽지만, 끈기 있게 다가가면 마지막 고비를 넘길 수 있어요.","career":"힘든 고비의 끝자락이에요. 조금만 더 버티면 그동안의 노력이 지켜져요.","money":"재정적 고비를 버텨내는 시기예요. 마지막까지 방어하면 위기를 넘겨요.","advice":"오늘은 믿을 수 있는 사람 한 명 앞에서만이라도 완벽한 대응을 멈추고, 솔직한 감정 한 문장을 말해 보세요.","caution":"경계가 지나치면 도움의 손길마저 밀어낼 수 있어요. 마음까지 닫진 마세요.","words":["방어","지침","버팀"]},"r":{"line":"버티던 힘이 바닥나 완드를 놓치기 직전인 자리예요.","core":"계속된 버팀에 소진되어 포기 직전이거나, 과도한 경계로 스스로를 지치게 하는 상태예요.","mind":"버티던 힘이 약해진 것이 아니라, 과도한 경계가 한계에 도달했다는 신호일 수 있어요.","daily":"오늘은 지친 몸과 마음을 먼저 돌보세요. 무리하면 무너져요.","love":"지쳐서 관계를 놓고 싶거나, 과한 방어로 마음을 닫아버릴 수 있어요. 힘을 회복하세요.","people":"소진되어 버틸 힘이 없거나, 경계가 지나쳐 상대를 밀어내요. 마음의 문을 조금 여세요.","reunion":"지치고 경계심이 커져 다가서기 어려워요. 무리하지 말고 마음을 먼저 회복하세요.","career":"소진되어 버틸 힘이 바닥날 수 있어요. 무리하지 말고 회복이 먼저예요.","money":"지쳐서 방어가 무너질 수 있어요. 무리한 버팀보다 재정비가 필요해요.","advice":"하루 일정에서 20분 비워 두고 누구의 기대도 아닌 내 컨디션 회복에만 쓰세요.","caution":"지나친 경계는 자신을 고립시켜요. 도움을 밀어내지 마세요.","words":["방어 이완","소진 인식","회복 지연"]}},"W10":{"name":"완드 10","number":10,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"열 개의 완드를 힘겹게 끌어안고 무거운 걸음을 옮기는, 부담과 과부하의 자리예요.","core":"너무 많은 것을 혼자 짊어진 카드예요. 목표는 가깝지만 짐이 무거우니, 무엇을 내려놓을지 정할 때예요.","mind":"지금 당신은 너무 많은 것을 혼자 짊어져, 무거움에 눌려 있는 상태예요.","daily":"오늘은 짐이 무겁게 느껴질 수 있어요. 다 하려 말고 하나씩 덜어내세요.","love":"관계에서 혼자 너무 많은 것을 감당하는 시기예요. 부담을 나누지 않으면 지쳐요.","people":"한쪽이 과도한 책임을 떠안아 무거워져요. 짐을 나누는 대화가 필요해요.","reunion":"혼자 모든 걸 감당하려는 부담이 커요. 다 짊어지려 하기보다 힘을 나눠야 해요.","career":"책임과 업무가 과부하된 시기예요. 혼자 다 하려 말고 우선순위를 정하거나 나누세요.","money":"재정적 부담이 무겁게 쌓인 상태예요. 감당할 범위를 정리해야 해요.","advice":"다 짊어지지 마세요. 목표는 가깝지만, 무엇을 내려놓거나 나눌지 정해야 끝까지 가요.","caution":"혼자 다 감당하려다, 완주 직전에 무너질 수 있어요.","words":["과부하","책임","짐"]},"r":{"line":"짊어졌던 완드를 하나씩 내려놓거나, 무게에 무너지는 자리예요.","core":"무거운 짐을 내려놓기 시작하거나, 반대로 부담에 눌려 번아웃되는 상태예요. 덜어냄과 소진의 갈림길이에요.","mind":"지금 마음은 번아웃 직전이거나, 이제 짐을 내려놓고 싶은 상태예요.","daily":"오늘은 짐 하나를 내려놓아 보세요. 다 안고 가면 지쳐요.","love":"혼자 감당하던 부담을 내려놓으려는 시기예요. 짐을 나누면 관계가 가벼워져요.","people":"과부하를 재분배하거나, 지쳐서 관계를 놓고 싶어져요. 솔직히 부담을 나누세요.","reunion":"혼자 짊어지던 것을 내려놓으면 마음이 편해져요. 다 감당하려던 부담을 내려놓으세요.","career":"과부하로 번아웃될 수 있어요. 업무를 위임하거나 덜어내세요.","money":"재정 부담을 재정비할 때예요. 감당 못 할 짐은 내려놓아야 해요.","advice":"혼자 다 안고 가지 마세요. 내려놓거나 나눠야, 번아웃 없이 끝까지 가요.","caution":"덜어내지 못하고 계속 짊어지면, 결국 번아웃으로 무너져요.","words":["짐 내려놓기","위임","번아웃"]}},"W11":{"name":"완드 페이지","number":11,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"완드를 들고 세상을 향해 호기심 어린 눈으로 첫발을 내딛는 자유로운 탐색가의 자리예요.","core":"새로운 것에 대한 열정과 호기심이 넘치는 카드예요. 완벽하지 않아도 자유롭게 시도하며 가능성을 탐색할 때예요.","mind":"지금 당신은 새로운 것에 대한 호기심과 열정으로, 뭔가 시도해 보고 싶은 상태예요.","daily":"오늘은 호기심을 따라 새로운 것을 시도해 보세요. 즐거운 탐색이 활력을 줘요.","love":"설레는 새 관심사나 인연이 생기는 시기예요. 가볍고 즐거운 마음으로 다가가면 좋은 흐름이 생겨요.","people":"관계에 새로운 활력과 즐거움이 생겨요. 자유롭고 열린 태도가 관계를 신선하게 해요.","reunion":"다시 시작하려는 열정과 호기심이 살아 있어요. 가볍고 진솔하게 다가가 보세요.","career":"새로운 분야나 아이디어를 탐색하기 좋은 시기예요. 자유롭게 시도하며 배우세요.","money":"새로운 기회를 탐색하는 시기예요. 큰 결정보다 가볍게 시도하며 살펴보세요.","advice":"완벽하지 않아도 좋아요. 호기심을 따라 자유롭게 시도하며 가능성을 탐색하세요.","caution":"이것저것 벌이기만 하면, 어느 것도 깊어지지 못해요.","words":["탐색","열정적 호기심","새 소식"]},"r":{"line":"호기심이 사방으로 흩어져 어디에도 진득하게 머물지 못하는 자리예요.","core":"열정은 있지만 산만하거나 변덕스러워 하나에 집중하지 못하는 상태예요. 방향 없는 시도가 흩어져요.","mind":"지금 마음은 하고 싶은 건 많은데 산만해, 하나에 집중하지 못하는 상태예요.","daily":"오늘은 여러 일을 벌이기보다, 하나를 골라 집중해 보세요.","love":"관심이 이리저리 옮겨가거나 진지함이 부족해 관계가 겉돌아요. 진짜 마음을 확인하세요.","people":"변덕이나 미성숙함이 관계를 흔들어요. 가벼움과 무책임을 구분해야 해요.","reunion":"다시 시작하려는 마음이 변덕스럽거나 방향이 없어요. 진지하게 마음을 정하세요.","career":"산만하거나 방향을 못 잡아 성과가 안 날 수 있어요. 우선순위를 정하세요.","money":"충동적이거나 산만한 시도를 조심하세요. 하나에 집중해야 결과가 나요.","advice":"흩어진 호기심을 하나로 모으세요. 방향을 정하면 열정이 결과로 이어져요.","caution":"변덕과 산만함이 반복되면, 신뢰도 성과도 쌓이지 않아요.","words":["산만함","미성숙","변덕"]}},"W12":{"name":"완드 기사","number":12,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"불꽃같은 말을 몰고 거침없이 목표를 향해 돌진하는 열정적인 기사의 자리예요.","core":"열정을 곧바로 행동으로 옮기는 카드예요. 망설임 없이 과감하게 뛰어들어 흐름을 돌파하는 추진력이 지금의 힘이에요.","mind":"지금 당신은 열정이 넘쳐, 곧바로 과감하게 뛰어들고 싶은 상태예요.","daily":"오늘은 망설이던 일에 과감하게 뛰어들기 좋은 날이에요. 추진력이 흐름을 열어요.","love":"적극적이고 열정적으로 다가가는 시기예요. 망설임 없는 표현이 관계에 불을 붙이에요.","people":"역동적이고 열정적인 관계예요. 과감한 태도가 관계를 앞으로 이끌어요.","reunion":"열정을 갖고 과감하게 다가가면 흐름을 만들 수 있어요. 다만 조급함과 진심을 구분하세요.","career":"열정적으로 밀어붙여 성과를 내는 시기예요. 과감한 실행이 흐름을 돌파해요.","money":"적극적인 시도가 결과를 만들어요. 다만 과감함과 무모함은 구분하세요.","advice":"망설이지 말고 과감하게 움직이세요. 열정을 곧바로 행동으로 옮기면 흐름이 열려요.","caution":"열정에 취해 앞뒤 안 보고 돌진하면, 과감함이 무모함이 돼요.","words":["과감한 행동","모험","열정"]},"r":{"line":"고삐 풀린 말이 제멋대로 날뛰어 방향을 잃은 자리예요.","core":"열정이 조급함이나 충동으로 흘러 방향을 잃은 상태예요. 과감함이 무모함으로 바뀌기 쉬워요.","mind":"지금 마음은 조급함과 충동으로, 앞뒤 없이 움직이고 싶은 상태예요.","daily":"오늘은 충동적으로 움직이기 전에 한 박자 멈춰 보세요.","love":"성급하게 밀어붙이다 관계를 그르치거나, 열정이 금세 식어요. 일관성이 필요해요.","people":"충동적이거나 일관성 없는 태도가 관계를 흔들어요. 감정을 조절하세요.","reunion":"조급하게 밀어붙이면 역효과예요. 열정을 다스리고 진심으로 다가가세요.","career":"조급하거나 무모한 실행이 일을 그르칠 수 있어요. 계획을 다지세요.","money":"충동적인 결정을 조심하세요. 과감함과 무모함을 구분해야 해요.","advice":"열정을 조급함으로 흘려보내지 마세요. 방향과 속도를 다잡으면 추진력이 살아나요.","caution":"앞뒤 없는 돌진은, 빠른 만큼 크게 넘어져요.","words":["무모함","조급함","충동"]}},"W13":{"name":"완드 퀸","number":13,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"해바라기를 든 채 당당하고 따뜻하게 좌중을 사로잡는 완드 여왕의 자리예요.","core":"자신감과 따뜻한 카리스마가 빛나는 카드예요. 밝은 활력과 매력으로 사람을 끌어당기며, 결단력 있게 자기 길을 가요.","mind":"지금 당신은 자신감이 넘치고 활력이 살아 있어, 매력적으로 빛나는 상태예요.","daily":"오늘은 당당하고 밝은 태도가 좋은 흐름을 불러요. 자신감을 발휘하세요.","love":"매력과 자신감이 빛나는 시기예요. 당당하면서도 따뜻한 태도가 상대를 끌어당겨요.","people":"활력과 따뜻함이 관계를 빛내요. 자신감 있는 표현이 서로를 끌어당겨요.","reunion":"당당하고 밝은 매력으로 다가가면 좋은 흐름이 생겨요. 자신감을 잃지 마세요.","career":"카리스마와 결단력으로 주도하는 시기예요. 자신감 있는 리더십이 인정받아요.","money":"활력 있는 추진이 좋은 결과를 만들어요. 자신감을 갖고 나아가세요.","advice":"당당하되 따뜻함을 잃지 마세요. 자신감 있는 매력이 사람과 기회를 끌어당겨요.","caution":"자신감이 지나치면 상대를 압도할 수 있어요. 따뜻함을 함께 지키세요.","words":["자신감","따뜻한 카리스마","활력"]},"r":{"line":"밝던 빛이 흐려지고, 자신감 대신 불안과 질투가 스미는 자리예요.","core":"자신감이 흔들리거나 감정 기복이 커진 상태예요. 질투나 불안이 밝은 매력을 가려요.","mind":"지금 마음은 자신감이 떨어지고 감정이 흔들려, 위축된 상태예요.","daily":"오늘은 흔들리는 마음을 다독이고, 자기 페이스를 회복해 보세요.","love":"자신감이 떨어져 위축되거나, 질투와 불안이 관계를 흔들어요. 마음을 다잡으세요.","people":"감정 기복이나 질투가 관계를 흔들어요. 자기 중심을 회복해야 해요.","reunion":"자신감이 떨어지거나 불안이 앞서 다가서기 어려워요. 마음을 먼저 회복하세요.","career":"자신감 저하나 감정 기복이 성과를 흔들 수 있어요. 페이스를 회복하세요.","money":"감정적 판단을 조심하세요. 자신감을 회복한 뒤 결정하세요.","advice":"질투와 불안에 밝은 빛을 가리지 마세요.","caution":"감정 기복에 휘둘리면, 자신감도 관계도 함께 흔들려요.","words":["자신감 저하","질투","소진"]}},"W14":{"name":"완드 킹","number":14,"arcana":"minor","suit":"wands","element":"fire","u":{"line":"불의 왕좌에 앉아 큰 그림을 그리며 사람들을 이끄는 완드 왕의 자리예요.","core":"내 삶의 방향을 내가 정하는 성숙한 추진력이 살아나는 카드예요.","mind":"타인의 실망과 내 가치 판단을 분리할 때 감정 소모 없이 관계를 운영할 수 있어요.","daily":"오늘은 큰 그림을 그리고 대담하게 결단하기 좋은 날이에요.","love":"관계를 주도적으로 이끄는 시기예요. 든든한 비전과 대담함이 상대에게 신뢰를 줘요.","people":"관계의 방향을 대담하게 이끄는 때예요. 큰 그림을 함께 그리면 관계가 견고해져요.","reunion":"비전과 자신감을 갖고 주도적으로 다가가면 흐름을 만들 수 있어요.","career":"리더십과 비전으로 큰 성과를 만드는 시기예요. 대담한 결단이 길을 열어요.","money":"큰 그림을 그리고 대담하게 운용하면 좋은 결과가 와요. 다만 과욕은 경계하세요.","advice":"'네 마음은 이해하지만 내 결정은 이거야'라는 문장을 오늘 한 번 실제 대화에서 사용해 보세요.","caution":"비전이 독선이 되고 대담함이 독단이 되면, 사람들이 등을 돌려요.","words":["자기주도권","건강한 권위","단호함"]},"r":{"line":"큰 그림을 밀어붙이다 독선에 빠지거나 방향을 잃은 자리예요.","core":"리더십이 독선으로 흐르거나, 성급한 결단으로 비전을 잃은 상태예요. 과욕이 판단을 흐려요.","mind":"주도권을 지키려는 마음이 강할수록 말투가 단단해져 불필요한 충돌을 만들 수 있어요.","daily":"오늘은 밀어붙이기 전에 방향과 상대의 의견을 점검해 보세요.","love":"주도가 지나쳐 상대를 압도하거나, 방향을 잃어 관계가 흔들려요. 상대의 목소리를 들으세요.","people":"독단적인 태도가 갈등을 키워요. 함께 그리는 자세가 필요해요.","reunion":"일방적으로 밀어붙이면 역효과예요. 상대의 마음을 먼저 들으세요.","career":"독단이나 성급한 결단이 문제를 키울 수 있어요. 큰 그림을 다시 다지세요.","money":"과욕이나 무리한 확장을 조심하세요. 대담함과 무모함을 구분하세요.","advice":"주장을 말하기 전에 상대 감정을 한 문장으로 먼저 인정한 뒤, 내 기준을 짧게 전달하세요.","caution":"독단적으로 밀어붙이면, 큰 그림도 사람도 함께 잃어요.","words":["권위 과잉","통제 불안","과열"]}},"C01":{"name":"컵 에이스","number":1,"arcana":"minor","suit":"cups","element":"water","u":{"line":"넘쳐흐르는 성배에서 맑은 물이 솟아나는, 감정이 새롭게 차오르는 자리예요.","core":"마음이 새롭게 열리며 감정이 충만하게 차오르는 카드예요. 순수한 사랑과 애정이 샘솟아, 마음을 여는 것 자체가 선물이 돼요.","mind":"지금 당신의 마음은 애정과 설렘으로 충만해, 감정을 나누고 싶은 상태예요.","daily":"오늘은 마음을 열고 감정을 솔직하게 나눠보세요. 순수한 애정이 흐름을 열어요.","love":"새로운 사랑이나 감정이 시작되는 시기예요. 마음을 열고 순수하게 다가가면 아름다운 흐름이 열려요.","people":"감정이 깊어지고 애정이 충만해지는 때예요. 진심을 솔직하게 표현할 때 관계가 피어나요.","reunion":"감정의 문이 새롭게 열릴 수 있는 시기예요. 순수한 마음으로 다가가면 다시 이어질 여지가 커요.","career":"새로운 열정이나 만족감이 생기는 시기예요. 마음이 이끄는 일에 진심을 담으세요.","money":"새로운 기회에 대한 좋은 예감이 드는 시기예요. 마음이 끌리는 방향을 살펴보세요.","advice":"마음을 여는 것을 두려워하지 마세요. 순수하게 감정을 표현할 때 사랑이 차올라요.","caution":"감정에만 취해 현실을 놓치면, 넘친 물처럼 마음이 흘러가 버려요.","words":["새로운 감정","사랑의 시작","마음의 열림"]},"r":{"line":"성배가 엎어져 물이 흘러버린, 감정이 막히거나 메마른 자리예요.","core":"마음이 닫히거나 감정이 메마른 상태예요. 애정을 표현하기 어렵거나, 채워지지 않는 공허함이 있어요.","mind":"지금 마음은 감정이 메마르거나 억눌려, 표현하기 어려운 상태예요.","daily":"오늘은 억눌린 감정을 조용히 들여다보세요. 마음을 돌보는 것이 먼저예요.","love":"마음을 열기 어렵거나 감정이 억눌린 시기예요. 상처나 두려움이 마음의 문을 막고 있어요.","people":"감정 표현이 막혀 서로의 마음이 닿지 않아요. 닫힌 마음을 조금씩 여는 노력이 필요해요.","reunion":"감정의 문이 닫혀 있거나 표현이 어려워요. 억지로 열려 하기보다 마음을 먼저 회복하세요.","career":"열정이 식거나 만족감이 떨어지는 시기예요. 마음이 지쳤다면 재충전이 필요해요.","money":"기대했던 예감이 흐려질 수 있어요. 감정보다 현실을 점검하세요.","advice":"감정을 억누르지 마세요. 닫힌 마음을 조금씩 열고, 지친 감정을 먼저 돌보세요.","caution":"마음을 계속 닫아두면, 애정이 흐를 통로마저 막혀요.","words":["감정 억압","닫힌 마음","공허함"]}},"C02":{"name":"컵 2","number":2,"arcana":"minor","suit":"cups","element":"water","u":{"line":"두 사람이 서로에게 성배를 건네며 마음을 주고받는, 결합과 신뢰의 자리예요.","core":"두 사람의 감정이 맞닿아 상호 신뢰를 이루는 카드예요. 마음이 깊어지며, 감정과 약속이 균형을 맞춰가는 순간이에요.","mind":"지금 당신의 마음은 상대에게 진심으로 향하며, 신뢰를 주고받고 싶은 상태예요.","daily":"오늘은 진심 어린 대화로 신뢰를 나눠보세요. 마음을 주고받는 것이 관계를 키워요.","love":"감정은 깊어졌지만 현실적 약속(만남의 형태, 관계의 방향)에는 조율이 필요한 시점이에요. 감정과 현실의 간극을 함께 좁혀가세요.","people":"상호 신뢰가 관계의 토대가 돼요. 감정의 깊이가 약속의 무게가 될 때 관계가 견고해져요.","reunion":"감정의 끌림이 여전히 살아 있어요. 다만 감정만이 아니라 서로의 진심과 약속을 함께 확인해야 해요.","career":"신뢰 기반의 협력이나 파트너십이 힘을 발휘하는 시기예요. 상호 신뢰가 성과를 만들어요.","money":"신뢰할 수 있는 협력이나 거래가 유리해요. 서로의 약속이 명확할 때 안정돼요.","advice":"감정을 믿되 현실적인 대화도 나누세요. 감정과 약속이 일치할 때 오래가는 결합이 돼요.","caution":"감정의 깊이에만 기대 현실 조건을 미루면, 신뢰의 균형이 흔들려요.","words":["상호 신뢰","감정의 깊이","결합"]},"r":{"line":"건네던 성배가 어긋나, 마음의 균형이 무너진 자리예요.","core":"감정의 균형이 무너지거나 신뢰에 금이 간 상태예요. 한쪽으로 기운 마음이나 오해가 관계를 흔들어요.","mind":"지금 마음은 신뢰와 불안 사이에서 흔들리며, 상대의 진심을 확신하지 못하는 상태예요.","daily":"오늘은 어긋난 감정이나 오해를 솔직히 풀어보세요. 방치하면 멀어져요.","love":"감정은 있지만 불균형이나 오해로 어긋나요. 약속에 대한 두려움이 솔직한 대화를 막고 있을 수 있어요.","people":"주고받음의 균형이 무너져 신뢰가 흔들려요. 어긋난 마음을 솔직히 마주해야 해요.","reunion":"감정은 남아 있지만 신뢰가 흔들려 있어요. 오해를 먼저 풀어야 다시 이어질 수 있어요.","career":"협력이나 신뢰에 균열이 생길 수 있어요. 오해를 풀고 약속을 명확히 하세요.","money":"거래나 협력의 신뢰가 흔들릴 수 있어요. 조건과 약속을 다시 확인하세요.","advice":"어긋난 신뢰를 덮지 마세요. 오해를 풀고 균형을 회복하는 대화가 먼저예요.","caution":"불균형과 오해를 미룰수록, 감정의 골이 깊어져요.","words":["불균형","신뢰 균열","오해"]}},"C03":{"name":"컵 3","number":3,"arcana":"minor","suit":"cups","element":"water","u":{"line":"잔을 높이 든 세 사람이 함께 어울려 기쁨을 나누는, 우정과 축하의 자리예요.","core":"함께하는 기쁨과 정서적 지지가 넘치는 카드예요. 사람들과 어울리며 마음을 나눌 때 활력과 위로가 채워져요.","mind":"지금 당신은 사람들과 어울리며 즐거움과 지지를 나누고 싶은 상태예요.","daily":"오늘은 사람들과 즐겁게 어울려 보세요. 함께 나누는 기쁨이 활력을 줘요.","love":"즐겁고 밝은 만남이 있는 시기예요. 함께 웃고 어울리는 가벼운 기쁨이 관계에 활력을 줘요.","people":"서로를 지지하며 함께하는 기쁨이 커지는 때예요. 밝은 어울림이 관계를 따뜻하게 해요.","reunion":"따뜻한 재회나 화합의 기운이 있어요. 편안하고 즐거운 만남으로 다가가면 마음이 열려요.","career":"함께할 때 성과와 기쁨이 커져요.","money":"함께하는 일이나 좋은 인연이 재물의 기회가 돼요. 협력의 흐름을 살리세요.","advice":"혼자 애쓰지 말고 사람들과 기쁨을 나누세요. 함께하는 지지가 큰 힘이 돼요.","caution":"즐거움이 지나쳐 방종이 되거나, 어울림에 취해 할 일을 놓치지 마세요.","words":["우정","축하","함께하는 기쁨"]},"r":{"line":"즐겁던 모임이 공허해지거나, 어울림에서 소외된 자리예요.","core":"어울림이 과하거나 반대로 관계가 소원해진 상태예요. 함께 있어도 공허하거나, 가십·소모적 모임에 지쳐요.","mind":"지금 마음은 어울려도 공허하거나, 소외감을 느끼는 상태예요.","daily":"오늘은 소모적인 자리보다, 진짜 위로가 되는 사람과 시간을 보내세요.","love":"만남이 겉돌거나 즐거움이 공허하게 느껴져요. 진짜 마음이 통하는 관계를 찾으세요.","people":"어울림이 소모적이거나 관계가 소원해져요. 진정한 지지가 무엇인지 돌아보세요.","reunion":"겉으로는 화기애애해도 진심이 닿지 않을 수 있어요. 형식적인 만남을 넘어서야 해요.","career":"협업이 겉돌거나 소모적일 수 있어요. 형식적 모임보다 실질적 협력에 집중하세요.","money":"소모적인 지출이나 어울림을 조심하세요. 실속 있는 관계에 집중하세요.","advice":"겉도는 어울림에 지치지 마세요. 진짜 마음이 통하는 관계에 에너지를 쓰세요.","caution":"공허한 어울림을 반복하면, 함께 있어도 외로움만 커져요.","words":["과잉","관계 소원","가십"]}},"C04":{"name":"컵 4","number":4,"arcana":"minor","suit":"cups","element":"water","u":{"line":"팔짱을 낀 채 눈앞에 건네진 성배마저 시큰둥하게 바라보는, 권태와 무관심의 자리예요.","core":"익숙함에 무뎌져 눈앞의 기회조차 시큰둥해진 카드예요. 마음이 안으로 침잠해, 지금 있는 것의 가치를 다시 볼 때예요.","mind":"지금 당신의 마음은 권태나 무기력으로, 무엇에도 큰 흥미를 못 느끼는 상태예요.","daily":"오늘은 무기력할 수 있어요. 눈앞의 작은 것에서 다시 의미를 찾아보세요.","love":"관계가 익숙해져 설렘이 무뎌진 시기예요. 권태에 빠져 눈앞의 소중함을 놓치고 있진 않은지 돌아보세요.","people":"관계에 무관심이나 권태가 스며들어요. 익숙함에 가려진 소중함을 다시 발견해야 해요.","reunion":"지금은 마음이 시큰둥하거나 지쳐 있을 수 있어요. 억지로 움직이기보다 진짜 마음을 들여다보세요.","career":"일에 권태나 무기력을 느끼는 시기예요. 눈앞의 기회를 시큰둥하게 넘기지 마세요.","money":"새 기회에 무관심해 놓칠 수 있어요. 익숙함에 가려진 가능성을 살펴보세요.","advice":"권태에 빠져 눈앞의 기회를 흘리지 마세요. 지금 있는 것의 가치를 다시 들여다보세요.","caution":"무관심에 머물면, 건네진 기회가 조용히 거둬져요.","words":["권태","무관심","재점검"]},"r":{"line":"팔짱을 풀고 눈앞의 성배로 손을 뻗는, 관심과 활력이 돌아오는 자리예요.","core":"권태에서 벗어나 관심과 활력이 돌아오는 상태예요. 새로운 시각으로 눈앞의 기회를 다시 보기 시작해요.","mind":"지금 마음은 무기력에서 벗어나 다시 의욕과 관심이 살아나는 상태예요.","daily":"오늘은 무기력을 털고 눈앞의 것에 다시 관심을 가져보세요.","love":"눈앞의 소중함을 새롭게 발견하는 시기예요.","people":"새로운 마음으로 다가가세요.","reunion":"시큰둥했던 마음이 다시 움직이기 시작해요. 관심을 회복하면 흐름이 열려요.","career":"권태에서 벗어나 다시 동기가 생기는 시기예요. 흘려보낸 기회를 다시 보세요.","money":"무관심했던 기회에 다시 눈이 가요. 새로운 시각으로 살펴보세요.","advice":"돌아온 관심을 살리세요. 새로운 시각으로 보면, 흘려보낸 기회가 다시 보여요.","caution":"관심이 돌아왔을 때 움직이지 않으면, 다시 권태로 가라앉아요.","words":["관심 회복","새 시각","권태 탈출"]}},"C05":{"name":"컵 5","number":5,"arcana":"minor","suit":"cups","element":"water","u":{"line":"쏟아진 세 잔을 바라보며 슬퍼하느라, 뒤에 남은 두 잔을 보지 못하는 자리예요.","core":"잃은 것에 대한 슬픔과 후회에 잠긴 카드예요. 아프지만, 쏟아진 잔만 보느라 아직 남아 있는 것을 놓치고 있진 않은지 살필 때예요.","mind":"지금 당신의 마음은 잃은 것에 대한 슬픔과 후회로 무겁게 가라앉아 있어요.","daily":"오늘은 슬픔이 밀려올 수 있어요. 충분히 애도하되, 남은 것도 잊지 마세요.","love":"상실감이나 후회로 마음이 아픈 시기예요. 지나간 것에만 매이지 말고 아직 남은 것을 보세요.","people":"실망이나 상처로 슬픔이 커요. 잃은 것을 애도하되, 남아 있는 관계의 가치를 잊지 마세요.","reunion":"지난 일에 대한 후회와 슬픔이 커요. 쏟아진 것만 보기보다 아직 남은 가능성을 살펴보세요.","career":"실패나 상실로 아쉬움이 큰 시기예요. 잃은 것에 매이지 말고 남은 자원을 보세요.","money":"손실이나 후회가 있는 시기예요. 지난 손실보다 남은 것을 지키는 데 집중하세요.","advice":"잃은 것을 충분히 애도하세요. 다만 쏟아진 잔만 보지 말고, 아직 남은 두 잔을 기억하세요.","caution":"후회에만 잠겨 있으면, 아직 남은 소중한 것마저 흘려보내요.","words":["상실","후회","슬픔"]},"r":{"line":"쏟아진 잔에서 눈을 돌려, 뒤에 남은 잔을 발견하고 일어서는 자리예요.","core":"슬픔을 지나 회복이 시작되는 상태예요. 잃은 것을 받아들이고, 남아 있는 것을 발견하며 앞으로 나아가요.","mind":"지금 마음은 슬픔을 지나 조금씩 회복되며, 앞을 볼 여유가 생기고 있어요.","daily":"오늘은 지난 슬픔을 털고, 남아 있는 것에 감사해 보세요.","love":"상처가 아물고 마음이 회복되는 시기예요. 지난 일을 용서하고 앞을 보기 시작해요.","people":"슬픔을 정리하고 관계를 회복하려는 흐름이에요. 남아 있는 소중함을 다시 봐요.","reunion":"후회를 정리하고 다시 나아갈 여지가 생겨요. 지난 것을 용서하면 새 흐름이 열려요.","career":"실패를 딛고 회복하는 시기예요. 남은 자원으로 다시 시작할 수 있어요.","money":"손실을 정리하고 회복하는 흐름이에요. 남은 것을 기반으로 다시 세우세요.","advice":"잃은 것을 용서하고 놓아주세요. 남아 있는 것을 발견하면, 회복이 시작돼요.","caution":"회복이 시작됐어도 서두르진 마세요. 상처가 아무는 데는 시간이 필요해요.","words":["회복","용서","앞으로 나아감"]}},"C06":{"name":"컵 6","number":6,"arcana":"minor","suit":"cups","element":"water","u":{"line":"옛 정원에서 순수했던 시절의 꽃을 주고받는, 추억과 그리움의 자리예요.","core":"따뜻했던 과거의 기억이 되살아나는 카드예요. 순수했던 시절의 온기가 마음을 채우며, 옛 인연이 다시 이어질 여지를 비춰요.","mind":"지금 당신의 마음은 따뜻했던 추억과 그리움으로 채워져 있어요.","daily":"오늘은 따뜻한 추억을 떠올리거나 옛 인연과 연결되기 좋은 날이에요.","love":"따뜻한 추억이 마음을 채우는 시기예요. 순수한 감정으로 다가가면 관계에 온기가 돌아요.","people":"함께한 추억이 관계를 따뜻하게 해요. 초심의 순수함을 되새기면 마음이 이어져요.","reunion":"따뜻했던 과거 기억이 아직 살아 있어 감정의 문이 완전히 닫히지 않은 상태예요. 다만 추억만으로는 재회가 유지되지 않아 현실 조율이 필요해요.","career":"과거의 경험이나 인연이 도움이 되는 시기예요. 익숙한 기반을 다시 살펴보세요.","money":"과거의 인연이나 익숙한 방식이 기회가 돼요. 다만 옛것에만 기대진 마세요.","advice":"따뜻한 추억을 소중히 하되, 과거를 소환할 때는 지금 달라진 모습도 함께 보여주세요.","caution":"좋았던 기억만 강조하면, 과거의 갈등이 지워진 것처럼 보여 오히려 경계를 불러요.","words":["그리움","추억","미완 감정"]},"r":{"line":"과거의 정원에서 나오지 못하고, 미화된 기억에 붙들린 자리예요.","core":"과거에 집착하거나 미화된 기억에 갇힌 상태예요. 지난날에 머물러 현실의 성장을 외면하고 있어요.","mind":"지금 마음은 지난날에 붙들려, 현실보다 과거를 그리워하는 상태예요.","daily":"오늘은 과거에 머물기보다, 지금 할 수 있는 것에 눈을 돌려보세요.","love":"지난 추억에만 매여 현실을 못 보는 시기예요. 미화된 기억과 실제를 구분해야 해요.","people":"과거에 갇혀 현재의 관계가 나아가지 못해요. 지난날을 놓고 지금을 봐야 해요.","reunion":"추억의 힘은 남아 있지만 과거에 갇힌 감정이 정리를 방해해요. 미련과 현실 사이에서 흔들려 접촉 타이밍이 늦어지기 쉬워요.","career":"옛 방식에만 기대 정체될 수 있어요. 과거 경험을 넘어 현재에 맞게 갱신하세요.","money":"익숙한 과거 방식이 오히려 발목을 잡을 수 있어요. 현실에 맞게 점검하세요.","advice":"미화된 과거에 갇히지 마세요. 추억은 간직하되, 지금의 현실을 딛고 나아가세요.","caution":"과거를 이상화할수록, 현재의 소중함이 초라해 보여요.","words":["과거 고착","미련","현실 회피"]}},"C07":{"name":"컵 7","number":7,"arcana":"minor","suit":"cups","element":"water","u":{"line":"구름 위로 떠오른 일곱 개의 성배 속 환영들을 바라보며 갈피를 못 잡는 자리예요.","core":"여러 가능성과 환상이 눈앞에 어른거리는 카드예요. 선택지는 많아 보이지만, 무엇이 진짜이고 무엇이 몽상인지 가려야 할 때예요.","mind":"선택지가 많아서가 아니라, 비교 기준을 외부에 둘 때 자기 신뢰가 무너져요.","daily":"오늘은 상상이 부풀 수 있어요. 무엇이 진짜인지 현실적으로 따져보세요.","love":"이상과 환상이 앞서는 시기예요. 상대를 환상 속에서 보고 있진 않은지, 현실의 모습을 확인하세요.","people":"기대나 상상이 실제를 앞질러요. 환상과 현실을 구분해야 관계가 명확해져요.","reunion":"이상화된 기대가 클 수 있어요. 환상 속 상대가 아니라 실제 상황을 냉정히 봐야 해요.","career":"여러 기회가 어른거리지만 실체가 불분명해요. 환상을 걷고 현실적인 것을 고르세요.","money":"솔깃한 기회가 많아 보이지만 검증이 필요해요. 그럴듯한 환상을 조심하세요.","advice":"결정을 미루는 이유를 설명하지 말고, 오늘 마감 시간을 정해 하나를 선택하세요.","caution":"가능성 비교만 반복하면 실제 삶의 주도권이 계속 늦춰져요.","words":["환상","비교","선택 과부하"]},"r":{"line":"구름 속 환영이 걷히고, 진짜 손에 쥘 성배가 드러나는 자리예요.","core":"환상이 걷히고 현실이 또렷해지는 상태예요. 몽상에서 벗어나 무엇이 진짜인지 가려내며 결단해요.","mind":"지금 마음은 혼란이 걷히고 무엇을 원하는지 또렷해지는 상태예요.","daily":"오늘은 혼란이 정리되고 무엇을 할지 분명해져요. 결단할 때예요.","love":"환상이 걷히고 상대의 실제 모습이 보이기 시작해요. 현실을 바탕으로 판단하세요.","people":"기대와 현실을 구분하며 관계가 명확해져요. 환상 대신 실제에 집중하세요.","reunion":"이상화가 걷히고 현실이 보여요. 냉정한 판단으로 진짜 가능성을 가려내세요.","career":"여러 선택지 중 실체 있는 것이 드러나요. 명확한 하나에 집중하세요.","money":"그럴듯한 환상이 걷히고 진짜 기회가 보여요. 검증된 것을 택하세요.","advice":"결정 기준 1줄을 먼저 적고 그 기준에 맞는 선택만 남기세요.","caution":"정리 단계에서 갑작스러운 단절형 거절은 죄책감을 키울 수 있어요.","words":["환상 해체","선택 정리","기준 회복"]}},"C08":{"name":"컵 8","number":8,"arcana":"minor","suit":"cups","element":"water","u":{"line":"쌓아둔 성배를 뒤로하고 달빛 아래 홀로 산을 향해 떠나는, 더 깊은 것을 찾는 자리예요.","core":"채워지지 않는 것을 뒤로하고 더 깊은 의미를 찾아 떠나는 카드예요. 익숙한 것을 놓는 아쉬움 속에서도, 진짜 원하는 것을 향해 나아가요.","mind":"지금 당신의 마음은 표면적 만족에 채워지지 않아, 더 깊은 것을 찾고 싶은 상태예요.","daily":"오늘은 채워지지 않는 것을 붙들기보다, 진짜 원하는 방향을 물어보세요.","love":"표면적 만족을 넘어 진짜 마음을 찾는 시기예요. 채워지지 않는 관계라면 방향을 다시 물을 때예요.","people":"지금의 관계에서 더 깊은 의미를 찾으려는 때예요. 무엇이 부족한지 솔직히 마주하세요.","reunion":"떠나야 할지 남아야 할지 마음이 깊어지는 시기예요. 진짜 원하는 것이 무엇인지 물어보세요.","career":"지금의 자리에서 채워지지 않는 의미를 찾아 방향을 바꾸려는 시기예요.","money":"익숙하지만 만족스럽지 않은 방식을 떠나 새 방향을 찾을 때예요.","advice":"채워지지 않는 것을 억지로 붙들지 마세요. 아쉬워도 더 깊은 의미를 향해 나아갈 때예요.","caution":"떠남이 회피가 되지 않게, 무엇을 찾아 떠나는지 분명히 하세요.","words":["떠남","더 깊은 의미 추구","미련 없이 놓기"]},"r":{"line":"떠나야 할지 남아야 할지 정하지 못한 채 제자리에서 표류하는 자리예요.","core":"떠나지도 머물지도 못하고 미련에 붙들린 상태예요. 방향을 못 정한 채 표류하거나 회피하고 있어요.","mind":"지금 마음은 놓지도 나아가지도 못한 채, 방향을 잃고 표류하는 상태예요.","daily":"오늘은 미뤄둔 결정을 마주해 보세요. 표류를 끝내는 것은 결단이에요.","love":"채워지지 않으면서도 놓지 못해 관계에 매여 있어요. 미련과 진심을 구분해야 해요.","people":"떠날 용기도 머물 확신도 없어 관계가 표류해요. 방향을 정직하게 물으세요.","reunion":"미련 때문에 놓지 못하거나, 결정을 회피하고 있어요. 진짜 마음을 마주하세요.","career":"떠나지도 남지도 못해 정체될 수 있어요. 방향을 분명히 정하세요.","money":"미련 때문에 손실을 못 놓거나, 방향 없이 표류할 수 있어요. 결단이 필요해요.","advice":"미련에 붙들려 표류하지 마세요. 떠날지 머물지, 진짜 마음을 마주하고 정하세요.","caution":"떠나지도 머물지도 못하는 상태가 길어지면, 마음만 소진돼요.","words":["떠나지 못함","미련","표류"]}},"C09":{"name":"컵 9","number":9,"arcana":"minor","suit":"cups","element":"water","u":{"line":"아홉 개의 성배를 뒤에 두고 흡족하게 앉아 있는, 만족과 소원 성취의 자리예요.","core":"바라던 것이 이뤄져 마음이 흡족하게 채워지는 '소원의 카드'예요. 감정적 충족과 여유가 찾아와 자족할 수 있어요.","mind":"지금 당신의 마음은 바라던 것이 채워져, 흡족하고 여유로운 상태예요.","daily":"오늘은 만족스럽고 여유로운 하루가 될 수 있어요. 이룬 것에 감사하세요.","love":"관계에 만족과 행복이 채워지는 시기예요. 바라던 마음이 이뤄져 여유롭게 사랑할 수 있어요.","people":"서로에게 만족하며 편안한 행복을 누리는 때예요. 감정적 충족이 관계를 안정시켜요.","reunion":"바라던 흐름이 이뤄질 가능성이 있는 시기예요. 여유롭고 만족스러운 마음으로 다가가세요.","career":"노력의 결실로 만족스러운 성과를 얻는 시기예요. 이룬 것을 충분히 누리세요.","money":"재정적으로 만족스러운 결실을 거두는 흐름이에요. 여유가 생겨요.","advice":"바라던 것이 이뤄지고 있어요. 이룬 것을 충분히 누리고 감사하세요.","caution":"만족에 안주해 자만하면, 채워진 것이 당연해져 감사를 잃어요.","words":["만족","소원 성취","감정적 충족"]},"r":{"line":"성배는 가득한데 마음 한켠이 허전한, 채워지지 않는 만족의 자리예요.","core":"겉으로는 채워졌으나 속은 허전하거나, 과욕으로 만족을 모르는 상태예요. 표면적 충족이 진짜 만족이 아님을 느껴요.","mind":"지금 마음은 가진 것에도 만족하지 못하거나, 채워지지 않는 허전함을 느껴요.","daily":"오늘은 더 채우려 하기보다, 이미 가진 것의 가치를 돌아보세요.","love":"겉으로 괜찮아 보여도 마음이 채워지지 않아요. 진짜 원하는 것이 무엇인지 물어보세요.","people":"표면적 만족 뒤에 허전함이 있어요. 진정한 충족이 무엇인지 돌아보세요.","reunion":"바라는 것을 이뤄도 허전할 수 있어요. 진짜 원하는 것이 맞는지 확인하세요.","career":"성과에도 만족이 안 되거나 과욕이 앞설 수 있어요. 진짜 목표를 점검하세요.","money":"겉으로 채워져도 과욕으로 허전할 수 있어요. 무엇이 진짜 만족인지 보세요.","advice":"겉의 만족에 속지 마세요. 과욕을 내려놓고, 진짜 마음을 채우는 것이 무엇인지 물으세요.","caution":"채워도 허전함이 반복된다면, 방향 자체를 다시 봐야 해요.","words":["헛된 만족","과욕","표면적 충족"]}},"C10":{"name":"컵 10","number":10,"arcana":"minor","suit":"cups","element":"water","u":{"line":"무지개 아래 온 가족이 손을 맞잡고 기뻐하는, 정서적 충만과 화합의 자리예요.","core":"마음이 온전히 채워져 화합을 이루는 카드예요. 사랑과 유대가 지속되는 행복으로 무르익어, 관계의 완성에 일러요.","mind":"지금 당신의 마음은 사랑과 화합으로 충만해, 깊은 행복을 느끼는 상태예요.","daily":"오늘은 사랑하는 사람들과 따뜻한 시간을 보내기 좋은 날이에요.","love":"깊은 사랑과 화합이 무르익는 시기예요. 서로의 마음이 온전히 통하는 충만한 관계예요.","people":"정서적으로 완성된 조화로운 관계예요. 지속되는 사랑과 유대가 행복을 줘요.","reunion":"따뜻한 화합의 기운이 강해요. 진심 어린 마음으로 다가가면 온전히 이어질 여지가 커요.","career":"마음이 온전히 채워져 화합을 이루는 카드예요. 사랑과 유대가 지속되는 행복으로 무르익어, 관계의 완성에 일러요.","money":"안정과 화합 속에서 풍요를 누리는 흐름이에요. 함께 나누는 기쁨이 커요.","advice":"지금의 화합과 사랑을 충분히 누리고 감사하세요. 온전한 마음이 관계를 완성해요.","caution":"이상적인 화합에 안주해 노력을 놓으면, 무지개는 서서히 흐려져요.","words":["정서적 충만","화합","가정의 행복"]},"r":{"line":"무지개가 흐려지고, 겉의 화목 뒤에 균열이 감춰진 자리예요.","core":"겉으로는 화목해 보여도 속에 균열이 있는 상태예요. 이상과 현실의 괴리로 진짜 화합이 흔들려요.","mind":"지금 마음은 화목을 바라면서도, 채워지지 않는 괴리감으로 흔들리는 상태예요.","daily":"오늘은 겉의 화목보다 속의 진심을 살펴보세요. 진짜 유대가 필요해요.","love":"겉으로 안정돼 보여도 마음이 겉돌아요. 이상과 현실의 간극을 솔직히 마주해야 해요.","people":"화합에 금이 가거나 정서적 거리가 생겨요. 진짜 유대를 회복하는 노력이 필요해요.","reunion":"겉으로 화기애애해도 진심이 닿지 않을 수 있어요. 이상보다 현실을 봐야 해요.","career":"겉으로 화합해 보여도 속에 불협화음이 있을 수 있어요. 진짜 소통이 필요해요.","money":"안정돼 보여도 속에 불안이 있을 수 있어요. 겉치레보다 실속을 챙기세요.","advice":"이상적인 그림에 매이지 마세요. 겉의 화합보다 속의 진짜 마음을 회복하세요.","caution":"괴리를 덮고 화목한 척하면, 균열이 안에서 더 커져요.","words":["화합 균열","이상과 현실 괴리","가정 불화"]}},"C11":{"name":"컵 페이지","number":11,"arcana":"minor","suit":"cups","element":"water","u":{"line":"성배 속에서 떠오른 물고기를 신기하게 바라보는, 순수하고 섬세한 감성의 자리예요.","core":"순수한 감성과 창의적 영감이 피어나는 카드예요. 마음이 섬세하게 열려 새로운 감정이나 반가운 소식을 맞이해요.","mind":"지금 당신의 마음은 섬세하고 순수하게 열려, 새로운 감정을 맞이하는 상태예요.","daily":"오늘은 섬세한 감성이나 반가운 소식이 있을 수 있어요. 마음을 열어보세요.","love":"설레는 새 감정이나 고백의 소식이 있는 시기예요. 순수하고 진솔한 마음이 상대에게 닿아요.","people":"섬세하고 다정한 감정이 관계를 따뜻하게 해요. 순수한 표현이 마음을 이어요.","reunion":"감성적인 신호나 반가운 소식이 올 수 있는 시기예요. 순수한 마음으로 다가가세요.","career":"창의적 영감이나 반가운 제안이 오는 시기예요. 섬세한 감각을 살리세요.","money":"작지만 반가운 기회의 소식이 있을 수 있어요. 직감을 살펴보세요.","advice":"순수한 마음과 섬세한 감성을 소중히 하세요. 진솔한 표현이 마음을 이어요.","caution":"감성에만 젖어 현실을 놓치면, 섬세함이 여림이 돼요.","words":["감성적 소식","순수한 마음","창의적 영감"]},"r":{"line":"성배 속 물고기에 놀라 마음이 흔들리는, 여리고 서투른 감정의 자리예요.","core":"감정이 미성숙하거나 상처받기 쉬운 상태예요. 섬세함이 지나쳐 여려지거나, 감정 표현이 서툴러 엉켜요.","mind":"지금 마음은 여리고 흔들려, 작은 일에도 쉽게 상처받는 상태예요.","daily":"오늘은 여린 마음을 다독여 주세요. 상처에 너무 휘둘리지 마세요.","love":"감정이 여리거나 표현이 서툴러 마음이 엇갈려요. 상처를 두려워하기보다 솔직해지세요.","people":"감정 기복이나 미성숙한 표현이 관계를 흔들어요. 마음을 다잡는 것이 필요해요.","reunion":"감정이 여리거나 서툴러 마음을 전하기 어려워요. 조급하지 말고 마음을 다독이세요.","career":"감정적으로 예민하거나 현실 감각이 흐려질 수 있어요. 마음을 추스르세요.","money":"감성적 판단이나 현실 도피를 조심하세요. 현실을 함께 보세요.","advice":"여린 감정을 탓하지 마세요. 마음을 다독이되, 상처를 두려워 말고 솔직하게 표현하세요.","caution":"감정에만 매몰되면, 작은 일에도 크게 흔들려요.","words":["감정 미성숙","상처받기 쉬움","현실 도피"]}},"C12":{"name":"컵 기사","number":12,"arcana":"minor","suit":"cups","element":"water","u":{"line":"성배를 들고 우아하게 다가오는 낭만적인 기사의 자리예요.","core":"마음이 이끄는 대로 낭만을 좇는 카드예요. 감성적이고 이상적인 제안이나 다가옴이 있으며, 진심 어린 매혹이 흘러요.","mind":"지금 당신의 마음은 낭만과 이상을 좇으며, 감성적으로 움직이고 싶은 상태예요.","daily":"오늘은 마음이 이끄는 대로 낭만을 좇아보세요. 진심이 흐름을 열어요.","love":"낭만적인 제안이나 다가옴이 있는 시기예요. 마음이 이끄는 대로 진심을 전하면 통해요.","people":"감성적이고 낭만적인 흐름이 관계를 아름답게 해요. 진심 어린 표현이 마음을 이어요.","reunion":"낭만적인 제안이나 감성적 다가옴이 있을 수 있는 시기예요. 진심으로 다가가세요.","career":"감성이나 이상이 이끄는 제안이 오는 시기예요. 진정성을 담아 응하세요.","money":"마음이 끌리는 기회가 있을 수 있어요. 다만 낭만과 현실을 함께 보세요.","advice":"마음이 이끄는 낭만을 따르되, 진심을 담으세요. 이상과 현실의 균형이 관계를 아름답게 해요.","caution":"낭만에만 취해 현실을 놓치면, 아름다운 제안도 공허해져요.","words":["낭만","이상 추구","감성적 제안"]},"r":{"line":"우아하던 기사가 방향을 잃고, 낭만이 공허하게 흩어지는 자리예요.","core":"이상이 비현실적으로 흐르거나, 감정 기복으로 진실성이 흔들리는 상태예요. 낭만이 공허해지기 쉬워요.","mind":"지금 마음은 이상과 현실 사이에서 흔들리며, 감정이 변덕스러운 상태예요.","daily":"오늘은 낭만적 기분에 휩쓸리기 전에 현실을 한 번 점검해 보세요.","love":"말과 행동이 다르거나, 낭만이 공허하게 느껴져요. 진심과 겉치레를 구분하세요.","people":"감정 기복이나 비현실적 기대가 관계를 흔들어요. 이상보다 진심을 봐야 해요.","reunion":"낭만적 제안이 진심인지 확인이 필요해요. 말보다 실제 행동을 보세요.","career":"감성적 제안의 진정성을 확인하세요. 말보다 실체를 보세요.","money":"그럴듯한 감성적 제안을 조심하세요. 진짜인지 검증이 필요해요.","advice":"낭만이 공허해지지 않게 하세요. 이상만 좇지 말고, 진심과 현실을 함께 담으세요.","caution":"말과 행동이 다른 낭만은, 결국 신뢰를 무너뜨려요.","words":["비현실적 이상","변덕","감정 기복"]}},"C13":{"name":"컵 퀸","number":13,"arcana":"minor","suit":"cups","element":"water","u":{"line":"바닷가 왕좌에 앉아 성배를 깊이 들여다보는, 감정적 지혜와 공감의 자리예요.","core":"깊은 공감과 직관으로 마음을 헤아리는 카드예요. 따뜻한 포용력과 정서적 지혜로 자신과 상대의 감정을 부드럽게 품어요.","mind":"지금 당신의 마음은 깊고 차분해, 감정을 지혜롭게 헤아릴 수 있는 상태예요.","daily":"오늘은 따뜻한 공감으로 사람을 대해보세요. 깊은 이해가 마음을 이어요.","love":"깊은 공감과 따뜻함으로 사랑하는 시기예요. 상대의 마음을 헤아리는 포용력이 관계를 깊게 해요.","people":"정서적 지혜와 공감이 관계를 성숙하게 해요. 서로의 감정을 부드럽게 품어줘요.","reunion":"따뜻한 공감과 포용으로 다가가면 마음이 열려요. 상대의 감정을 헤아려 주세요.","career":"공감과 배려로 사람들을 아우르는 시기예요. 정서적 지혜가 신뢰를 얻어요.","money":"직관과 신중함이 좋은 판단을 돕는 시기예요. 마음의 소리를 살펴보세요.","advice":"따뜻한 공감과 직관을 믿으세요. 자신과 상대를 부드럽게 품는 지혜가 관계를 깊게 해요.","caution":"남을 다 품으려다 정작 자신의 감정을 소홀히 하지 마세요.","words":["감정적 깊이","공감","직관"]},"r":{"line":"성배의 물이 넘쳐 감정에 휩쓸리는, 경계를 잃은 자리예요.","core":"감정이 과잉되거나 경계를 잃은 상태예요. 남을 품느라 자신을 소홀히 하거나, 감정에 휩쓸려 흔들려요.","mind":"지금 마음은 감정이 넘쳐 흔들리거나, 남을 챙기느라 지친 상태예요.","daily":"오늘은 남보다 자신의 감정을 먼저 돌보세요. 경계를 지키는 것이 필요해요.","love":"감정 과잉이나 지나친 헌신이 관계를 무겁게 해요. 자신을 돌보는 균형이 필요해요.","people":"감정에 휩쓸리거나 경계가 무너져 지쳐요. 자신과 상대 사이의 선을 지키세요.","reunion":"감정이 앞서 휘둘리기 쉬워요. 마음을 다스린 뒤 다가가세요.","career":"감정적 판단이나 과한 배려로 소진될 수 있어요. 균형을 회복하세요.","money":"감정에 휘둘린 결정을 조심하세요. 차분히 사실로 판단하세요.","advice":"감정에 휩쓸리지 마세요. 남을 품기 전에 자신을 먼저 돌보고, 마음의 경계를 지키세요.","caution":"경계 없이 다 품으려다, 자신의 감정이 먼저 무너져요.","words":["감정 과잉","경계 상실","자기소홀"]}},"C14":{"name":"컵 킹","number":14,"arcana":"minor","suit":"cups","element":"water","u":{"line":"출렁이는 바다 위 왕좌에서도 흔들림 없이 성배를 든, 감정의 균형을 이룬 왕의 자리예요.","core":"격한 감정 속에서도 중심을 지키는 성숙의 카드예요. 차분한 지혜와 포용력으로 감정을 다스리며, 외유내강의 균형을 이뤄요.","mind":"지금 당신은 감정을 지혜롭게 다스리며, 흔들림 없이 중심을 지키는 상태예요.","daily":"오늘은 감정이 흔들려도 중심을 지켜보세요. 차분한 지혜가 상황을 안정시켜요.","love":"감정을 성숙하게 다스리며 안정적으로 사랑하는 시기예요. 차분한 포용이 관계를 든든하게 해요.","people":"감정의 균형과 지혜가 관계를 안정시켜요. 흔들림 없는 따뜻함이 신뢰를 줘요.","reunion":"차분하고 성숙한 태도로 다가가면 신뢰를 회복할 수 있어요. 감정을 다스려 안정감을 보이세요.","career":"감정을 다스리며 사람들을 아우르는 성숙한 리더십의 시기예요. 신뢰를 얻어요.","money":"차분하고 균형 잡힌 판단이 안정을 줘요. 감정에 휘둘리지 않는 운용이 유리해요.","advice":"격한 감정 속에서도 중심을 지키세요. 차분한 지혜와 포용이 관계와 일을 든든하게 해요.","caution":"감정을 다스리는 것과 억누르는 것은 달라요. 속마음도 돌보세요.","words":["감정의 균형","차분한 지혜","포용력"]},"r":{"line":"잔잔해 보이는 표면 아래 감정이 요동치는, 겉과 속이 어긋난 자리예요.","core":"감정을 억누르거나 겉과 속이 어긋난 상태예요. 차분한 척하지만 속은 불안정하거나, 감정을 조종하려 들 수 있어요.","mind":"지금 마음은 차분한 척하지만 속으로는 불안정하게 흔들리는 상태예요.","daily":"오늘은 억누른 감정을 솔직히 들여다보세요. 겉과 속을 일치시키는 것이 필요해요.","love":"감정을 억누르거나 겉과 속이 달라 진심이 닿지 않아요. 솔직하게 마음을 여세요.","people":"차분한 척 억누른 감정이 냉담이나 조종으로 흘러요. 진짜 마음을 솔직히 나누세요.","reunion":"겉으로는 담담해도 속은 흔들릴 수 있어요. 감정을 억누르기보다 진솔하게 마주하세요.","career":"감정을 억누르거나 겉과 속이 달라 신뢰가 흔들릴 수 있어요. 진솔함을 회복하세요.","money":"감정을 억누른 채 내린 결정을 조심하세요. 속마음을 정리한 뒤 판단하세요.","advice":"감정을 억누르지 마세요. 차분함을 가장하기보다, 속마음을 솔직히 마주하고 풀어내세요.","caution":"겉과 속이 계속 어긋나면, 차분함이 냉담이나 조종으로 변질돼요.","words":["감정 억압","냉담","감정 조종"]}},"S01":{"name":"소드 에이스","number":1,"arcana":"minor","suit":"swords","element":"air","u":{"line":"구름을 뚫고 솟은 한 자루의 검이 왕관을 꿰뚫는, 명료한 진실과 돌파의 자리예요.","core":"안개 같던 생각이 한순간에 또렷해지는 카드예요. 진실을 꿰뚫는 명료함과 결단으로, 얽힌 문제를 단번에 돌파할 힘이 있어요.","mind":"지금 당신의 마음은 또렷해져, 무엇이 진실인지 분명히 알고 결단하려는 상태예요.","daily":"오늘은 애매하던 것이 또렷해져요. 명확하게 결단하기 좋은 날이에요.","love":"관계의 진실이나 마음이 명확해지는 시기예요. 애매함을 걷어내고 솔직하게 마주할 때 방향이 잡혀요.","people":"명확한 소통이 관계를 정리하는 때예요. 돌려 말하기보다 진실을 분명히 전하세요.","reunion":"관계를 명확히 짚어볼 시기예요. 애매한 감정보다 진실을 직시하면 답이 분명해져요.","career":"명료한 판단과 결단으로 문제를 돌파하는 시기예요. 핵심을 꿰뚫으면 길이 열려요.","money":"명확한 분석과 결단이 유리해요. 애매함을 걷고 핵심을 짚으세요.","advice":"애매함을 걷어내고 진실을 직시하세요. 명료한 결단이 얽힌 문제를 단번에 돌파해요.","caution":"날카로운 진실도 함부로 휘두르면 상처가 돼요. 명료함에 배려를 더하세요.","words":["명료함","돌파","진실"]},"r":{"line":"솟았던 검이 흐려져, 진실과 판단이 뒤엉킨 자리예요.","core":"생각이 뒤엉키고 판단이 흐려진 상태예요. 명료함을 잃어 진실이 왜곡되거나, 결단을 내리지 못해요.","mind":"지금 마음은 생각이 과부하되어 뒤엉키고, 무엇이 진실인지 확신하지 못하는 상태예요.","daily":"오늘은 생각이 복잡할 수 있어요. 결론을 서두르지 말고 정리부터 하세요.","love":"마음이나 진실이 애매해 혼란스러워요. 성급한 결론보다 사실을 다시 확인하세요.","people":"오해나 흐린 판단이 소통을 막아요. 명확해질 때까지 단정을 미루세요.","reunion":"판단이 흐려 성급히 결론 내리기 쉬워요. 진실이 분명해질 때까지 기다리세요.","career":"판단이 흐려지거나 정보가 왜곡될 수 있어요. 핵심을 다시 점검하세요.","money":"성급하거나 흐린 판단을 조심하세요. 사실을 재확인한 뒤 결정하세요.","advice":"뒤엉킨 생각을 먼저 정리하세요. 명료함을 회복한 뒤에 판단해도 늦지 않아요.","caution":"흐린 판단으로 날카로운 결론을 내리면, 오해와 상처만 커져요.","words":["혼란","판단 흐림","왜곡된 진실"]}},"S02":{"name":"소드 2","number":2,"arcana":"minor","suit":"swords","element":"air","u":{"line":"눈을 가린 채 두 자루의 검을 엇갈려 든, 결정을 미룬 교착의 자리예요.","core":"결정을 앞두고 어느 쪽도 택하지 못해 멈춘 카드예요. 감정을 차단한 채 균형만 잡고 있어, 언젠가는 눈을 뜨고 선택해야 해요.","mind":"지금 당신의 마음은 선택 앞에서 멈춰, 어느 쪽도 정하지 못한 채 감정을 눌러두고 있어요.","daily":"오늘은 미뤄둔 선택 하나를 마주해 보세요. 감정을 외면하면 답이 안 나와요.","love":"마음을 정하지 못해 관계가 멈춰 있는 시기예요. 감정을 외면하기보다 진짜 마음을 마주해야 해요.","people":"결정을 미루며 교착에 빠져 있어요. 회피하지 말고 솔직히 마주할 때 풀려요.","reunion":"다시 만날지 결정을 못 내리고 있어요. 감정을 차단한 채 미루면 교착만 길어져요.","career":"결정을 못 내려 일이 멈춰 있어요. 정보를 확인하고 선택할 때예요.","money":"결정을 미루다 기회를 놓칠 수 있어요. 회피보다 판단이 필요해요.","advice":"눈을 감은 채 균형만 잡지 마세요. 회피하던 감정을 마주하고, 어려워도 선택하세요.","caution":"결정을 미루는 것도 하나의 선택이며, 그 대가는 커져요.","words":["교착","어려운 선택","회피"]},"r":{"line":"가렸던 눈을 뜨고 엇갈린 검을 내려놓아, 교착이 풀리는 자리예요.","core":"멈췄던 결정이 풀리기 시작하는 상태예요. 차단했던 감정을 마주하고, 진실을 직면하며 선택으로 나아가요.","mind":"지금 마음은 멈춰 있던 감정을 마주하며, 선택할 준비가 되어가는 상태예요.","daily":"오늘은 미뤄둔 선택이 풀려요. 감정을 마주하고 결정하세요.","love":"미뤄둔 마음을 정하기 시작해요. 감정을 마주하며 관계의 방향이 잡혀요.","people":"교착이 풀리고 소통이 열려요. 진실을 마주하면 관계가 나아가요.","reunion":"결정을 내리거나 진실이 드러나며 교착이 풀려요. 감정을 직시할 때예요.","career":"멈췄던 일이 다시 움직여요. 정보가 공개되며 결정할 수 있게 돼요.","money":"미뤄둔 결정을 내릴 때예요. 회피를 끝내면 흐름이 풀려요.","advice":"차단했던 감정을 마주하세요. 진실을 직면하면 멈췄던 교착이 풀려요.","caution":"교착이 풀릴 때 성급히 밀어붙이면, 또 다른 갈등이 생길 수 있어요.","words":["교착 해소","결단","진실 직면"]}},"S03":{"name":"소드 3","number":3,"arcana":"minor","suit":"swords","element":"air","u":{"line":"세 자루의 검이 심장을 관통하고 비가 내리는, 마음의 상처와 슬픔의 자리예요.","core":"마음이 관통당하는 듯한 아픔의 카드예요. 아프지만, 이 슬픔은 외면했던 진실을 마주하고 정화하는 과정이기도 해요.","mind":"지금 당신의 마음은 상처와 슬픔으로 아파, 아픈 진실을 마주하고 있는 상태예요.","daily":"오늘은 마음이 아플 수 있어요. 슬픔을 억누르지 말고 충분히 흘려보내세요.","love":"상처나 이별의 아픔이 큰 시기예요. 슬픔을 억누르기보다 충분히 흘려보내는 것이 회복의 시작이에요.","people":"상처 주는 진실이나 갈등으로 마음이 아파요. 아픔을 외면하지 말고 정직하게 마주하세요.","reunion":"지난 상처가 아직 아물지 않았어요. 아픔을 충분히 정리해야 다시 나아갈 수 있어요.","career":"실망이나 아픈 현실을 마주하는 시기예요. 상처를 인정해야 다음으로 나아가요.","money":"손실이나 아픈 결정이 있는 시기예요. 현실을 직시하고 정리하세요.","advice":"아픔을 억누르지 마세요. 슬픔을 충분히 흘려보내고 진실을 마주할 때, 상처가 아물기 시작해요.","caution":"상처를 외면하고 덮어두면, 아픔이 곪아 더 오래가요.","words":["마음의 상처","슬픔","아픈 진실"]},"r":{"line":"심장을 찌르던 검이 하나씩 빠지며, 상처가 아물기 시작하는 자리예요.","core":"상처가 아물고 슬픔이 정리되는 상태예요. 아픔을 지나 용서와 화해로 회복이 시작돼요.","mind":"지금 마음은 아픔을 지나 조금씩 회복되며, 용서할 여유가 생기고 있어요.","daily":"오늘은 지난 슬픔을 조금씩 놓아보세요. 회복이 시작되고 있어요.","love":"상처가 아물고 마음이 회복되는 시기예요. 지난 아픔을 용서하며 앞으로 나아가요.","people":"갈등이 풀리고 화해로 나아가는 흐름이에요. 상처를 정리하면 관계가 회복돼요.","reunion":"지난 상처를 정리하고 다시 나아갈 여지가 생겨요. 용서가 회복의 열쇠예요.","career":"아픈 현실을 딛고 회복하는 시기예요. 상처를 교훈 삼아 다시 세우세요.","money":"손실을 정리하고 회복하는 흐름이에요. 지난 아픔을 딛고 나아가세요.","advice":"지난 아픔을 용서하고 놓아주세요. 상처를 정리할 때, 마음이 회복돼요.","caution":"회복이 시작됐어도 서두르지 마세요. 아문 상처도 다시 건드리면 아파요.","words":["상처 회복","용서","슬픔 정리"]}},"S04":{"name":"소드 4","number":4,"arcana":"minor","suit":"swords","element":"air","u":{"line":"검을 내려놓고 조용히 누워 힘을 회복하는, 휴식과 재충전의 자리예요.","core":"잠시 멈추고 힘을 회복하는 카드예요. 지친 몸과 마음에 휴식이 필요한 때이며, 물러남은 다음을 위한 준비예요.","mind":"지금 당신의 마음은 지쳐서 휴식이 필요하며, 잠시 멈추고 싶은 상태예요.","daily":"오늘은 무리하지 말고 충분히 쉬세요. 재충전이 곧 힘이 돼요.","love":"관계에서 잠시 거리를 두고 마음을 쉬는 시기예요. 재촉하지 말고 서로에게 여유를 주세요.","people":"잠시 멈추고 관계를 돌아보는 때예요. 조용한 휴식이 관계를 회복시켜요.","reunion":"지금은 다가가기보다 각자 회복하는 시간이 필요해요. 조급히 움직이지 마세요.","career":"무리하기보다 잠시 멈추고 재정비할 시기예요. 휴식이 다음 성과의 밑거름이에요.","money":"큰 결정을 미루고 잠시 관망할 때예요. 조급하지 말고 힘을 아끼세요.","advice":"지쳤다면 잠시 멈추세요. 물러나 힘을 회복하는 것이 다음을 위한 준비예요.","caution":"휴식이 지나쳐 정체가 되지 않도록, 회복 후엔 다시 움직이세요.","words":["휴식","회복","잠시 멈춤"]},"r":{"line":"쉬어야 할 몸이 일어나지 못하거나, 반대로 쉬지 못해 소진되는 자리예요.","core":"필요한 휴식을 거부해 번아웃되거나, 반대로 쉼이 길어져 정체된 상태예요. 회복의 리듬이 깨져 있어요.","mind":"지금 마음은 쉬어야 하는데 쉬지 못해 소진되었거나, 무기력에 빠진 상태예요.","daily":"무리하면 무너져요.","love":"지쳤는데도 쉬지 못해 관계가 소진되거나, 거리 두기가 길어져 멀어져요. 균형이 필요해요.","people":"재충전 없이 무리하다 지치거나, 회복이 길어져 정체돼요. 리듬을 회복하세요.","reunion":"회복이 지연되거나 지쳐서 움직이지 못할 수 있어요. 무리하지 말고 힘을 되찾으세요.","career":"소진되었는데 쉬지 못하거나, 정체가 길어질 수 있어요. 회복의 리듬을 잡으세요.","money":"무리한 강행이나 지나친 관망 모두 조심하세요. 균형 잡힌 재정비가 필요해요.","advice":"쉼을 미루지도, 지나치게 늘리지도 마세요. 회복의 리듬을 되찾는 것이 핵심이에요.","caution":"쉬지 못하고 밀어붙이면 번아웃, 쉼이 길어지면 정체예요. 리듬을 보세요.","words":["번아웃","휴식 거부","정체"]}},"S05":{"name":"소드 5","number":5,"arcana":"minor","suit":"swords","element":"air","u":{"line":"홀로 검을 챙기며 떠나는 사람들을 바라보는, 이겨도 공허한 갈등의 자리예요.","core":"이겨도 남는 것 없는 소모적 갈등의 카드예요. 자존심 싸움에서 승리해도, 관계와 마음을 잃는다면 진짜 이긴 것이 아니에요.","mind":"지금 당신의 마음은 이기고 싶은 자존심과, 그래도 남는 공허함 사이에서 흔들려요.","daily":"오늘은 다툼에서 이기려 들기보다, 무엇을 위한 싸움인지 돌아보세요.","love":"자존심 싸움이나 소모적 갈등이 있는 시기예요. 이기려 들수록 관계가 상해요. 무엇을 위한 다툼인지 물으세요.","people":"이기려는 마음이 관계를 갉아먹어요. 승부보다 관계를 지키는 것이 먼저예요.","reunion":"자존심이나 감정 싸움이 남아 있어요. 이기려 들기보다 먼저 손 내미는 용기가 필요해요.","career":"경쟁이나 갈등에서 이겨도 관계나 신뢰를 잃을 수 있어요. 실리와 관계를 함께 보세요.","money":"이해 다툼에서 이겨도 손해가 남을 수 있어요. 소모전을 피하세요.","advice":"이기는 데 매달리지 마세요. 자존심 싸움에서 승리해도 관계를 잃으면 진 것이에요.","caution":"이기려는 마음이 앞서면, 얻는 것보다 잃는 것이 훨씬 커요.","words":["소모적 갈등","이겨도 잃음","불화"]},"r":{"line":"챙기던 검을 내려놓고 떠난 이들에게 돌아서는, 화해의 자리예요.","core":"소모적 갈등이 끝나고 화해로 나아가는 상태예요. 자존심을 내려놓고 관계를 회복하려는 흐름이에요.","mind":"지금 마음은 소모적 싸움에 지쳐, 이제 화해하고 싶은 상태예요.","daily":"오늘은 묵은 갈등을 풀고 화해하기 좋은 날이에요. 먼저 손 내밀어 보세요.","love":"자존심 싸움을 끝내고 화해하려는 시기예요. 먼저 손 내밀면 관계가 회복돼요.","people":"다툼을 청산하고 관계를 회복하는 흐름이에요. 이기려던 마음을 내려놓으세요.","reunion":"자존심을 내려놓으면 화해의 여지가 생겨요. 먼저 다가가는 용기가 필요해요.","career":"경쟁이나 갈등이 일단락되는 시기예요. 관계를 회복하는 데 집중하세요.","money":"이해 다툼이 정리되는 흐름이에요. 소모전을 끝내고 실리를 챙기세요.","advice":"자존심을 내려놓으세요. 이기려던 마음을 놓을 때, 잃었던 관계를 되찾아요.","caution":"화해하려다 또 잘잘못을 따지면, 소모전이 다시 시작돼요.","words":["화해","갈등 청산","자존심 내려놓기"]}},"S06":{"name":"소드 6","number":6,"arcana":"minor","suit":"swords","element":"air","u":{"line":"잔잔한 물길을 따라 거친 곳을 떠나 고요한 물가로 향하는, 전환과 이동의 자리예요.","core":"거친 시기를 지나 잔잔한 곳으로 옮겨가는 카드예요. 극적이진 않아도, 조용히 한 국면을 벗어나 회복으로 나아가요.","mind":"지금 당신의 마음은 거친 시기를 벗어나, 잔잔한 곳으로 옮겨가려는 상태예요.","daily":"오늘은 힘든 것을 뒤로하고 조용히 나아가기 좋은 날이에요.","love":"힘든 시기를 지나 관계가 안정을 찾아가는 시기예요. 조급하지 않게 서서히 나아가세요.","people":"갈등의 시기를 지나 고요한 국면으로 옮겨가요. 차분히 회복의 흐름을 타세요.","reunion":"거친 감정의 시기를 지나 마음이 잔잔해지는 때예요. 서두르지 말고 서서히 다가가세요.","career":"어려운 시기를 지나 새 국면으로 전환하는 시기예요. 차분히 옮겨가세요.","money":"재정적 어려움을 지나 서서히 안정을 찾는 흐름이에요. 조급하지 마세요.","advice":"거친 시기를 벗어나고 있어요. 극적인 변화가 아니어도, 조용한 이동이 회복을 가져와요.","caution":"떠나면서도 짐(미련)을 다 안고 가면, 새 국면에서도 무거워요.","words":["전환","떠남","점진적 회복"]},"r":{"line":"떠나야 할 물가에서 배가 나아가지 못하고 맴도는 자리예요.","core":"벗어나야 할 곳을 떠나지 못하고 정체된 상태예요. 미련이나 두려움이 전환을 막고 있어요.","mind":"지금 마음은 떠나고 싶으면서도 미련에 붙들려 제자리에서 표류하는 상태예요.","daily":"오늘은 붙들고 있던 것을 놓고 나아갈 결심을 해보세요.","love":"힘든 관계를 놓지 못해 제자리를 맴돌아요. 떠날지 남을지 마음을 정해야 해요.","people":"갈등의 국면에서 벗어나지 못하고 반복돼요. 전환할 용기가 필요해요.","reunion":"미련 때문에 나아가지도 놓지도 못해요. 무엇이 발목을 잡는지 봐야 해요.","career":"어려운 국면에서 벗어나지 못해 정체될 수 있어요. 전환을 결단하세요.","money":"손실이나 어려움을 못 놓아 회복이 지연돼요. 미련을 끊을 때예요.","advice":"미련에 붙들려 표류하지 마세요. 벗어나야 할 곳이라면, 떠날 용기를 내세요.","caution":"전환을 미룰수록, 거친 자리에 더 오래 머물게 돼요.","words":["떠나지 못함","정체","미련"]}},"S07":{"name":"소드 7","number":7,"arcana":"minor","suit":"swords","element":"air","u":{"line":"남몰래 검을 챙겨 조용히 빠져나가는, 전략과 은밀함의 자리예요.","core":"정면 대결보다 기지와 전략으로 움직이는 카드예요. 다만 은밀함이 지나치면 기만이 되니, 처신에 신중함이 필요해요.","mind":"지금 당신의 마음은 정면 대결보다 전략적으로 움직이려 하며, 신중히 처신하고 있어요.","daily":"오늘은 신중하게 처신하되, 정직함을 잃지 마세요.","love":"속마음을 다 드러내지 않고 신중하게 움직이는 시기예요. 다만 솔직하지 못한 태도가 오해를 부를 수 있어요.","people":"전략적이거나 조심스러운 처신이 필요한 때예요. 감추는 것이 많으면 신뢰가 흔들려요.","reunion":"직접 부딪히기보다 신중하게 접근할 시기예요. 다만 진심을 감추면 역효과예요.","career":"정면 승부보다 전략적 접근이 유리한 시기예요. 다만 편법은 화를 불러요.","money":"신중하고 전략적인 판단이 필요해요.","advice":"기지를 발휘하되 정직함을 지키세요. 전략과 기만은 종이 한 장 차이예요.","caution":"기지를 발휘하되 정직함을 지키세요. 전략과 기만은 종이 한 장 차이예요.","words":["전략","은밀함","기지"]},"r":{"line":"몰래 챙기던 검을 들키거나, 스스로 양심에 걸려 되돌아오는 자리예요.","core":"감추던 것이 드러나거나 양심의 가책을 느끼는 상태예요.","mind":"지금 마음은 감추던 것에 대한 부담이나 가책으로, 정직해지고 싶은 상태예요.","daily":"오늘은 감추던 것을 솔직히 밝히는 편이 마음이 편해요.","love":"감추던 것이 드러나거나 솔직해지려는 시기예요. 진실을 밝히는 것이 관계를 살려요.","people":"숨긴 것이 드러나 신뢰가 흔들리거나, 정직을 회복하려 해요. 솔직함이 필요해요.","reunion":"감추던 진심을 드러내거나 정직해질 때예요. 솔직함이 흐름을 열어요.","career":"편법이나 감춘 것이 드러날 수 있어요. 정직하게 처리하세요.","money":"정직하고 투명하게 처리하세요.","advice":"감추던 것을 내려놓고 정직해지세요. 진실을 밝히는 것이 결국 자신을 지켜요.","caution":"감추던 것을 내려놓고 정직해지세요. 진실을 밝히는 것이 결국 자신을 지켜요.","words":["자기기만","양심의 가책","전략 실패"]}},"S08":{"name":"소드 8","number":8,"arcana":"minor","suit":"swords","element":"air","u":{"line":"눈을 가리고 검에 둘러싸여 스스로 묶인 듯 서 있는, 심리적 속박의 자리예요.","core":"실제로는 벗어날 수 있는데도 스스로 갇혔다고 믿는 카드예요. 두려움이 만든 제약일 뿐, 눈을 뜨면 탈출구가 보여요.","mind":"지금 당신의 마음은 갇힌 듯 답답하지만, 그 제약의 대부분은 스스로 만든 것이에요.","daily":"오늘은 스스로 만든 걱정의 틀을 인식하고 한 걸음 벗어나는 것이 핵심이에요.","love":"마음이 묶여 있어 표현하고 싶어도 쉽게 말을 꺼내지 못해요.","people":"선택지가 없다고 느끼지만 실제로는 열려 있어요. 스스로 만든 제약을 인식하세요.","reunion":"연락하고 싶은 마음은 분명하지만 두려움과 자존심이 동시에 걸려 스스로 움직임을 묶는 흐름이에요.","career":"선택지가 없다고 느끼지만 실제로는 탈출구가 열려 있는 카드예요.","money":"막막해 보여도 방법이 있어요. 두려움이 판단을 좁히지 않게 하세요.","advice":"생각은 맴도는데 행동이 멈춰 있진 않나요? 두려움이 만든 벽은 생각보다 낮아요. 눈을 뜨세요.","caution":"스스로 만든 제약을 실제라 믿을수록, 시간이 지나 오해가 굳어져요.","words":["심리적 구속","자존심","연락 망설임"]},"r":{"line":"가렸던 눈을 뜨고 묶인 줄을 풀며, 스스로 벗어나기 시작하는 자리예요.","core":"스스로 만든 속박을 자각하고 벗어나기 시작하는 상태예요. 두려움을 넘어 탈출구를 찾으며 자유를 회복해요.","mind":"지금 마음은 갇힌 느낌에서 벗어나, 스스로 만든 제약을 풀어가는 상태예요.","daily":"생각의 과부하를 줄이면 오늘의 흐름이 빠르게 가벼워져요.","love":"묶였던 감정이 조금씩 풀리며 솔직한 대화의 틈이 열려요.","people":"막혔던 마음이 풀리기 시작해요. 스스로 만든 벽을 넘으면 관계가 나아가요.","reunion":"막혀 있던 심리의 매듭이 조금씩 풀리지만, 바로 확신을 주는 연락보다는 조심스러운 탐색 접촉에 가까워요.","career":"답답함에서 벗어나 현실적인 선택지를 다시 보기 시작해요.","money":"막막함에서 벗어나 방법을 찾기 시작해요. 두려움을 걷으면 판단이 넓어져요.","advice":"두려움이 만든 벽을 자각했다면, 이제 한 걸음 벗어나세요. 다만 초기 단계이니 서두르진 마세요.","caution":"움직임이 보여도 불안정한 초기 단계라, 속도를 올리면 다시 닫힐 수 있어요.","words":["완화","재정비","조심스러운 접촉"]}},"S09":{"name":"소드 9","number":9,"arcana":"minor","suit":"swords","element":"air","u":{"line":"한밤중 침대에 앉아 얼굴을 감싸 쥔, 불안과 걱정에 짓눌린 자리예요.","core":"생각이 꼬리를 물어 불안이 커지는 카드예요. 다만 그 두려움의 상당 부분은 실제보다 부풀려진 밤의 상상일 수 있어요.","mind":"지금 당신의 마음은 걱정이 꼬리를 물어, 불안과 자책에 짓눌린 상태예요.","daily":"오늘은 걱정이 밀려올 수 있어요. 상상과 사실을 나눠 적어보면 불안이 줄어들어요.","love":"관계에 대한 불안과 걱정이 커지는 시기예요. 상상으로 최악을 그리기보다 사실을 확인하세요.","people":"불안이나 자책이 관계를 흔들어요. 머릿속 걱정과 실제를 구분하는 것이 필요해요.","reunion":"불안과 후회로 잠 못 이루는 시기예요. 상상에 휘둘리지 말고 사실에 근거해 판단하세요.","career":"일에 대한 불안이나 압박이 큰 시기예요. 상상 속 최악보다 실제 상황을 점검하세요.","money":"재정 불안이 과장되게 커질 수 있어요. 막연한 걱정보다 실제 숫자를 확인하세요.","advice":"머릿속 최악의 상상과 실제를 구분하세요. 밤의 불안은 대개 아침의 사실보다 커요.","caution":"불안한 밤의 결론을 낮의 행동 기준으로 채택하지 마세요.","words":["불안","야간 사고","죄책감"]},"r":{"line":"밤이 지나 창으로 빛이 들며, 짓눌렀던 불안이 옅어지는 자리예요.","core":"짓누르던 불안이 옅어지고 회복이 시작되는 상태예요. 과장된 두려움을 자각하며 마음이 가벼워져요.","mind":"회복 초반에는 확신보다 검증 가능한 사실이 자기신뢰를 빠르게 복원해요.","daily":"오늘은 짓누르던 걱정이 가벼워져요. 스스로에게 너그러워지세요.","love":"불안이 가라앉고 관계에 대한 마음이 편해지는 시기예요. 걱정을 내려놓기 시작해요.","people":"불안이나 오해가 정리되며 관계가 편안해져요. 걱정을 덜어내세요.","reunion":"불안이 옅어지고 마음이 정리돼요. 상상에서 벗어나 현실을 볼 여유가 생겨요.","career":"압박이나 불안이 줄어드는 시기예요. 과장된 걱정을 걷고 현실을 보세요.","money":"재정 불안이 가라앉는 흐름이에요. 막연한 걱정을 덜고 차분히 관리하세요.","advice":"머릿속 가정과 확인된 사실을 분리한 뒤, 오늘 행동은 사실 기준으로만 정하세요.","caution":"불안이 줄었다고 관계 복구를 서두르면 다시 과부하가 올 수 있어요.","words":["불안 이완","현실 검증","회복 시작"]}},"S10":{"name":"소드 10","number":10,"arcana":"minor","suit":"swords","element":"air","u":{"line":"등에 여러 검이 꽂힌 채 바닥에 누운, 한 방식이 완전히 끝나버린 자리예요.","core":"생각과 긴장이 한계에 닿아, 버티던 방식이 끝나는 카드예요. 밑바닥처럼 느껴지지만 여기가 끝이라는 것은 곧 회복이 시작될 지점이라는 뜻이에요.","mind":"지금 마음은 소진과 배신감으로 바닥에 닿아, 최악의 생각까지 스치는 힘든 상태예요.","daily":"오늘은 무리하지 말고 회복에 집중하세요. 멈춰야 할 것을 멈추는 것이 재기의 시작이에요.","love":"관계의 한 방식이 소진되어 끝에 다다른 시기예요. 억지로 되살리기보다 끝난 것을 인정하고 회복 공간을 확보하세요.","people":"지치고 상처받아 더 버티기 어려운 상태예요. 무리한 재시작보다 중단과 회복을 먼저 받아들여야 해요.","reunion":"끝난 패턴을 억지로 되살리면 소진과 상처가 반복돼요. 지금은 다시 밀어붙일 때가 아니라 회복이 먼저예요.","career":"한 방식이나 프로젝트가 소진되어 끝나는 시기예요. 무리한 재시작보다 손실을 확정하고 회복 공간을 확보하세요.","money":"재정적으로 바닥을 친 느낌일 수 있어요. 없는 자원을 있는 것처럼 계산하지 말고 손실을 인정하는 것이 먼저예요.","advice":"끝난 것을 억지로 붙들지 마세요. 중단·회복·손실 확정을 먼저 받아들이고, 몸과 일정의 회복 시간을 확보하세요.","caution":"끝난 패턴을 무리하게 되살리면, 소진과 상처만 반복돼요.","words":["종결","소진","바닥"]},"r":{"line":"바닥에 누워 있던 몸을 조심스레 일으켜, 회복이 시작되는 자리예요.","core":"소드 10 역행은 최악의 바닥을 지나 서서히 회복이 시작되는 상태예요. 다만 아직 기력이 약하니, 급하게 밀어붙이면 다시 주저앉을 수 있어요.","mind":"지금 마음은 바닥을 지나 조금씩 기운을 되찾고 있지만, 여전히 조심스럽고 약한 상태예요.","daily":"오늘은 회복에 집중하되, 무리하지 마세요. 서서히 일어나는 지금 페이스를 지키는 것이 중요해요.","love":"힘든 시기를 지나 관계나 마음이 서서히 회복되는 흐름이에요. 조급하지 않게 천천히 기운을 되찾으세요.","people":"바닥을 지나 회복이 시작돼요. 다만 아직 상처가 아무는 중이니 무리한 기대는 삼가세요.","reunion":"최악은 지났고 회복의 여지가 생겨요. 서두르지 말고 천천히 다가가야 다시 주저앉지 않아요.","career":"소진된 상태에서 서서히 재기하는 시기예요. 무리한 확장보다 천천히 기반을 회복하세요.","money":"바닥을 지나 재정이 서서히 회복돼요. 조급한 만회 시도보다 안정적인 회복이 우선이에요.","advice":"최악은 지났어요. 서서히 회복하되 급하게 밀어붙이지 말고, 몸과 마음의 기력을 먼저 되찾으세요.","caution":"회복 초기에 무리하면, 겨우 일어난 몸이 다시 주저앉을 수 있어요.","words":["회복 시작","재기","서서히 일어남"]}},"S11":{"name":"소드 페이지","number":11,"arcana":"minor","suit":"swords","element":"air","u":{"line":"바람 부는 언덕에서 검을 든 채 사방을 예리하게 살피는, 호기심과 관찰의 자리예요.","core":"예리한 호기심으로 새로운 것을 탐구하는 카드예요. 날카로운 관찰과 소통으로 정보를 모으며, 진실을 파고드는 기민함이 있어요.","mind":"지금 당신의 마음은 예리하고 기민해, 새로운 것을 파고들고 소통하려는 상태예요.","daily":"오늘은 호기심을 살려 새로운 것을 배우거나 소통하기 좋은 날이에요.","love":"상대를 알아가며 관계를 탐색하는 시기예요. 솔직한 소통이 관계를 진전시켜요.","people":"호기심과 소통이 관계에 활력을 줘요. 다만 지나친 경계는 거리를 만들어요.","reunion":"관계를 예리하게 살피며 다가갈 시기예요. 솔직한 소통이 실마리가 돼요.","career":"정보 수집과 소통이 힘이 되는 시기예요. 기민하게 배우고 파악하세요.","money":"정보를 예리하게 살피면 기회가 보여요. 꼼꼼히 확인하세요.","advice":"예리한 관찰과 솔직한 소통을 살리세요. 다만 경계가 지나치면 마음이 닫혀요.","caution":"호기심이 지나쳐 남의 일을 캐거나 가십이 되지 않게 하세요.","words":["호기심","예리한 관찰","새 정보"]},"r":{"line":"예리하던 시선이 흐트러져, 말만 앞서거나 냉소로 흐르는 자리예요.","core":"예리함이 성급함이나 냉소로 흐르는 상태예요. 말만 앞서 실행이 없거나, 산만해 집중하지 못해요.","mind":"지금 마음은 산만하거나 냉소적이 되어, 말만 앞서고 집중하지 못하는 상태예요.","daily":"오늘은 말보다 실행에 무게를 두고, 성급한 판단을 삼가세요.","love":"말은 많지만 진심이 없거나, 성급한 판단으로 오해가 생겨요. 솔직함이 필요해요.","people":"냉소나 성급한 말이 관계를 상하게 해요. 말보다 진심을 담으세요.","reunion":"성급한 판단이나 말뿐인 태도가 역효과예요. 진심을 담아 신중하게 다가가세요.","career":"계획만 세우고 실행이 없거나 산만할 수 있어요. 하나에 집중하세요.","money":"성급하거나 산만한 판단을 조심하세요. 정보를 차분히 검증하세요.","advice":"말만 앞세우지 마세요. 성급한 판단과 냉소를 거두고, 진심과 실행을 담으세요.","caution":"예리함이 냉소가 되면, 사람도 기회도 멀어져요.","words":["말뿐인 계획","성급한 판단","가십"]}},"S12":{"name":"소드 기사","number":12,"arcana":"minor","suit":"swords","element":"air","u":{"line":"칼을 뽑아 든 채 폭풍을 뚫고 거침없이 돌진하는 소드 기사의 자리예요.","core":"명확한 목표를 향해 거침없이 직진하는 카드예요. 빠른 판단과 결단으로 장애를 돌파하는 추진력이 지금의 힘이에요.","mind":"지금 당신의 마음은 목표가 뚜렷해, 거침없이 밀고 나가려는 상태예요.","daily":"오늘은 명확한 목표를 향해 빠르게 움직이기 좋은 날이에요.","love":"적극적이고 직진하는 태도로 관계를 이끄는 시기예요. 분명한 의사 표현이 흐름을 만들어요.","people":"빠르고 명확한 소통이 관계를 진전시켜요. 다만 직설이 지나치면 상처가 돼요.","reunion":"명확한 의지로 다가가면 흐름을 만들 수 있어요. 다만 조급함과 진심을 구분하세요.","career":"빠른 판단과 실행으로 성과를 내는 시기예요. 명확한 목표로 돌파하세요.","money":"결단력 있는 실행이 결과를 만들어요. 다만 조급함은 경계하세요.","advice":"목표를 분명히 하고 거침없이 나아가세요. 다만 직진의 속도만큼 배려도 챙기세요.","caution":"직진에만 몰두해 주변을 무시하면, 추진력이 독선이 돼요.","words":["추진력","명확한 목표","직진"]},"r":{"line":"폭풍 속에서 방향을 잃고 제멋대로 내달리는 자리예요.","core":"추진력이 무모함이나 조급함으로 흐른 상태예요. 방향 없이 밀어붙이거나, 독선적으로 돌진해 문제를 키워요.","mind":"지금 마음은 조급함과 충동으로, 앞뒤 없이 밀어붙이려는 상태예요.","daily":"오늘은 밀어붙이기 전에 방향과 말투를 한 번 점검하세요.","love":"성급하게 밀어붙이다 관계를 그르쳐요. 직설이 지나쳐 상처를 줄 수 있어요.","people":"조급하거나 독선적인 태도가 갈등을 키워요. 속도와 말투를 조절하세요.","reunion":"조급하게 밀어붙이면 역효과예요. 방향과 진심을 먼저 정하세요.","career":"조급하거나 독선적인 실행이 문제를 키울 수 있어요. 방향을 다지세요.","money":"충동적이거나 무모한 결정을 조심하세요. 속도를 줄이고 점검하세요.","advice":"속도보다 방향이에요. 조급함과 독선을 거두고, 목표를 다시 확인한 뒤 나아가세요.","caution":"방향 없는 돌진은, 빠른 만큼 크게 어긋나요.","words":["무모함","조급함","독선"]}},"S13":{"name":"소드 퀸","number":13,"arcana":"minor","suit":"swords","element":"air","u":{"line":"칼을 곧게 세우고 흐트러짐 없이 진실을 가늠하는 소드 여왕의 자리예요.","core":"감정에 휘둘리지 않는 명석함과 독립의 카드예요. 정직한 통찰과 분명한 경계로, 진실을 가리고 자기 기준을 지켜요.","mind":"지금 당신의 마음은 명석하고 독립적이어서, 감정에 휘둘리지 않고 진실을 보려 해요.","daily":"오늘은 명확한 판단과 솔직한 소통이 좋은 흐름을 만들어요.","love":"감정에 휩쓸리지 않고 명확하게 관계를 보는 시기예요. 솔직함과 경계가 건강한 관계를 만들어요.","people":"명확한 소통과 경계가 관계를 건강하게 해요. 정직함이 신뢰를 줘요.","reunion":"감정보다 명확한 판단으로 관계를 볼 시기예요. 정직하게 마주하면 답이 보여요.","career":"명석한 판단과 독립적인 태도가 힘이 되는 시기예요. 정직함으로 신뢰를 얻으세요.","money":"냉철한 분석과 명확한 기준이 유리해요. 감정을 배제하고 판단하세요.","advice":"감정에 휩쓸리지 말고 명석하게 판단하세요. 정직함과 분명한 경계가 자신을 지켜요.","caution":"명석함이 지나쳐 차가워지면, 사람이 곁에 다가오기 어려워져요.","words":["명석함","독립","정직"]},"r":{"line":"곧던 칼이 날을 세워, 정직함이 냉정과 상처로 변한 자리예요.","core":"명석함이 냉정 과잉으로 흐른 상태예요. 날선 말이나 지나친 경계가 상처를 주거나, 감정을 차단해 고립돼요.","mind":"지금 마음은 감정을 차단하고 냉정해져, 스스로를 고립시키는 상태예요.","daily":"오늘은 날선 말을 삼가고, 마음의 문을 조금 열어보세요.","love":"냉정함이나 날선 말이 관계를 상하게 해요. 솔직함과 차가움을 구분하세요.","people":"지나친 경계나 냉담이 거리를 만들어요. 마음의 문을 조금 여세요.","reunion":"냉정하거나 방어적인 태도가 다가섬을 막아요. 마음을 조금 여세요.","career":"냉담하거나 날선 태도가 관계를 상하게 할 수 있어요. 소통에 배려를 더하세요.","money":"지나치게 냉정한 판단이 기회를 좁힐 수 있어요. 균형을 보세요.","advice":"명석함에 차가움을 섞지 마세요. 정직하되 따뜻함을 더할 때, 고립되지 않아요.","caution":"명석함에 차가움을 섞지 마세요. 정직하되 따뜻함을 더할 때, 고립되지 않아요.","words":["냉정 과잉","고립","날선 말"]}},"S14":{"name":"소드 킹","number":14,"arcana":"minor","suit":"swords","element":"air","u":{"line":"왕좌에 앉아 칼을 곧게 세우고 흔들림 없이 진실을 판별하는 소드 왕의 자리예요.","core":"논리와 원칙으로 진실을 판별하는 지적 권위의 카드예요. 공정하고 명료한 판단으로, 감정에 휘둘리지 않고 옳은 방향을 정해요.","mind":"지금 당신은 논리와 원칙으로 상황을 판단하며, 공정한 결정을 내리려 해요.","daily":"오늘은 원칙과 논리로 문제를 정리하기 좋은 날이에요.","love":"이성적이고 원칙 있는 태도로 관계를 이끄는 시기예요. 명확한 기준과 공정함이 신뢰를 줘요.","people":"논리적이고 공정한 소통이 관계를 안정시켜요. 원칙을 지키되 배려를 더하세요.","reunion":"감정보다 원칙과 진실로 관계를 볼 시기예요. 공정하게 판단하면 답이 분명해져요.","career":"논리와 권위로 문제를 해결하는 시기예요. 공정한 판단이 신뢰를 얻어요.","money":"냉철하고 원칙 있는 판단이 유리해요. 논리적으로 분석하세요.","advice":"논리와 원칙으로 공정하게 판단하세요. 다만 진실에 배려를 더할 때 권위가 신뢰가 돼요.","caution":"논리가 지나치면 냉혹해져요. 원칙에 인간적 온기를 더하세요.","words":["지적 권위","논리","공정한 판단"]},"r":{"line":"곧던 판단이 독단으로 기울어, 권위가 냉혹함으로 변한 자리예요.","core":"논리가 독단이나 냉혹함으로 흐른 상태예요. 권위를 남용하거나, 감정을 완전히 배제해 경직돼요.","mind":"지금 마음은 논리에만 매여 독단적이거나, 감정을 배제해 경직된 상태예요.","daily":"오늘은 원칙을 고집하기 전에, 상대의 감정도 한 번 헤아려 보세요.","love":"지나치게 이성적이거나 독단적인 태도가 관계를 차갑게 해요. 감정도 존중하세요.","people":"권위적이거나 냉혹한 태도가 갈등을 키워요. 논리에 배려를 더하세요.","reunion":"일방적이거나 냉정한 판단이 다가섬을 막아요. 상대의 감정을 헤아리세요.","career":"권위 남용이나 경직된 판단이 문제를 키울 수 있어요. 균형을 회복하세요.","money":"지나치게 냉혹한 판단이 기회를 좁힐 수 있어요. 유연함을 더하세요.","advice":"논리를 독단으로 밀어붙이지 마세요. 원칙에 유연함과 온기를 더할 때, 진짜 권위가 서요.","caution":"냉혹한 논리는 옳아도 사람을 잃게 만들어요.","words":["독단","냉혹함","권위 남용"]}},"P01":{"name":"펜타클 에이스","number":1,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"손바닥 위에 놓인 반짝이는 금화 하나, 풍요의 씨앗이 열리는 자리예요.","core":"손에 잡히는 현실적 기회가 열리는 카드예요. 풍요와 안정의 씨앗이 주어졌으니, 이를 현실에 심어 키울 때예요.","mind":"작은 실행의 축적은 자기효능감을 안정시키고 비교 사고를 줄여요.","daily":"오늘은 현실적인 기회나 좋은 제안이 있을 수 있어요. 놓치지 마세요.","love":"안정적이고 현실적인 관계의 시작이 열리는 시기예요. 든든한 토대 위에서 마음을 키워가세요.","people":"관계에 현실적 안정의 기반이 생겨요. 꾸준함이 든든한 결실을 만들어요.","reunion":"다시 시작할 현실적 여지가 열려요. 감정만이 아니라 안정된 기반을 함께 만드세요.","career":"새로운 기회나 안정적 시작이 열리는 시기예요. 현실적 기반을 다지세요.","money":"새로운 수입원이나 재정 기회가 열려요. 씨앗을 잘 키우면 결실이 돼요.","advice":"작은 기준 하나를 행동으로 증명해 자기신뢰의 근거를 만드세요.","caution":"회복 계획을 거대하게 잡으면 다시 미루기 패턴으로 돌아가요.","words":["현실적 시작","생활 기반","몸의 안정"]},"r":{"line":"쥐고 있던 금화가 손에서 미끄러지는, 기회가 흐려지는 자리예요.","core":"기회가 지연되거나 불안정하게 시작되는 상태예요. 준비가 부족하거나 물질에 집착해 흐름을 놓쳐요.","mind":"지금 마음은 기회를 원하면서도, 준비 부족이나 불안으로 망설이는 상태예요.","daily":"오늘은 성급한 시작보다 기본을 점검하는 편이 안전해요.","love":"관계의 시작이 불안정하거나, 현실 조건에 매여 마음이 흐려져요. 기반을 먼저 다지세요.","people":"안정의 기반이 흔들리거나 현실 문제가 관계를 눌러요. 토대를 점검하세요.","reunion":"다시 시작할 여지는 있으나 기반이 불안정해요. 조급하게 시작하지 마세요.","career":"기회가 지연되거나 준비가 부족할 수 있어요. 토대를 먼저 다지세요.","money":"재정 기회가 흐려지거나 손실 위험이 있어요. 물질에 대한 집착을 경계하세요.","advice":"큰 계획을 버리고 15분짜리 행동으로 회복 리듬을 다시 붙이세요.","caution":"한 번의 미실행을 실패로 일반화하지 마세요.","words":["기반 흔들림","실행 지연","현실 불안"]}},"P02":{"name":"펜타클 2","number":2,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"두 개의 금화를 무한대 모양으로 저글링하며 균형을 맞추는 자리예요.","core":"여러 일을 유연하게 저글링하며 균형을 잡는 카드예요. 변화 속에서도 우선순위를 조율하면, 흔들리지 않고 흐름을 탈 수 있어요.","mind":"지금 당신은 여러 일을 동시에 다루며, 균형을 잡으려 유연하게 움직이는 상태예요.","daily":"오늘은 여러 일을 저글링하기 좋은 날이에요. 우선순위를 정하고 유연하게 움직이세요.","love":"여러 상황 속에서 관계의 균형을 맞추는 시기예요. 유연하게 조율하면 흐름이 안정돼요.","people":"바쁜 와중에도 관계의 균형을 지키는 때예요. 우선순위를 조율하세요.","reunion":"여러 감정과 상황 사이에서 균형을 잡을 시기예요. 조급하지 말고 유연하게 조율하세요.","career":"여러 업무를 유연하게 조율하는 시기예요. 우선순위를 정하면 흐름을 타요.","money":"수입과 지출의 균형을 맞추는 시기예요. 유연하게 관리하세요.","advice":"변화 속에서 유연하게 균형을 잡으세요. 우선순위를 정하면 흔들리지 않아요.","caution":"너무 많은 것을 동시에 쥐면, 균형이 순식간에 무너져요.","words":["균형 잡기","유연함","우선순위"]},"r":{"line":"저글링하던 금화를 놓쳐 균형이 무너지는 자리예요.","core":"너무 많은 것을 감당하려다 균형을 잃은 상태예요. 우선순위가 엉켜 우왕좌왕하며 과부하돼요.","mind":"지금 마음은 너무 많은 것을 감당하려다 과부하되어, 우왕좌왕하는 상태예요.","daily":"오늘은 다 하려 말고, 가장 중요한 하나에 집중하세요.","love":"여러 일에 치여 관계에 소홀하거나 균형을 잃어요. 무엇이 중요한지 정하세요.","people":"감당 못 할 상황들이 관계를 흔들어요. 우선순위를 정리해야 해요.","reunion":"여러 감정에 치여 균형을 잃기 쉬워요. 무엇이 우선인지 정하세요.","career":"업무 과부하로 균형이 무너질 수 있어요. 우선순위를 정리하고 덜어내세요.","money":"수입과 지출의 균형이 무너질 수 있어요. 재정을 재정비하세요.","advice":"다 저글링하려 하지 마세요. 우선순위를 정하고, 감당 못 할 것은 내려놓으세요.","caution":"균형을 잃은 채 계속 벌이면, 결국 모두 놓치게 돼요.","words":["과부하","균형 상실","우왕좌왕"]}},"P03":{"name":"펜타클 3","number":3,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"장인이 사람들과 함께 성당을 지어 올리는, 협업과 숙련의 자리예요.","core":"각자의 실력을 모아 함께 무언가를 쌓아 올리는 카드예요. 협업과 숙련이 만나, 혼자서는 못 할 결실을 만들어내요.","mind":"지금 당신은 사람들과 협력하며, 실력을 모아 결실을 만들려는 상태예요.","daily":"오늘은 사람들과 협력하기 좋은 날이에요. 함께하면 더 큰 결과가 나와요.","love":"서로의 노력을 모아 관계를 함께 쌓아가는 시기예요. 협력하는 마음이 관계를 견고하게 해요.","people":"함께 만들어가는 과정에서 관계가 깊어져요. 서로의 몫을 인정하고 협력하세요.","reunion":"함께 다시 쌓아갈 여지가 있어요. 서로의 노력을 인정하며 협력하세요.","career":"협업과 팀워크로 성과를 만드는 시기예요. 실력을 모으면 인정받아요.","money":"협력이나 공동 작업이 재물의 기회가 돼요. 함께할 때 결실이 커요.","advice":"혼자 애쓰지 말고 실력을 모으세요. 협업과 숙련이 만나면 큰 결실이 돼요.","caution":"각자의 몫과 실력을 인정하지 않으면, 협업이 불협화음이 돼요.","words":["협업","숙련","팀워크"]},"r":{"line":"함께 짓던 건물이 삐걱대거나, 실력과 협업이 어긋나는 자리예요.","core":"협업이 부실하거나 실력이 부족한 상태예요. 손발이 안 맞거나 품질이 떨어져 결실이 흔들려요.","mind":"지금 마음은 실력이나 협업에 대한 자신감이 떨어져, 위축된 상태예요.","daily":"오늘은 손발이 안 맞을 수 있어요. 역할을 명확히 하고 조율하세요.","love":"함께 쌓아가는 노력이 어긋나거나 한쪽만 애써요. 서로의 몫을 다시 나누세요.","people":"협력이 부실해 관계가 삐걱대요. 각자의 역할을 다시 조율하세요.","reunion":"함께 다시 쌓으려 해도 손발이 안 맞아요. 무엇이 어긋났는지 봐야 해요.","career":"협업이 부실하거나 실력이 부족해 성과가 흔들릴 수 있어요. 기본기를 다지세요.","money":"공동 작업의 부실이 손실로 이어질 수 있어요. 역할과 품질을 점검하세요.","advice":"협업이 삐걱대면 역할부터 다시 나누세요. 실력이 부족하면 기본기를 다지세요.","caution":"부실한 협업을 방치하면, 함께 쌓은 것이 무너져요.","words":["협업 부실","실력 부족","불협화음"]}},"P04":{"name":"펜타클 4","number":4,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"금화를 꼭 끌어안고 놓지 않으려는, 안정과 소유의 자리예요.","core":"가진 것을 단단히 지키려는 카드예요. 안정을 다지는 힘이 되지만, 지나치면 움켜쥔 손이 새것을 받지 못하게 해요.","mind":"지금 당신의 마음은 가진 것을 지키려는 안정 욕구가 강한 상태예요.","daily":"오늘은 가진 것을 잘 지키되, 움켜쥐기만 하지 않도록 하세요.","love":"관계를 안정적으로 지키려는 시기예요. 다만 지키려는 마음이 집착이나 통제가 되지 않게 하세요.","people":"안정을 중시하는 관계예요. 지키려는 마음과 통제하려는 마음을 구분하세요.","reunion":"관계를 붙들려는 마음이 강해요. 다만 움켜쥘수록 상대가 부담을 느낄 수 있어요.","career":"안정을 지키고 다지는 시기예요. 다만 변화를 지나치게 거부하진 마세요.","money":"저축과 재정 안정에 유리한 시기예요. 다만 지나친 인색함은 경계하세요.","advice":"안정을 다지되, 움켜쥔 손을 가끔 펴세요. 지키는 것과 집착하는 것은 달라요.","caution":"지나치게 움켜쥐면, 새로운 기회와 사람이 손안에 들어오지 못해요.","words":["안정 유지","지킴","보존"]},"r":{"line":"움켜쥐던 손을 펴거나, 반대로 통제를 잃고 놓치는 자리예요.","core":"집착을 내려놓고 나누기 시작하거나, 반대로 통제를 잃는 상태예요. 움켜쥠과 흘림의 갈림길이에요.","mind":"지금 마음은 지키려는 집착을 내려놓거나, 통제를 잃을까 불안한 상태예요.","daily":"오늘은 움켜쥔 것을 조금 풀어보세요. 나눌 때 오히려 채워져요.","love":"집착을 내려놓고 여유를 찾으려는 시기예요. 통제하려는 마음을 풀면 관계가 편해져요.","people":"움켜쥐던 마음을 풀거나, 반대로 불안해 통제가 심해져요. 균형을 찾으세요.","reunion":"붙들던 마음을 내려놓으면 오히려 편해져요. 통제보다 여유를 보이세요.","career":"지나친 방어나 인색함을 풀 때예요. 나누고 투자하면 흐름이 생겨요.","money":"인색함을 풀고 나누거나 투자할 시기예요. 다만 통제 없는 지출은 조심하세요.","advice":"움켜쥔 손을 펴세요. 집착을 내려놓고 나눌 때, 안정이 오히려 커져요.","caution":"인색함을 계속 고집하면, 지키려던 것마저 마음의 짐이 돼요.","words":["집착 완화","인색함","통제 상실"]}},"P05":{"name":"펜타클 5","number":5,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"눈 내리는 밤, 불 켜진 창문 앞을 지나면서도 안으로 들어가지 못하는 결핍과 고립의 자리예요.","core":"돈·몸·관계에서 부족함과 고립감이 현실 압박으로 떠오르는 카드예요. 혼자 버티려 하기보다, 바로 옆의 도움과 지원선을 확인할 때예요.","mind":"지금 마음은 부족함과 고립감으로 위축되어, 혼자 버티려다 더 힘들어지는 상태예요.","daily":"오늘은 부족함이 크게 느껴질 수 있어요. 혼자 버티기보다 도움을 청하는 것이 지혜예요.","love":"관계에서 정서적 결핍이나 소외감을 느끼는 시기예요. 혼자 참기보다 필요한 것을 솔직히 말하는 것이 고립을 줄여요.","people":"서로 지쳐 마음의 여유가 부족한 상태예요. 없는 것을 있는 척하기보다 부족함을 인정하고 도움을 청하세요.","reunion":"결핍감이나 외로움 때문에 다시 찾는 건 아닌지 돌아보세요. 고립을 메우려는 재회는 오래가기 어려워요.","career":"자원이나 지원이 부족해 압박을 느끼는 시기예요. 혼자 떠안지 말고 도움을 요청할 사람이나 제도를 확인하세요.","money":"재정 압박이 현실로 떠올라요. 없는 자원을 있는 것처럼 계산하지 말고, 고정비와 줄일 지출부터 분리하세요.","advice":"혼자 버티지 마세요. 비용을 줄이고, 도움을 요청할 사람이나 제도를 하나 확인하며, 생활 기반부터 점검하세요.","caution":"혼자 버티거나 없는 자원을 있는 것처럼 계산하면, 결핍과 손실이 더 커져요.","words":["결핍","재정 압박","고립감"]},"r":{"line":"추위 속을 헤매다 마침내 안으로 들어갈 문을 발견하는, 회복이 시작되는 자리예요.","core":"펜타클 5 역행은 결핍과 고립에서 벗어나 회복이 시작되는 상태예요. 도움이나 출구가 보이기 시작하지만, 아직 완전히 안정되지는 않았어요.","mind":"지금 마음은 결핍에서 벗어나 조금씩 안정을 되찾고, 도움을 받아들일 여유가 생기고 있어요.","daily":"오늘은 도움이나 출구가 보이기 시작해요. 손 내미는 것을 주저하지 마세요.","love":"정서적 결핍에서 벗어나 관계가 따뜻함을 되찾는 흐름이에요. 도움을 받아들이면 고립이 풀려요.","people":"지쳤던 관계에 여유가 돌아오기 시작해요. 서로 손 내밀면 회복이 빨라져요.","reunion":"고립에서 벗어나 마음의 여유가 생기는 시기예요. 결핍을 메우려는 마음이 아니라 진짜 회복인지 확인하세요.","career":"부족했던 자원이나 지원이 채워지기 시작해요. 도움이 연결되며 압박이 줄어들어요.","money":"재정 압박이 서서히 풀리는 흐름이에요. 회수나 지원이 들어오되, 아직 안정 초기이니 관리를 이어가세요.","advice":"고립에서 벗어나고 있어요. 들어온 도움을 받아들이되, 안정 초기이니 지출 관리와 생활 기반 점검을 이어가세요.","caution":"회복이 시작됐다고 방심해 다시 혼자 떠안으면, 결핍 상태로 되돌아갈 수 있어요.","words":["회복 시작","도움 발견","고립 탈출"]}},"P06":{"name":"펜타클 6","number":6,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"저울을 들고 가진 것을 필요한 이에게 나누는, 관대함과 균형의 자리예요.","core":"가진 것을 나누고 주고받음의 균형을 이루는 카드예요.","mind":"지금 당신의 마음은 나누고 베풀거나, 도움을 주고받으며 균형을 찾으려는 상태예요.","daily":"오늘은 나누거나 도움을 주고받기 좋은 날이에요. 관대함이 순환해요.","love":"서로 주고받는 마음이 균형을 이루는 시기예요. 베풂과 받음이 조화로울 때 관계가 따뜻해져요.","people":"서로 지원하고 나누는 관계예요. 주고받음의 균형이 관계를 건강하게 해요.","reunion":"관대한 마음으로 다가가면 흐름이 열려요. 다만 일방적 베풂이 되지 않게 하세요.","career":"협력과 지원이 오가는 시기예요. 관대한 나눔이 좋은 관계와 기회를 만들어요.","money":"재물을 나누거나 지원을 주고받는 시기예요. 균형 잡힌 순환이 풍요를 불러요.","advice":"가진 것을 나누되 균형을 지키세요. 주고받음이 조화로울 때 풍요가 순환해요.","caution":"베풂이 일방적이거나 조건부가 되면, 관대함이 빚진 관계로 변질돼요.","words":["나눔","주고받음","관대함"]},"r":{"line":"저울이 한쪽으로 기울어, 나눔의 균형이 무너진 자리예요.","core":"주고받음의 균형이 무너진 상태예요. 일방적으로 베풀거나 받기만 하며, 나눔에 조건이나 불공정이 끼어들어요.","mind":"지금 마음은 일방적으로 베풀어 지치거나, 받기만 해 부담을 느끼는 상태예요.","daily":"오늘은 일방적으로 베풀거나 받기보다, 균형을 점검해 보세요.","love":"한쪽만 베풀거나 받아 관계가 불균형해져요. 주고받음의 균형을 회복하세요.","people":"일방적인 헌신이나 의존이 관계를 기울여요. 공정한 나눔이 필요해요.","reunion":"일방적으로 베풀거나 매달리면 불균형해져요. 균형 잡힌 태도가 필요해요.","career":"일방적 지원이나 불공정한 관계를 조심하세요. 균형 잡힌 협력이 필요해요.","money":"불공정한 거래나 조건부 도움을 조심하세요. 균형과 투명함이 필요해요.","advice":"나눔의 균형이 기울었다면 바로잡으세요. 일방적 베풂도 받음도 관계를 지치게 해요.","caution":"불균형한 나눔이 반복되면, 관대함이 빚과 원망으로 변해요.","words":["불공정한 나눔","일방적 베풂","조건부 도움"]}},"P07":{"name":"펜타클 7","number":7,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"가꿔온 밭의 열매를 바라보며 잠시 숨을 고르는, 인내와 점검의 자리예요.","core":"가꿔온 것이 익기를 기다리며 잠시 점검하는 카드예요. 조급하지 않게 장기적 안목으로 노력을 축적할 때 결실이 와요.","mind":"지금 당신의 마음은 노력의 결실을 기다리며, 인내하고 있는 상태예요.","daily":"오늘은 결과를 재촉하기보다, 지금까지의 과정을 점검해 보세요.","love":"관계가 무르익기를 기다리는 시기예요. 조급해하지 말고 정성을 들여 지켜보세요.","people":"관계가 자라는 과정을 인내로 지켜보는 때예요. 서두르지 않는 정성이 결실을 만들어요.","reunion":"뿌려둔 정성이 익기를 기다릴 시기예요. 조급하게 재촉하기보다 때를 기다리세요.","career":"장기적 안목으로 축적하세요.","money":"투자나 노력의 결실을 기다리는 시기예요. 조급하지 말고 장기적으로 보세요.","advice":"조급해하지 마세요. 가꿔온 것이 익는 데는 시간이 필요해요. 인내가 결실을 만들어요.","caution":"조급함에 아직 덜 익은 것을 거두면, 그동안의 정성이 헛수고가 돼요.","words":["인내","장기적 안목","중간 점검"]},"r":{"line":"익지 않은 열매 앞에서 조바심을 내거나, 헛수고를 걱정하는 자리예요.","core":"인내가 바닥나 조급해진 상태예요. 성과에 조바심 내거나, 그동안의 노력이 헛될까 불안해해요.","mind":"지금 마음은 결실을 기다리다 지쳐, 조바심과 불안에 흔들리는 상태예요.","daily":"오늘은 조바심을 내려놓고, 방향이 맞는지 차분히 점검해 보세요.","love":"결실을 재촉하다 관계를 그르치거나, 지쳐서 포기하려 해요. 조급함을 내려놓으세요.","people":"조바심이 관계를 흔들어요. 아직 익지 않았다면 기다림이 필요해요.","reunion":"조급하게 재촉하면 역효과예요. 헛수고 같아도 때를 기다려야 해요.","career":"성과에 조바심 내다 그르칠 수 있어요. 방향이 맞다면 인내가 필요해요.","money":"조급한 회수나 투자 철회가 손실이 될 수 있어요. 장기적으로 보세요.","advice":"조급함에 덜 익은 것을 거두지 마세요. 방향이 맞다면, 조금 더 인내할 때예요.","caution":"조바심에 방향까지 틀어버리면, 그동안의 축적이 무너져요.","words":["조급함","성과 조바심","헛수고 우려"]}},"P08":{"name":"펜타클 8","number":8,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"묵묵히 금화를 하나하나 새겨 실력을 연마하는, 숙련과 몰입의 자리예요.","core":"한 가지에 몰입해 실력을 갈고닦는 카드예요. 성실한 반복과 연마가 쌓여, 서서히 장인의 경지로 나아가요.","mind":"지금 당신은 한 가지에 몰입해, 실력을 갈고닦으려는 성실한 상태예요.","daily":"오늘은 한 가지에 몰입해 실력을 다지기 좋은 날이에요.","love":"관계에 정성을 들이며 꾸준히 노력하는 시기예요. 성실한 마음이 신뢰를 쌓아요.","people":"꾸준한 노력으로 관계를 다지는 때예요. 성실함이 관계를 견고하게 해요.","reunion":"정성을 들여 꾸준히 다가갈 시기예요. 성실한 진심이 마음을 움직여요.","career":"실력을 연마하고 전문성을 쌓기 좋은 시기예요. 몰입한 만큼 성장해요.","money":"꾸준한 노력이 재물로 이어지는 흐름이에요. 성실함이 안정을 만들어요.","advice":"한 가지에 몰입해 성실히 연마하세요. 꾸준한 반복이 장인의 경지를 만들어요.","caution":"몰입이 지나쳐 시야가 좁아지면, 방향을 잃은 반복이 돼요.","words":["숙련","성실한 연마","몰입"]},"r":{"line":"같은 작업을 무성의하게 반복하거나, 완벽주의에 갇힌 자리예요.","core":"연마가 매너리즘에 빠지거나 완벽주의에 갇힌 상태예요. 방향 없는 반복이나 무성의로 실력이 정체돼요.","mind":"지금 마음은 매너리즘에 빠졌거나, 완벽주의로 스스로를 옭아매는 상태예요.","daily":"오늘은 습관적 반복을 멈추고, 무엇을 위한 일인지 돌아보세요.","love":"관계에 성의가 없거나 같은 패턴만 반복해요. 진심 어린 노력이 필요해요.","people":"매너리즘에 빠져 관계가 정체돼요. 새로운 정성이 필요해요.","reunion":"형식적인 노력은 통하지 않아요. 진심을 담은 성의가 필요해요.","career":"매너리즘이나 실력 정체가 올 수 있어요. 방향을 점검하고 새롭게 몰입하세요.","money":"무성의하거나 방향 없는 노력은 결실이 없어요. 방식을 재점검하세요.","advice":"방향 없는 반복을 멈추세요. 매너리즘에서 벗어나, 무엇을 위한 연마인지 다시 세우세요.","caution":"완벽주의나 무성의 모두 실력을 정체시켜요. 방향이 핵심이에요.","words":["매너리즘","완벽주의 함정","실력 정체"]}},"P09":{"name":"펜타클 9","number":9,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"가꾼 정원에서 여유롭게 풍요를 누리는, 자족과 품격의 자리예요.","core":"스스로의 힘으로 이룬 풍요를 품격 있게 누리는 카드예요. 독립적인 성취 속에서, 혼자서도 충만한 여유를 즐겨요.","mind":"지금 당신의 마음은 스스로 이룬 것에 만족하며, 독립적인 여유를 누리는 상태예요.","daily":"오늘은 스스로 이룬 것을 여유롭게 누려보세요. 자족이 마음을 채워요.","love":"스스로 충만한 상태로 관계를 대하는 시기예요. 독립적인 여유가 오히려 매력이 돼요.","people":"서로 독립적이면서도 풍요로운 관계예요. 각자의 충만함이 관계를 여유롭게 해요.","reunion":"스스로 충만한 여유로 다가가면 매력이 돼요. 조급함 없이 품격 있게 대하세요.","career":"독립적인 성취를 이루고 여유를 누리는 시기예요. 스스로의 힘을 믿으세요.","money":"재정적 자족과 안정을 누리는 흐름이에요. 이룬 풍요를 품격 있게 누리세요.","advice":"스스로 이룬 것을 품격 있게 누리세요. 독립적인 충만함이 진짜 여유를 만들어요.","caution":"자족이 지나쳐 고립이 되지 않도록, 사람들과의 연결도 챙기세요.","words":["자족","독립","품격 있는 풍요"]},"r":{"line":"가꾼 정원이 겉만 화려하고 속은 허전한 자리예요.","core":"풍요가 공허하거나 과시로 흐르는 상태예요. 겉은 충만해 보여도 속이 허전하거나, 독립 대신 의존에 기대요.","mind":"지금 마음은 이룬 것에도 공허하거나, 홀로서기에 대한 불안이 있는 상태예요.","daily":"오늘은 겉을 꾸미기보다, 속을 채우는 것에 집중해 보세요.","love":"겉으로 여유로워 보여도 속이 허전하거나, 관계에 지나치게 의존해요. 진짜 충만함을 찾으세요.","people":"겉의 풍요 뒤에 공허함이 있거나 의존이 커져요. 스스로를 채우세요.","reunion":"겉으로 괜찮아 보여도 속이 허전할 수 있어요. 진짜 마음을 돌보세요.","career":"성취가 공허하거나 과시로 흐를 수 있어요. 진짜 만족을 점검하세요.","money":"과시성 소비나 공허한 풍요를 조심하세요. 실속 있는 자족을 찾으세요.","advice":"겉의 풍요에 속지 마세요. 과시나 의존을 내려놓고, 스스로를 진짜로 채우세요.","caution":"공허함을 과시로 덮으면, 허전함만 더 커져요.","words":["과시","공허한 풍요","의존"]}},"P10":{"name":"펜타클 10","number":10,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"여러 세대가 함께 어울리는 풍요로운 저택, 안정된 기반과 유산의 자리예요.","core":"오래도록 지속되는 풍요와 안정의 카드예요. 개인을 넘어 가정과 미래로 이어지는 든든한 기반이 완성돼요.","mind":"지금 당신의 마음은 장기적 안정과 든든한 기반을 중시하는 상태예요.","daily":"오늘은 장기적인 안정과 기반을 다지기 좋은 날이에요.","love":"관계가 장기적이고 안정된 형태로 무르익는 시기예요. 미래를 함께 그릴 든든한 기반이 생겨요.","people":"지속되는 안정과 신뢰가 관계를 든든하게 해요. 함께할 미래가 그려져요.","reunion":"안정된 미래를 함께 그릴 여지가 있어요. 든든한 기반을 보여주면 마음이 열려요.","career":"장기적 안정과 든든한 성과를 이루는 시기예요. 지속 가능한 기반을 다지세요.","money":"재정적 안정과 풍요가 오래 지속되는 흐름이에요. 든든한 기반이 완성돼요.","advice":"눈앞의 것을 넘어 오래갈 기반을 세우세요. 지속되는 안정이 진짜 풍요예요.","caution":"안정에 안주해 변화를 거부하면, 든든한 기반도 서서히 낡아가요.","words":["안정된 풍요","유산","가정의 기반"]},"r":{"line":"든든하던 저택의 토대에 금이 가거나, 유산을 두고 다투는 자리예요.","core":"안정된 기반이 흔들리는 상태예요. 재정 불안정이나 가정·관계의 갈등이 든든함을 위협해요.","mind":"지금 마음은 안정이 흔들려 불안하거나, 기반에 대한 걱정이 큰 상태예요.","daily":"오늘은 든든해 보이던 것의 토대를 한 번 점검해 보세요.","love":"관계의 안정된 기반이 흔들리거나, 미래에 대한 이견이 생겨요. 토대를 다시 점검하세요.","people":"지속되던 안정에 균열이 생겨요. 갈등을 풀고 기반을 회복하세요.","reunion":"안정된 미래를 그리기 어렵거나 이견이 커요. 기반부터 다시 봐야 해요.","career":"안정이 흔들리거나 단기적 손실이 있을 수 있어요. 기반을 재점검하세요.","money":"재정 불안정이나 예상 밖 손실을 조심하세요. 든든해 보여도 점검이 필요해요.","advice":"흔들리는 기반을 외면하지 마세요. 갈등과 불안정을 점검하고 다져야 오래가요.","caution":"안정을 과신하고 균열을 방치하면, 든든하던 기반이 무너져요.","words":["재정 불안정","가정 갈등","단기적 손실"]}},"P11":{"name":"펜타클 페이지","number":11,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"금화를 소중히 들여다보며 배움과 도전을 시작하는, 성실한 탐구자의 자리예요.","core":"새로운 것을 현실적으로 배우고 도전하는 카드예요. 화려하진 않아도 성실하게 기반을 다지며, 목표를 향해 첫걸음을 떼요.","mind":"지금 당신은 새로운 것을 배우며, 현실적 목표를 향해 성실히 시작하려는 상태예요.","daily":"오늘은 새로운 것을 배우거나 목표를 세우기 좋은 날이에요.","love":"관계를 진지하게 배우고 다져가는 시기예요. 성실한 태도가 신뢰의 기반을 만들어요.","people":"차근차근 관계를 쌓아가는 때예요. 현실적이고 성실한 마음이 관계를 다져요.","reunion":"차근차근 기반을 다지며 다가갈 시기예요. 성실한 진심이 실마리가 돼요.","career":"새 분야를 배우거나 기반을 다지기 좋은 시기예요. 현실적 목표로 시작하세요.","money":"새로운 재정 목표나 배움을 시작하는 시기예요. 차근차근 기반을 다지세요.","advice":"화려한 도약보다 성실한 첫걸음을 택하세요. 현실적 목표를 차근차근 다지세요.","caution":"배우기만 하고 실행하지 않으면, 목표가 계획으로만 남아요.","words":["배움","새 도전","현실적 목표"]},"r":{"line":"금화를 든 채 딴생각에 빠져, 시작을 미루는 자리예요.","core":"배움이나 시작을 미루는 상태예요. 비현실적 계획을 세우거나, 집중력이 부족해 목표가 흐려져요.","mind":"지금 마음은 시작하고 싶으면서도 미루거나, 목표가 흐려 산만한 상태예요.","daily":"오늘은 미루던 것을 실제로 시작해 보세요. 작게라도 첫걸음이 중요해요.","love":"관계를 진지하게 다지지 못하거나 집중하지 못해요. 성실한 태도가 필요해요.","people":"관계에 집중하지 못하거나 시작만 반복해요. 진지한 노력이 필요해요.","reunion":"진지하게 다가가지 못하거나 계획만 세워요. 성실한 실행이 필요해요.","career":"계획만 세우고 실행이 없거나 집중력이 부족할 수 있어요. 목표를 좁히세요.","money":"비현실적 계획이나 미루기를 조심하세요. 현실적 목표로 시작하세요.","advice":"계획만 세우지 말고 시작하세요. 비현실적 목표를 현실에 맞게 좁히고 실행하세요.","caution":"시작을 계속 미루면, 좋은 기회도 남의 것이 돼요.","words":["미루기","비현실적 계획","집중력 부족"]}},"P12":{"name":"펜타클 기사","number":12,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"든든한 말 위에서 서두르지 않고 묵묵히 밭을 향하는, 성실하고 꾸준한 기사의 자리예요.","core":"화려하지 않아도 꾸준하고 책임감 있게 나아가는 카드예요. 느려 보여도 성실한 걸음이 결국 가장 멀리 가요.","mind":"지금 당신은 서두르지 않고 책임감 있게, 꾸준히 나아가려는 상태예요.","daily":"오늘은 서두르지 말고 꾸준히 해야 할 일을 하세요. 성실함이 힘이 돼요.","love":"믿음직하고 꾸준한 태도로 관계를 다지는 시기예요. 성실함이 든든한 신뢰를 만들어요.","people":"안정적이고 책임감 있는 관계예요. 꾸준한 정성이 관계를 견고하게 해요.","reunion":"서두르지 않고 꾸준히 다가갈 시기예요. 성실한 진심이 신뢰를 회복해요.","career":"꾸준하고 책임감 있는 태도가 신뢰를 얻는 시기예요. 성실함이 성과가 돼요.","money":"안정적이고 꾸준한 관리가 유리해요. 성실한 축적이 안정을 만들어요.","advice":"화려함보다 꾸준함을 택하세요. 성실하고 책임감 있는 걸음이 결국 가장 멀리 가요.","caution":"꾸준함이 지나쳐 융통성을 잃으면, 성실함이 완고함이 돼요.","words":["성실함","꾸준함","책임감"]},"r":{"line":"든든하던 말이 멈춰 서, 나아가지 못하고 정체된 자리예요.","core":"꾸준함이 정체나 지루함으로 흐른 상태예요. 진전이 너무 느리거나, 완고함과 무기력에 빠져요.","mind":"지금 마음은 꾸준함이 지루해졌거나, 정체되어 무기력한 상태예요.","daily":"오늘은 늘 하던 방식에 작은 변화를 더해보세요. 정체를 푸는 계기가 돼요.","love":"관계가 정체되거나 지루해져요. 꾸준함에 새로움을 더할 필요가 있어요.","people":"안정이 지나쳐 지루하거나 정체돼요. 관계에 활력을 더하세요.","reunion":"너무 소극적이거나 정체되어 진전이 없어요. 꾸준함에 적극성을 더하세요.","career":"진전이 너무 느리거나 정체될 수 있어요. 완고함을 풀고 방식을 갱신하세요.","money":"지나치게 보수적이거나 정체된 관리를 재점검하세요. 유연함이 필요해요.","advice":"꾸준함이 정체가 되지 않게 하세요. 완고함을 풀고, 익숙한 방식에 새로움을 더하세요.","caution":"느린 진전을 방치하면, 꾸준함이 제자리걸음으로 굳어져요.","words":["정체","지루함","완고함"]}},"P13":{"name":"펜타클 퀸","number":13,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"풍요로운 정원의 왕좌에서 금화를 품고 만물을 돌보는, 현실적 풍요의 여왕 자리예요.","core":"현실적인 돌봄과 실용적 지혜로 풍요를 일구는 카드예요. 따뜻하면서도 유능하게, 자신과 주변을 든든히 챙겨요.","mind":"지금 당신은 현실적이면서도 따뜻하게, 자신과 주변을 챙기는 여유로운 상태예요.","daily":"오늘은 자신과 주변을 따뜻하게 챙기기 좋은 날이에요. 실용적 여유를 누리세요.","love":"따뜻하고 현실적인 돌봄으로 관계를 안정시키는 시기예요. 든든한 애정이 관계를 편안하게 해요.","people":"실용적 지혜와 따뜻함이 관계를 든든하게 해요. 현실적 배려가 신뢰를 줘요.","reunion":"따뜻하고 안정적인 태도로 다가가면 마음이 열려요. 현실적 배려가 신뢰를 줘요.","career":"실용적 지혜와 따뜻한 리더십이 힘이 되는 시기예요. 유능함이 신뢰를 얻어요.","money":"현실적이고 안정적인 관리로 풍요를 일구는 흐름이에요. 실용적 지혜가 유리해요.","advice":"따뜻함과 실용을 함께 살리세요. 현실적으로 챙기되, 자신을 돌보는 것도 잊지 마세요.","caution":"주변을 챙기느라 정작 자신을 소홀히 하지 않도록 하세요.","words":["현실적 돌봄","풍요","실용적 지혜"]},"r":{"line":"풍요를 나누던 여왕이 정작 자신을 돌보지 못해 지친 자리예요.","core":"돌봄의 균형이 무너진 상태예요. 자신을 소홀히 하거나, 과잉 돌봄·물질 집착으로 여유를 잃어요.","mind":"지금 마음은 남을 챙기느라 지쳤거나, 자신을 돌보지 못해 소진된 상태예요.","daily":"오늘은 남보다 자신을 먼저 돌보세요. 스스로를 채워야 여유가 생겨요.","love":"남을 챙기느라 자신을 잃거나, 지나친 돌봄이 부담이 돼요. 균형을 회복하세요.","people":"과잉 돌봄이나 자기소홀이 관계를 기울여요. 자신을 먼저 챙기세요.","reunion":"지나친 헌신이나 조급함이 부담이 돼요. 여유를 되찾은 뒤 다가가세요.","career":"과부하나 자기소홀로 지칠 수 있어요. 실용적 균형을 회복하세요.","money":"물질 집착이나 불안정한 관리를 조심하세요. 현실적 균형이 필요해요.","advice":"다 챙기려 하지 마세요. 자신을 먼저 돌보는 것이, 오래 돌보기 위한 지혜예요.","caution":"다 챙기려 하지 마세요. 자신을 먼저 돌보는 것이, 오래 돌보기 위한 지혜예요.","words":["자기소홀","과잉 돌봄","물질 집착"]}},"P14":{"name":"펜타클 킹","number":14,"arcana":"minor","suit":"pentacles","element":"earth","u":{"line":"풍요의 왕좌에서 금화를 든 채 든든하게 세상을 다스리는, 안정된 성취의 왕 자리예요.","core":"현실적 성취와 안정을 완성한 든든함의 카드예요. 책임감 있는 관리와 리더십으로, 풍요를 지키고 키워내요.","mind":"현실 증거 기반 자기평가는 외부 인정 변동성에 덜 흔들려요.","daily":"오늘은 안정된 기반 위에서 든든하게 결정하기 좋은 날이에요.","love":"든든하고 안정적인 태도로 관계를 이끄는 시기예요. 책임감 있는 애정이 신뢰를 줘요.","people":"안정과 책임이 관계를 든든하게 해요. 현실적 신뢰가 관계를 지켜요.","reunion":"든든하고 안정적인 모습을 보이면 신뢰를 회복할 수 있어요. 책임감 있게 다가가세요.","career":"안정된 성취와 리더십으로 든든한 성과를 이루는 시기예요. 책임감이 신뢰를 얻어요.","money":"재정적 안정과 풍요가 완성되는 흐름이에요. 책임 있는 관리가 든든함을 지켜요.","advice":"나를 지켜낸 데이터(시간, 지출, 루틴)를 기록해 기준을 현실화하세요.","caution":"강한 척만 하며 휴식과 도움을 거부하면 회복 탄력이 떨어져요.","words":["안정감","자기 통제","현실 자신감"]},"r":{"line":"든든하던 왕이 재물에 집착하거나 통제에 매인 자리예요.","core":"안정이 물질 집착이나 통제욕으로 흐른 상태예요. 완고함과 과욕이 든든함을 위협해요.","mind":"지금 마음은 안정을 지키려다 물질 집착이나 통제에 매인 상태예요.","daily":"오늘은 움켜쥔 통제를 조금 풀어보세요. 유연함이 안정을 지켜요.","love":"안정을 지키려는 마음이 통제나 완고함으로 흘러요. 유연함을 회복하세요.","people":"통제욕이나 완고함이 관계를 눌러요. 상대의 목소리를 들으세요.","reunion":"일방적이거나 통제적인 태도가 다가섬을 막아요. 여유를 보이세요.","career":"완고함이나 과욕이 문제를 키울 수 있어요. 통제를 풀고 균형을 회복하세요.","money":"물질 집착이나 무리한 과욕을 조심하세요. 안정과 욕심을 구분하세요.","advice":"강함을 증명하려 하지 말고 지속 가능한 기준부터 복구하세요.","caution":"완벽 통제 집착은 자존감이 아니라 불안을 강화해요.","words":["통제 피로","완고함","자원 불균형"]}}};
